  KEY `IDX_QRTZ_T_C` (`SCHED_NAME`,`CALENDAR_NAME`),
  KEY `IDX_QRTZ_T_G` (`SCHED_NAME`,`TRIGGER_GROUP`),
  KEY `IDX_QRTZ_T_STATE` (`SCHED_NAME`,`TRIGGER_STATE`),
  KEY `IDX_QRTZ_T_N_STATE` (`SCHED_NAME`,`TRIGGER_NAME`,`TRIGGER_GROUP`,`TRIGGER_STATE`),
  KEY `IDX_QRTZ_T_N_G_STATE` (`SCHED_NAME`,`TRIGGER_GROUP`,`TRIGGER_STATE`),
  KEY `IDX_QRTZ_T_NEXT_FIRE_TIME` (`SCHED_NAME`,`NEXT_FIRE_TIME`),
  KEY `IDX_QRTZ_T_NFT_ST` (`SCHED_NAME`,`TRIGGER_STATE`,`NEXT_FIRE_TIME`),
  KEY `IDX_QRTZ_T_NFT_MISFIRE` (`SCHED_NAME`,`MISFIRE_INSTR`,`NEXT_FIRE_TIME`),
  KEY `IDX_QRTZ_T_NFT_ST_MISFIRE` (`SCHED_NAME`,`MISFIRE_INSTR`,`NEXT_FIRE_TIME`,`TRIGGER_STATE`),
  KEY `IDX_QRTZ_T_NFT_ST_MISFIRE_GRP` (`SCHED_NAME`,`MISFIRE_INSTR`,`NEXT_FIRE_TIME`,`TRIGGER_GROUP`,`TRIGGER_STATE`),
  CONSTRAINT `QRTZ_TRIGGERS_ibfk_1` FOREIGN KEY (`SCHED_NAME`, `JOB_NAME`, `JOB_GROUP`) REFERENCES `QRTZ_JOB_DETAILS` (`SCHED_NAME`, `JOB_NAME`, `JOB_GROUP`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `acc_acceptance` (
  `id` bigint NOT NULL,
  `project_id` bigint NOT NULL,
  `project_task_id` bigint DEFAULT NULL,
  `execution_contract_id` bigint DEFAULT NULL,
  `acceptance_type` varchar(16) NOT NULL,
  `activity_status` varchar(16) NOT NULL DEFAULT 'PENDING',
  `current_report_version_id` bigint DEFAULT NULL,
  `version` int unsigned NOT NULL DEFAULT '0',
  `creator` varchar(64) DEFAULT '',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  `deliverable_id` bigint DEFAULT NULL,
  `origin_kind` varchar(32) NOT NULL DEFAULT 'LEGACY_TASK',
  `origin_key` varchar(190) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `origin_snapshot` json DEFAULT NULL,
  `rule_snapshot` json DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_acc_acceptance_project_type` (`tenant_id`,`project_id`,`acceptance_type`),
  UNIQUE KEY `uk_acc_acceptance_task` (`tenant_id`,`project_task_id`),
  UNIQUE KEY `uk_acc_acceptance_origin` (`tenant_id`,`origin_key`),
  KEY `idx_acceptance_deliverable` (`tenant_id`,`deliverable_id`),
  CONSTRAINT `chk_acc_acceptance_origin` CHECK ((((`origin_kind` = _utf8mb4'LEGACY_TASK') and (`project_task_id` is not null) and (`project_task_id` > 0) and (`execution_contract_id` is not null) and (`execution_contract_id` > 0)) or ((`origin_kind` = _utf8mb4'DIRECT') and (`project_task_id` is null) and (`execution_contract_id` is null) and (`deliverable_id` is null) and (`origin_key` is not null) and (`origin_snapshot` is not null) and (`rule_snapshot` is not null) and (json_type(`origin_snapshot`) = _utf8mb4'OBJECT') and (json_type(`rule_snapshot`) = _utf8mb4'OBJECT')))),
  CONSTRAINT `chk_acc_acceptance_status` CHECK ((`activity_status` in (_utf8mb4'PENDING',_utf8mb4'COMPLETED'))),
  CONSTRAINT `chk_acc_acceptance_type` CHECK ((`acceptance_type` in (_utf8mb4'PRELIMINARY',_utf8mb4'FINAL')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='初验/终验活动根';

CREATE TABLE `acc_acceptance_record` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `project_id` bigint NOT NULL COMMENT '所属项目编号',
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '验收编码，项目内唯一',
  `name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '验收名称',
  `acceptance_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PRELIMINARY' COMMENT '验收类型 PRELIMINARY 初验 / FINAL 终验',
  `acceptance_date` date DEFAULT NULL COMMENT '验收日期',
  `plan_id` bigint DEFAULT NULL COMMENT '关联交付计划编号',
  `applicant_user_id` bigint DEFAULT NULL COMMENT '申请人',
  `apply_time` datetime DEFAULT NULL COMMENT '申请时间',
  `approver_user_id` bigint DEFAULT NULL COMMENT '审批人',
  `approve_time` datetime DEFAULT NULL COMMENT '审批时间',
  `approve_opinion` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '审批意见',
  `archive_time` datetime DEFAULT NULL COMMENT '归档时间',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0草稿 1待提交 2审批中 3已通过 4已驳回 5已归档',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_pms_acc_acceptance_code` (`project_id`,`code`),
  KEY `idx_pms_acc_acceptance_project` (`project_id`),
  KEY `idx_pms_acc_acceptance_status` (`project_id`,`status`),
  KEY `idx_pms_acc_acceptance_type` (`project_id`,`acceptance_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='初验/终验';

CREATE TABLE `acc_acceptance_report_attachment` (
  `id` bigint NOT NULL,
  `report_version_id` bigint NOT NULL,
  `attachment_sequence` int unsigned NOT NULL,
  `file_artifact_id` bigint NOT NULL,
  `file_version_no` int unsigned NOT NULL,
  `reference_key` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL,
  `artifact_version` int unsigned NOT NULL,
  `reference_version` int unsigned NOT NULL,
  `availability_version` int unsigned NOT NULL,
  `scope_version` bigint NOT NULL,
  `file_hash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `creator` varchar(64) DEFAULT '',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_acc_report_attachment_seq` (`tenant_id`,`report_version_id`,`attachment_sequence`),
  UNIQUE KEY `uk_acc_report_attachment_ref` (`tenant_id`,`report_version_id`,`reference_key`),
  UNIQUE KEY `uk_acc_report_attachment_file` (`tenant_id`,`report_version_id`,`file_artifact_id`,`file_version_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='验收报告有序附件公共事实';

CREATE TABLE `acc_acceptance_report_version` (
  `id` bigint NOT NULL,
  `acceptance_id` bigint NOT NULL,
  `report_version_no` int unsigned NOT NULL,
  `report_status` varchar(16) NOT NULL,
  `acceptance_time` datetime(3) DEFAULT NULL,
  `conclusion_code` varchar(32) DEFAULT NULL,
  `conclusion_text` text,
  `acceptor_name` varchar(128) DEFAULT NULL,
  `previous_version_id` bigint DEFAULT NULL,
  `effective_from` datetime(3) DEFAULT NULL,
  `effective_to` datetime(3) DEFAULT NULL,
  `current_marker` tinyint GENERATED ALWAYS AS ((case when ((`report_status` = _utf8mb4'EFFECTIVE') and (`effective_to` is null)) then 1 else NULL end)) STORED,
  `uploader_user_id` bigint DEFAULT NULL,
  `upload_time` datetime(3) DEFAULT NULL,
  `publisher_user_id` bigint DEFAULT NULL,
  `creator` varchar(64) DEFAULT '',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  `acceptance_rule_snapshot` json DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_acc_report_version` (`tenant_id`,`acceptance_id`,`report_version_no`),
  UNIQUE KEY `uk_acc_report_current` (`tenant_id`,`acceptance_id`,`current_marker`),
  CONSTRAINT `chk_acc_report_dates` CHECK (((`effective_to` is null) or (`effective_to` >= `effective_from`))),
  CONSTRAINT `chk_acc_report_status` CHECK ((`report_status` in (_utf8mb4'DRAFT',_utf8mb4'EFFECTIVE',_utf8mb4'SUPERSEDED',_utf8mb4'REVOKED')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='不可变验收报告版本';

CREATE TABLE `acc_acceptance_scope_binding` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `project_id` bigint NOT NULL,
  `project_stage_snapshot_id` bigint NOT NULL,
  `delivery_scope_id` bigint NOT NULL,
  `scope_allocation_version` bigint NOT NULL,
  `binding_trigger` varchar(32) NOT NULL,
  `binding_status` varchar(32) NOT NULL,
  `effective_from` datetime(3) NOT NULL,
  `effective_to` datetime(3) DEFAULT NULL,
  `acceptance_fact_version` int unsigned NOT NULL DEFAULT '1',
  `version` int unsigned NOT NULL DEFAULT '0',
  `creator` varchar(64) NOT NULL DEFAULT '',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) NOT NULL DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `deleted` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_acceptance_scope_binding` (`tenant_id`,`project_id`,`project_stage_snapshot_id`,`delivery_scope_id`,`scope_allocation_version`),
  KEY `idx_acceptance_scope_current` (`tenant_id`,`delivery_scope_id`,`effective_to`,`binding_status`),
  CONSTRAINT `chk_acceptance_scope_deleted` CHECK ((`deleted` in (0,1))),
  CONSTRAINT `chk_acceptance_scope_status` CHECK ((`binding_status` = _utf8mb4'LOCKED')),
  CONSTRAINT `chk_acceptance_scope_trigger` CHECK ((`binding_trigger` in (_utf8mb4'PROJECT_STAGE_ENTRY',_utf8mb4'SCOPE_VERSION_EFFECTIVE')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='ACC验收范围锁定事实';

CREATE TABLE `acc_archive_document` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `project_id` bigint NOT NULL COMMENT '所属项目编号',
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '归档文档编码，项目内唯一',
  `name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '归档文档名称',
  `document_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ACCEPTANCE' COMMENT '文档类型 ACCEPTANCE 验收 / BUSINESS 业务 / TECHNICAL 技术 / FINANCE 财务 / OTHER 其他',
  `document_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '文档附件地址',
  `version_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '文档版本号',
  `archive_user_id` bigint DEFAULT NULL COMMENT '归档人',
  `archive_time` datetime DEFAULT NULL COMMENT '归档时间',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0草稿 1待归档 2已归档',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_pms_acc_archive_document_code` (`project_id`,`code`),
  KEY `idx_pms_acc_archive_document_project` (`project_id`),
  KEY `idx_pms_acc_archive_document_status` (`project_id`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='交付资料归档';

CREATE TABLE `acc_closure_gate_snapshot` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `project_id` bigint NOT NULL,
  `project_version` int NOT NULL,
  `tree_version` bigint NOT NULL,
  `from_stage` varchar(32) NOT NULL,
  `closure_type` varchar(32) NOT NULL,
  `rule_revision` int NOT NULL,
  `passed` bit(1) NOT NULL,
  `evidence` json NOT NULL COMMENT 'Immutable check results',
  `source_vector` json NOT NULL COMMENT 'Immutable source identity and version vector',
  `source_digest` char(64) NOT NULL,
  `checked_by` bigint NOT NULL,
  `checked_at` datetime(3) NOT NULL,
  `creator` varchar(64) NOT NULL DEFAULT '',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) NOT NULL DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  KEY `idx_acc_closure_snapshot_latest` (`tenant_id`,`project_id`,`checked_at`,`id`),
  CONSTRAINT `ck_acc_closure_snapshot_policy` CHECK (((`closure_type` = _utf8mb4'NORMAL') and (`rule_revision` = 1)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `acc_closure_review` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `application_id` bigint NOT NULL,
  `project_id` bigint NOT NULL,
  `process_instance_id` varchar(128) NOT NULL,
  `process_definition_id` varchar(128) NOT NULL,
  `task_id` varchar(128) NOT NULL,
  `task_definition_key` varchar(128) NOT NULL,
  `reviewer_user_id` bigint NOT NULL,
  `outcome` varchar(32) NOT NULL,
  `reason` varchar(2048) DEFAULT NULL,
  `reviewed_at` datetime(3) NOT NULL,
  `creator` varchar(64) NOT NULL DEFAULT '',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) NOT NULL DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_acc_closure_review_task` (`tenant_id`,`application_id`,`task_id`),
  KEY `idx_acc_closure_review_application` (`tenant_id`,`application_id`),
  CONSTRAINT `ck_acc_closure_review_outcome` CHECK ((`outcome` in (_utf8mb4'APPROVE',_utf8mb4'REJECT',_utf8mb4'CANCEL')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `acc_completion_certificate` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `project_id` bigint NOT NULL COMMENT '所属项目编号',
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '完工证明编码，项目内唯一',
  `name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '完工证明名称',
  `certificate_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '证明编号（业务编号）',
  `service_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工程服务类型：工程实施/工程督导',
  `engineer_user_id` bigint DEFAULT NULL COMMENT '迪普工程师用户编号',
  `engineer_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '迪普工程师姓名（落证时快照）',
  `engineer_contact` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '迪普工程师联系方式',
  `customer_unit` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户单位',
  `contract_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '合同号',
  `item_arrival` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工程服务内容① 完成到货验收：是/否/不涉及',
  `item_install` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工程服务内容② 完成设备硬件安装和软件调测：是/否/不涉及',
  `item_cutover` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工程服务内容③ 完成业务上线/割接且业务测试正常：是/否/不涉及',
  `item_training` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工程服务内容④ 完成产品维护现场讲解和培训：是/否/不涉及',
  `item_docs` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工程服务内容⑤ 工程文档、帐号密码已移交并协助修改：是/否/不涉及',
  `customer_sign_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '甲方签章图片地址',
  `customer_sign_date` date DEFAULT NULL COMMENT '甲方签章日期',
  `vendor_sign_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '服务方签章图片地址',
  `vendor_sign_date` date DEFAULT NULL COMMENT '服务方签章日期',
  `customer_id` bigint DEFAULT NULL COMMENT '客户编号',
  `completion_date` date DEFAULT NULL COMMENT '完工日期',
  `customer_confirm_user_id` bigint DEFAULT NULL COMMENT '客户确认人',
  `customer_confirm_time` datetime DEFAULT NULL COMMENT '客户确认时间',
  `archive_time` datetime DEFAULT NULL COMMENT '归档时间',
  `reject_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '驳回原因',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '完工证明内容',
  `attachment_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '附件地址',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0草稿 1待客户确认 2客户已确认 3已归档 4已驳回',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  `satisfaction_template_id` bigint DEFAULT NULL,
  `completion_print_template_id` bigint DEFAULT NULL,
  `completion_print_revision_id` bigint DEFAULT NULL,
  `completion_print_snapshot` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `satisfaction_print_template_id` bigint DEFAULT NULL,
  `satisfaction_print_revision_id` bigint DEFAULT NULL,
  `satisfaction_print_snapshot` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `manual_arrival_date` date DEFAULT NULL COMMENT '无签收记录时手填到货日期',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_pms_acc_completion_certificate_code` (`project_id`,`code`),
  KEY `idx_pms_acc_completion_certificate_project` (`project_id`),
  KEY `idx_pms_acc_completion_certificate_status` (`project_id`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='电子完工证明';

CREATE TABLE `acc_completion_certificate_device` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `certificate_id` bigint NOT NULL COMMENT '完工证明编号',
  `device_type` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '设备类型',
  `device_model` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '设备型号',
  `quantity` int NOT NULL DEFAULT '1' COMMENT '数量',
  `sort` int NOT NULL DEFAULT '0' COMMENT '展示顺序',
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_acc_cert_device_certificate` (`certificate_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='电子完工证明设备明细';

CREATE TABLE `acc_completion_pdf_binding` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint NOT NULL,
  `certificate_id` bigint NOT NULL,
  `certificate_version` bigint NOT NULL,
  `document_kind` varchar(16) NOT NULL,
  `layout_key` char(32) NOT NULL,
  `material_id` bigint NOT NULL,
  `version` bigint NOT NULL DEFAULT '0',
  `creator` varchar(64) DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_completion_pdf_identity` (`tenant_id`,`certificate_id`,`certificate_version`,`document_kind`,`layout_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `acc_completion_satisfaction_bundle` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `project_id` bigint NOT NULL,
  `certificate_id` bigint NOT NULL,
  `certificate_version` bigint NOT NULL,
  `collection_key` varchar(200) NOT NULL,
  `certificate_snapshot` longtext NOT NULL,
  `version` bigint NOT NULL DEFAULT '0',
  `creator` varchar(64) NOT NULL DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) NOT NULL DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_completion_bundle_certificate` (`tenant_id`,`certificate_id`),
  UNIQUE KEY `uk_completion_bundle_collection` (`tenant_id`,`collection_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `acc_completion_satisfaction_signing` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `bundle_id` bigint NOT NULL,
  `questionnaire_id` bigint NOT NULL,
  `response_id` bigint NOT NULL,
  `grant_id` bigint NOT NULL,
  `signature_file_fact` longtext NOT NULL,
  `signed_at` datetime NOT NULL,
  `version` bigint NOT NULL DEFAULT '0',
  `creator` varchar(64) NOT NULL DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) NOT NULL DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `signature_image_data_url` longtext,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_completion_signing_response` (`tenant_id`,`response_id`),
  KEY `idx_completion_signing_bundle` (`tenant_id`,`bundle_id`,`signed_at`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `acc_deliverable_checklist` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `project_id` bigint NOT NULL COMMENT '所属项目编号',
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '交付件编码，项目内唯一',
  `name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '交付件名称',
  `acceptance_id` bigint DEFAULT NULL COMMENT '关联验收编号',
  `deliverable_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'REQUIRED' COMMENT '交付件类型 REQUIRED 必交 / OPTIONAL 选交 / CONDITIONAL 条件',
  `deliverable_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '交付件附件地址',
  `check_user_id` bigint DEFAULT NULL COMMENT '检查人',
  `check_time` datetime DEFAULT NULL COMMENT '检查时间',
  `check_result` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '检查结果',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0草稿 1已提交 2已通过 3已驳回',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_pms_acc_deliverable_checklist_code` (`project_id`,`code`),
  KEY `idx_pms_acc_deliverable_checklist_project` (`project_id`),
  KEY `idx_pms_acc_deliverable_checklist_acceptance` (`acceptance_id`),
  KEY `idx_pms_acc_deliverable_checklist_status` (`project_id`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='交付件完整性检查';

CREATE TABLE `acc_project_closure` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `project_id` bigint NOT NULL,
  `snapshot_id` bigint NOT NULL,
  `closure_type` varchar(32) NOT NULL,
  `rule_revision` int NOT NULL,
  `from_stage` varchar(32) NOT NULL,
  `project_version` int NOT NULL,
  `tree_version` bigint NOT NULL,
  `status` varchar(32) NOT NULL,
  `applicant_user_id` bigint NOT NULL,
  `service_manager_user_id` bigint NOT NULL,
  `reviewer_user_id` bigint NOT NULL,
  `process_definition_key` varchar(128) NOT NULL,
  `process_definition_id` varchar(128) NOT NULL,
  `process_instance_id` varchar(128) NOT NULL,
  `business_key` varchar(128) NOT NULL,
  `process_evidence` json NOT NULL COMMENT 'Immutable actual BPM definition/tasks/candidates evidence',
  `submitted_at` datetime(3) NOT NULL,
  `decided_at` datetime(3) DEFAULT NULL,
  `version` int NOT NULL DEFAULT '0',
  `active_marker` int GENERATED ALWAYS AS ((case when (`status` = _utf8mb4'IN_REVIEW') then 1 else NULL end)) STORED,
  `creator` varchar(64) NOT NULL DEFAULT '',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) NOT NULL DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_acc_closure_snapshot` (`tenant_id`,`snapshot_id`),
  UNIQUE KEY `uk_acc_closure_process` (`tenant_id`,`process_instance_id`),
  UNIQUE KEY `uk_acc_closure_active` (`tenant_id`,`project_id`,`active_marker`),
  KEY `idx_acc_closure_latest` (`tenant_id`,`project_id`,`submitted_at`,`id`),
  CONSTRAINT `ck_acc_closure_status` CHECK ((`status` in (_utf8mb4'IN_REVIEW',_utf8mb4'APPROVED',_utf8mb4'REJECTED',_utf8mb4'CANCELLED'))),
  CONSTRAINT `ck_acc_closure_type` CHECK (((`closure_type` = _utf8mb4'NORMAL') and (`rule_revision` = 1)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `acc_project_closure_record` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `project_id` bigint NOT NULL COMMENT '所属项目编号',
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '闭环编码，项目内唯一',
  `name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '闭环名称',
  `closure_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'NORMAL' COMMENT '闭环类型 NORMAL 正常闭环 / CONDITIONAL 带条件移交',
  `applicant_user_id` bigint DEFAULT NULL COMMENT '申请人',
  `apply_time` datetime DEFAULT NULL COMMENT '申请时间',
  `approver_user_id` bigint DEFAULT NULL COMMENT '审批人',
  `approve_time` datetime DEFAULT NULL COMMENT '审批时间',
  `approve_opinion` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '审批意见',
  `legacy_issue_summary` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '遗留问题摘要',
  `archive_time` datetime DEFAULT NULL COMMENT '归档时间',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0草稿 1待审批 2审批中 3已通过 4已驳回 5已归档',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_pms_acc_project_closure_code` (`project_id`,`code`),
  KEY `idx_pms_acc_project_closure_project` (`project_id`),
  KEY `idx_pms_acc_project_closure_status` (`project_id`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目闭环审批';

CREATE TABLE `acc_project_deliverable` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `project_id` bigint NOT NULL COMMENT '项目ID',
  `deliverable_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(128) NOT NULL,
  `stage_code` varchar(32) NOT NULL,
  `task_code` varchar(64) DEFAULT NULL,
  `required` bit(1) NOT NULL DEFAULT b'1',
  `source_definition_id` bigint DEFAULT NULL,
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'PENDING' COMMENT '状态',
  `current_source_version_id` bigint DEFAULT NULL,
  `archive_status` varchar(32) DEFAULT NULL,
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '创建人',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '更新人',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '删除标志：0否，1是',
  `deleted_time` datetime(3) DEFAULT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户ID',
  `active_deliverable_code` varchar(64) GENERATED ALWAYS AS ((case when (`deleted` = 0) then `deliverable_code` else NULL end)) VIRTUAL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_acc_project_deliverable` (`tenant_id`,`project_id`,`active_deliverable_code`),
  KEY `idx_acc_project_deliverable_stage` (`tenant_id`,`project_id`,`stage_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='ACC拥有的项目交付件实例';

CREATE TABLE `acc_project_deliverable_source_attachment` (
  `id` bigint NOT NULL,
  `deliverable_source_version_id` bigint NOT NULL,
  `attachment_sequence` int unsigned NOT NULL,
  `file_artifact_id` bigint NOT NULL,
  `file_version_no` int unsigned NOT NULL,
  `reference_key` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL,
  `artifact_version` int unsigned NOT NULL,
  `reference_version` int unsigned NOT NULL,
  `availability_version` int unsigned NOT NULL,
  `scope_version` bigint NOT NULL,
  `file_hash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `creator` varchar(64) DEFAULT '',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_acc_deliverable_source_attachment_seq` (`tenant_id`,`deliverable_source_version_id`,`attachment_sequence`),
  UNIQUE KEY `uk_acc_deliverable_source_attachment_ref` (`tenant_id`,`deliverable_source_version_id`,`reference_key`),
  UNIQUE KEY `uk_acc_deliverable_source_attachment_file` (`tenant_id`,`deliverable_source_version_id`,`file_artifact_id`,`file_version_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='应交件来源有序附件公共事实';

CREATE TABLE `acc_project_deliverable_source_version` (
  `id` bigint NOT NULL,
  `deliverable_id` bigint NOT NULL,
  `source_requirement_id` varchar(32) NOT NULL,
  `source_object_type` varchar(64) NOT NULL,
  `source_object_id` bigint NOT NULL,
  `source_version` int unsigned NOT NULL,
  `relation_status` varchar(16) NOT NULL,
  `archive_status` varchar(32) NOT NULL,
  `archive_failure_code` varchar(64) DEFAULT NULL,
  `archive_retry_count` int unsigned NOT NULL DEFAULT '0',
  `archive_time` datetime(3) DEFAULT NULL,
  `current_marker` tinyint GENERATED ALWAYS AS ((case when (`relation_status` = _utf8mb4'CURRENT') then 1 else NULL end)) STORED,
  `creator` varchar(64) DEFAULT '',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_acc_deliverable_source_version` (`tenant_id`,`deliverable_id`,`source_object_type`,`source_object_id`,`source_version`),
  UNIQUE KEY `uk_acc_deliverable_source_current` (`tenant_id`,`deliverable_id`,`current_marker`),
  CONSTRAINT `chk_acc_deliverable_source_relation` CHECK ((`relation_status` in (_utf8mb4'CURRENT',_utf8mb4'SUPERSEDED',_utf8mb4'REVOKED')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='应交件只追加来源版本';

CREATE TABLE `acc_project_deliverable_submission` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `project_id` bigint NOT NULL,
  `deliverable_id` bigint NOT NULL,
  `plan_version_id` bigint NOT NULL,
  `source_version_id` bigint NOT NULL,
  `request_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `request_payload` json NOT NULL,
  `configuration_snapshot` json NOT NULL,
  `source_type` varchar(32) NOT NULL,
  `source_evidence` json NOT NULL,
  `decision_evidence` json NOT NULL,
  `creator` varchar(64) NOT NULL,
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_acc_deliverable_submission_request` (`tenant_id`,`deliverable_id`,`request_key`),
  UNIQUE KEY `uk_acc_deliverable_submission_source` (`tenant_id`,`source_version_id`),
  KEY `idx_acc_deliverable_submission_history` (`tenant_id`,`project_id`,`deliverable_id`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='模板交付件提交原始证据，只追加';

CREATE TABLE `acc_satisfaction_access_grant` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '0',
  `questionnaire_id` bigint NOT NULL,
  `grant_version` int NOT NULL,
  `token_digest` char(64) NOT NULL,
  `effective_from` datetime(3) NOT NULL,
  `expires_at` datetime(3) NOT NULL,
  `grant_status` varchar(32) NOT NULL,
  `consumed_at` datetime(3) DEFAULT NULL,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) DEFAULT NULL,
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) DEFAULT NULL,
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `completion_bundle_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_acc_sat_grant_digest` (`tenant_id`,`token_digest`),
  UNIQUE KEY `uk_acc_sat_grant_version` (`tenant_id`,`questionnaire_id`,`grant_version`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='满意度受控访问授权';

CREATE TABLE `acc_satisfaction_collection_task` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '0',
  `project_id` bigint NOT NULL COMMENT '项目逻辑引用',
  `project_task_id` bigint DEFAULT NULL,
  `source_owner_context` varchar(32) NOT NULL,
  `source_object_type` varchar(64) NOT NULL,
  `source_object_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '来源对象逻辑引用',
  `source_object_version` bigint NOT NULL COMMENT '冻结来源业务对象版本',
  `trigger_owner_context` varchar(32) NOT NULL,
  `trigger_object_type` varchar(64) NOT NULL,
  `trigger_fact_id` varchar(128) NOT NULL,
  `trigger_fact_version` bigint NOT NULL,
  `collection_key` varchar(128) NOT NULL,
  `task_revision_no` int NOT NULL COMMENT '整改重收任务序号',
  `prior_task_id` bigint DEFAULT NULL COMMENT '整改前序满意度任务逻辑引用',
  `assigned_to_user_id` bigint DEFAULT NULL,
  `assigned_by_user_id` bigint DEFAULT NULL,
  `task_status` varchar(32) NOT NULL,
  `questionnaire_id` bigint DEFAULT NULL,
  `result_id` bigint DEFAULT NULL,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) DEFAULT NULL,
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) DEFAULT NULL,
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `deliverable_id` bigint DEFAULT NULL COMMENT 'Frozen deliverable instance identity',
  `origin_kind` varchar(24) NOT NULL DEFAULT 'LEGACY_TASK',
  `origin_key` varchar(191) DEFAULT NULL,
  `origin_snapshot` json DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_acc_sat_task_revision` (`tenant_id`,`collection_key`,`task_revision_no`),
  UNIQUE KEY `uk_acc_sat_task_trigger` (`tenant_id`,`project_task_id`,`trigger_owner_context`,`trigger_object_type`,`trigger_fact_id`,`trigger_fact_version`),
  UNIQUE KEY `uk_acc_sat_direct_origin` (`tenant_id`,`origin_kind`,`origin_key`),
  KEY `idx_acc_sat_task_project` (`tenant_id`,`project_id`,`task_status`),
  KEY `idx_satisfaction_task_deliverable` (`tenant_id`,`deliverable_id`),
  CONSTRAINT `chk_acc_sat_origin` CHECK ((((`origin_kind` = _utf8mb4'LEGACY_TASK') and (`project_task_id` is not null)) or ((`origin_kind` = _utf8mb4'DIRECT') and (`project_task_id` is null) and (`deliverable_id` is null) and (`origin_key` is not null) and (`origin_snapshot` is not null))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='满意度采集任务';

CREATE TABLE `acc_satisfaction_questionnaire` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '0',
  `collection_task_id` bigint NOT NULL,
  `template_id` bigint NOT NULL COMMENT '问卷模板逻辑引用',
  `template_revision_id` bigint NOT NULL,
  `template_version` int NOT NULL,
  `frozen_question_json` json NOT NULL COMMENT '冻结题目、必答项与分值规则',
  `frozen_threshold` decimal(7,2) NOT NULL,
  `rule_version` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '冻结满意度规则版本',
  `questionnaire_status` varchar(32) NOT NULL,
  `access_scope_version` bigint NOT NULL,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) DEFAULT NULL,
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) DEFAULT NULL,
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_acc_sat_questionnaire_task` (`tenant_id`,`collection_task_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='满意度冻结问卷';

CREATE TABLE `acc_satisfaction_questionnaire_template` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '0',
  `template_code` varchar(64) NOT NULL,
  `name` varchar(128) NOT NULL,
  `status` varchar(32) NOT NULL,
  `current_revision_id` bigint DEFAULT NULL,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) DEFAULT NULL,
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) DEFAULT NULL,
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_acc_sat_template_code` (`tenant_id`,`template_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='满意度问卷模板根';

CREATE TABLE `acc_satisfaction_questionnaire_template_revision` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '0',
  `template_id` bigint NOT NULL,
  `revision_no` int NOT NULL,
  `project_type` varchar(64) NOT NULL,
  `signing_mode` varchar(64) NOT NULL,
  `implementation_mode` varchar(64) NOT NULL,
  `business_purpose_code` varchar(64) NOT NULL,
  `applicable_timing_code` varchar(64) NOT NULL,
  `priority` int NOT NULL DEFAULT '0',
  `frozen_question_json` json NOT NULL,
  `frozen_threshold` decimal(7,2) NOT NULL,
  `rule_version` varchar(64) NOT NULL,
  `revision_status` varchar(32) NOT NULL,
  `effective_from` datetime(3) DEFAULT NULL,
  `effective_to` datetime(3) DEFAULT NULL,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) DEFAULT NULL,
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) DEFAULT NULL,
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_acc_sat_template_revision` (`tenant_id`,`template_id`,`revision_no`),
  KEY `idx_acc_sat_template_match` (`tenant_id`,`project_type`,`signing_mode`,`implementation_mode`,`business_purpose_code`,`applicable_timing_code`,`revision_status`,`priority`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='满意度问卷模板不可变修订';

CREATE TABLE `acc_satisfaction_remediation_fact` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '0',
  `prior_result_id` bigint NOT NULL,
  `remediation_revision_no` int NOT NULL,
  `remediation_request_id` varchar(128) NOT NULL,
  `evidence_summary` varchar(1000) NOT NULL,
  `evidence_file_fact_version` varchar(256) DEFAULT NULL,
  `completed_by` bigint NOT NULL,
  `completed_at` datetime(3) NOT NULL,
  `fact_version` bigint NOT NULL,
  `creator` varchar(64) DEFAULT NULL,
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_acc_sat_remediation_revision` (`tenant_id`,`prior_result_id`,`remediation_revision_no`),
  UNIQUE KEY `uk_acc_sat_remediation_request` (`tenant_id`,`prior_result_id`,`remediation_request_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='满意度整改不可变事实';

CREATE TABLE `acc_satisfaction_response` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '0',
  `questionnaire_id` bigint NOT NULL COMMENT '问卷实例逻辑引用',
  `response_no` int NOT NULL,
  `request_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '提交幂等键',
  `submit_channel` varchar(32) NOT NULL,
  `customer_contact_ref` varchar(128) NOT NULL,
  `assisted_by_user_id` bigint DEFAULT NULL,
  `answer_snapshot` json NOT NULL,
  `submitted_at` datetime(3) NOT NULL,
  `creator` varchar(64) DEFAULT NULL,
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_acc_sat_response_no` (`tenant_id`,`questionnaire_id`,`response_no`),
  UNIQUE KEY `uk_acc_sat_response_request` (`tenant_id`,`questionnaire_id`,`request_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='满意度不可变答卷';

CREATE TABLE `acc_satisfaction_response_file` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '0',
  `response_id` bigint NOT NULL,
  `file_role` varchar(32) NOT NULL,
  `file_sequence` int NOT NULL,
  `artifact_id` bigint NOT NULL,
  `version_no` int NOT NULL,
  `reference_key` varchar(128) NOT NULL,
  `artifact_version` int NOT NULL,
  `reference_version` int NOT NULL,
  `availability_version` int NOT NULL,
  `scope_version` bigint NOT NULL,
  `file_hash` char(64) NOT NULL,
  `creator` varchar(64) DEFAULT NULL,
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_acc_sat_response_file_seq` (`tenant_id`,`response_id`,`file_role`,`file_sequence`),
  CONSTRAINT `chk_acc_sat_response_file_role` CHECK ((`file_role` in (_utf8mb4'SIGNATURE',_utf8mb4'ATTACHMENT')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='满意度答卷公共文件事实';

CREATE TABLE `acc_satisfaction_result` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '0',
  `collection_task_id` bigint NOT NULL,
  `questionnaire_id` bigint NOT NULL COMMENT '问卷实例逻辑引用',
  `response_id` bigint NOT NULL COMMENT '答卷逻辑引用',
  `collection_key` varchar(128) NOT NULL,
  `result_version` int NOT NULL,
  `score` decimal(7,2) NOT NULL,
  `threshold` decimal(7,2) NOT NULL,
  `passed` bit(1) NOT NULL,
  `rule_version` varchar(64) NOT NULL,
  `result_status` varchar(32) NOT NULL,
  `effective_from` datetime(3) NOT NULL,
  `effective_to` datetime(3) DEFAULT NULL,
  `current_marker` tinyint GENERATED ALWAYS AS ((case when ((`result_status` = _utf8mb4'EFFECTIVE') and (`passed` = 0x01) and (`effective_to` is null)) then 1 else NULL end)) STORED,
  `archive_status` varchar(32) DEFAULT NULL,
  `archive_actor_user_id` bigint NOT NULL,
  `deliverable_source_version_id` bigint DEFAULT NULL,
  `archive_failure_code` varchar(64) DEFAULT NULL,
  `archive_retry_count` int NOT NULL DEFAULT '0',
  `invalidated_by_user_id` bigint DEFAULT NULL,
  `invalidated_at` datetime(3) DEFAULT NULL,
  `invalidation_reason_code` varchar(64) DEFAULT NULL,
  `invalidation_reason_summary` varchar(500) DEFAULT NULL,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) DEFAULT NULL,
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) DEFAULT NULL,
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_acc_sat_result_version` (`tenant_id`,`collection_key`,`result_version`),
  UNIQUE KEY `uk_acc_sat_result_current` (`tenant_id`,`collection_key`,`current_marker`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='满意度不可变判定结果';

CREATE TABLE `acc_satisfaction_result_file` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '0',
  `result_id` bigint NOT NULL,
  `file_role` varchar(32) NOT NULL,
  `file_sequence` int NOT NULL,
  `artifact_id` bigint NOT NULL,
  `version_no` int NOT NULL,
  `reference_key` varchar(128) NOT NULL,
  `artifact_version` int NOT NULL,
  `reference_version` int NOT NULL,
  `availability_version` int NOT NULL,
  `scope_version` bigint NOT NULL,
  `file_hash` char(64) NOT NULL,
  `creator` varchar(64) DEFAULT NULL,
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_acc_sat_result_file_seq` (`tenant_id`,`result_id`,`file_role`,`file_sequence`),
  CONSTRAINT `chk_acc_sat_result_file_role` CHECK ((`file_role` in (_utf8mb4'RESULT_DOCUMENT',_utf8mb4'SIGNATURE',_utf8mb4'ATTACHMENT')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='满意度Result公共文件事实';

CREATE TABLE `ast_address` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint NOT NULL DEFAULT '1',
  `country_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `country_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `province_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `province_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `city_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `city_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `district_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `district_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `detail_address` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `full_address` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `longitude` decimal(10,7) DEFAULT NULL,
  `latitude` decimal(10,7) DEFAULT NULL,
  `normalized_address` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `address_fingerprint` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` tinyint NOT NULL,
  `version` int unsigned NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  KEY `idx_ast_address_fingerprint` (`tenant_id`,`address_fingerprint`),
  KEY `idx_ast_address_district` (`tenant_id`,`district_code`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='资产地址主数据';

CREATE TABLE `ast_area_department_mapping` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint NOT NULL DEFAULT '1',
  `area_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `area_level` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `mapping_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `department_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `effective_from` datetime(3) NOT NULL,
  `effective_to` datetime(3) DEFAULT NULL,
  `status` tinyint NOT NULL,
  `version` int unsigned NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ast_area_department_effective` (`tenant_id`,`area_code`,`area_level`,`mapping_type`,`effective_from`),
  KEY `idx_ast_area_department_current` (`tenant_id`,`area_code`,`area_level`,`mapping_type`,`status`,`effective_to`),
  CONSTRAINT `chk_ast_area_level` CHECK ((`area_level` in (_utf8mb4'COUNTRY',_utf8mb4'PROVINCE',_utf8mb4'CITY',_utf8mb4'DISTRICT')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='行政区划与部门时态映射';

CREATE TABLE `ast_device` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '设备编号',
  `sn` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '租户内唯一设备序列号',
  `name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '设备名称',
  `product_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '产品编码',
  `product_model` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '产品型号',
  `product_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '产品名称',
  `product_desc` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '产品描述',
  `shipment_time` datetime(3) DEFAULT NULL COMMENT '最新有效发货时间',
  `package_no` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `contract_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '最新有效发货合同编号',
  `shipment_record_id` bigint DEFAULT NULL COMMENT '最新有效发货记录编号',
  `project_id` bigint DEFAULT NULL COMMENT '当前直接归属项目编号',
  `project_assignment_version` int unsigned NOT NULL DEFAULT '0' COMMENT '项目归属版本',
  `customer_id` bigint DEFAULT NULL COMMENT '当前直接归属客户编号',
  `customer_assignment_version` int unsigned NOT NULL DEFAULT '0' COMMENT '客户归属版本',
  `site_id` bigint DEFAULT NULL COMMENT '当前站点编号',
  `site_location_id` bigint DEFAULT NULL COMMENT '当前站点位置编号',
  `location_resolution_status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'UNRESOLVED' COMMENT '当前位置解析状态',
  `location_snapshot` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '当前位置快照',
  `location_effective_from` datetime(3) DEFAULT NULL COMMENT '当前位置生效时间',
  `location_record_id` bigint DEFAULT NULL COMMENT '当前位置记录编号',
  `warranty_start_date` date DEFAULT NULL COMMENT '当前维保开始日期',
  `warranty_end_date` date DEFAULT NULL COMMENT '当前维保结束日期',
  `warranty_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '当前客观维保状态',
  `conp_version` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '当前在网CONP原始版本',
  `conp_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '当前在网CONP类型',
  `conp_series` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '当前在网CONP系列',
  `conp_mark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '当前在网CONP版本掩码',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '设备状态',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '平台备注',
  `source_system` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源系统',
  `source_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源键',
  `source_version` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源版本',
  `source_updated_at` datetime(3) DEFAULT NULL COMMENT '来源更新时间',
  `synced_at` datetime(3) DEFAULT NULL COMMENT '最近成功同步时间',
  `sync_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'NOT_APPLICABLE' COMMENT '同步状态',
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '创建人',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '更新人',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  `internal_serial_no` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '内部序列号',
  `secondary_sn` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '最新发货附加SN缓存',
  `secondary_item` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '最新发货附加物料缓存',
  `company_id` bigint DEFAULT NULL COMMENT '所属公司 ID',
  `company_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '所属公司名称',
  `department_id` bigint DEFAULT NULL COMMENT '所属办事处/部门 ID',
  `department_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '所属办事处/部门编码',
  `department_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '所属办事处/部门名称',
  `organization_source` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'UNRESOLVED' COMMENT 'PROJECT/CONTRACT/UNRESOLVED',
  `organization_updated_at` datetime(3) DEFAULT NULL COMMENT '归属重建时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ast_device_tenant_sn` (`tenant_id`,`sn`),
  KEY `idx_ast_device_project` (`tenant_id`,`project_id`,`deleted`,`id`),
  KEY `idx_ast_device_customer` (`tenant_id`,`customer_id`,`deleted`,`id`),
  KEY `idx_ast_device_product` (`tenant_id`,`product_code`,`product_model`,`deleted`,`id`),
  KEY `idx_ast_device_warranty` (`tenant_id`,`warranty_status`,`warranty_end_date`,`deleted`,`id`),
  KEY `idx_ast_device_shipment` (`tenant_id`,`shipment_time`,`deleted`,`id`),
  KEY `idx_ast_device_conp_parse` (`tenant_id`,`conp_type`,`conp_series`,`conp_mark`,`deleted`,`id`),
  KEY `idx_device_organization` (`tenant_id`,`deleted`,`company_id`,`department_id`,`id`),
  KEY `idx_ast_device_contract_projection` (`tenant_id`,`contract_no`,`project_id`,`deleted`,`id`),
  KEY `idx_ast_device_visibility_cover` (`tenant_id`,`deleted`,`company_id`,`department_id`,`department_code`,`organization_source`,`project_id`,`contract_no`,`sn`),
  CONSTRAINT `chk_ast_device_location_resolution` CHECK ((`location_resolution_status` in (_utf8mb4'UNRESOLVED',_utf8mb4'RESOLVED'))),
  CONSTRAINT `chk_ast_device_warranty_dates` CHECK (((`warranty_end_date` is null) or (`warranty_start_date` is null) or (`warranty_end_date` >= `warranty_start_date`)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AST设备主档及高频当前事实投影';

CREATE TABLE `ast_device_ancestor_projection_operation` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '投影操作编号',
  `event_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Outbox事件编号',
  `operation_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '归属操作编号',
  `device_sn` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '设备序列号',
  `project_id` bigint NOT NULL COMMENT '直接归属项目编号',
  `tree_version` int unsigned NOT NULL COMMENT '项目树版本',
  `assignment_version` int unsigned NOT NULL COMMENT '设备归属版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '创建人',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '更新人',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ast_device_ancestor_projection_event` (`tenant_id`,`event_id`),
  KEY `idx_ast_device_ancestor_projection_operation_device` (`tenant_id`,`device_sn`,`assignment_version`),
  KEY `idx_ast_device_ancestor_projection_operation` (`tenant_id`,`operation_id`),
  CONSTRAINT `fk_ast_device_ancestor_projection_operation_device` FOREIGN KEY (`tenant_id`, `device_sn`) REFERENCES `ast_device` (`tenant_id`, `sn`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AST设备祖先投影幂等操作';

CREATE TABLE `ast_device_assembly` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '装配关系编号',
  `parent_device_sn` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '父设备序列号',
  `child_device_sn` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '子设备序列号',
  `position_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '装配位置编码',
  `assembly_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '装配类型',
  `effective_from` datetime(3) NOT NULL COMMENT '装配生效时间',
  `effective_to` datetime(3) DEFAULT NULL COMMENT '装配失效时间',
  `evidence_ref` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '装配证据引用',
  `source_system` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源系统',
  `source_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源键',
  `source_version` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源版本',
  `current_parent_device_sn` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci GENERATED ALWAYS AS ((case when ((`effective_to` is null) and (`deleted` = 0x00)) then `parent_device_sn` else NULL end)) STORED,
  `current_child_device_sn` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci GENERATED ALWAYS AS ((case when ((`effective_to` is null) and (`deleted` = 0x00)) then `child_device_sn` else NULL end)) STORED,
  `current_position_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci GENERATED ALWAYS AS ((case when ((`effective_to` is null) and (`deleted` = 0x00)) then `position_code` else NULL end)) STORED,
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '创建人',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '更新人',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ast_device_assembly_source` (`tenant_id`,`source_system`,`source_key`),
  UNIQUE KEY `uk_ast_device_assembly_current_child` (`tenant_id`,`current_child_device_sn`),
  UNIQUE KEY `uk_ast_device_assembly_current_position` (`tenant_id`,`current_parent_device_sn`,`current_position_code`),
  KEY `idx_ast_device_assembly_parent` (`tenant_id`,`parent_device_sn`,`effective_to`,`child_device_sn`,`id`),
  KEY `idx_ast_device_assembly_child` (`tenant_id`,`child_device_sn`,`effective_to`,`parent_device_sn`,`id`),
  CONSTRAINT `fk_ast_device_assembly_child` FOREIGN KEY (`tenant_id`, `child_device_sn`) REFERENCES `ast_device` (`tenant_id`, `sn`),
  CONSTRAINT `fk_ast_device_assembly_parent` FOREIGN KEY (`tenant_id`, `parent_device_sn`) REFERENCES `ast_device` (`tenant_id`, `sn`),
  CONSTRAINT `chk_ast_device_assembly_dates` CHECK (((`effective_to` is null) or (`effective_to` >= `effective_from`))),
  CONSTRAINT `chk_ast_device_assembly_self` CHECK ((`parent_device_sn` <> `child_device_sn`))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AST设备装配时态关系';

CREATE TABLE `ast_device_assembly_graph_lock` (
  `tenant_id` bigint NOT NULL,
  PRIMARY KEY (`tenant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `ast_device_assignment_reconciliation` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '归属核对编号',
  `device_sn` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '设备序列号',
  `project_id` bigint DEFAULT NULL COMMENT '当前项目编号',
  `project_customer_id` bigint DEFAULT NULL COMMENT '项目当前客户编号',
  `device_customer_id` bigint DEFAULT NULL COMMENT '设备当前客户编号',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '核对状态',
  `reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '核对原因',
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '创建人',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '更新人',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  PRIMARY KEY (`id`),
  KEY `idx_ast_device_assignment_reconciliation_device` (`tenant_id`,`device_sn`,`status`,`id`),
  CONSTRAINT `fk_ast_device_assignment_reconciliation_device` FOREIGN KEY (`tenant_id`, `device_sn`) REFERENCES `ast_device` (`tenant_id`, `sn`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AST设备项目客户归属核对';

CREATE TABLE `ast_device_config_log` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '配置日志编号',
  `device_id` bigint NOT NULL COMMENT '设备编号',
  `config_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '配置类型',
  `config_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '配置内容',
  `source_system` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源系统',
  `collected_at` datetime NOT NULL COMMENT '采集时间',
  `file_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '配置文件URL',
  `file_hash` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '配置文件哈希',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  PRIMARY KEY (`id`),
  KEY `idx_pms_equipment_config_equipment` (`device_id`),
  KEY `idx_pms_equipment_config_collected` (`collected_at`),
  KEY `idx_pms_equipment_config_hash` (`file_hash`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PMS设备配置日志';

CREATE TABLE `ast_device_current_product_type` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `device_id` bigint NOT NULL,
  `product_type_id` bigint DEFAULT NULL,
  `product_type_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source_mapping_id` bigint DEFAULT NULL,
  `resolution_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_version` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_updated_at` datetime(3) NOT NULL,
  `effective_from` datetime(3) NOT NULL,
  `effective_to` datetime(3) DEFAULT NULL,
  `version` int unsigned NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  `current_marker` tinyint GENERATED ALWAYS AS ((case when ((`effective_to` is null) and (`deleted` = 0x00)) then 1 else NULL end)) STORED,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ast_device_product_type_tenant_id` (`tenant_id`,`id`),
  UNIQUE KEY `uk_ast_device_product_type_current` (`tenant_id`,`device_id`,`current_marker`),
  KEY `idx_ast_device_product_type_target` (`tenant_id`,`product_type_id`,`device_id`,`id`),
  KEY `idx_ast_device_product_type_mapping` (`tenant_id`,`source_mapping_id`,`device_id`,`id`),
  KEY `fk_ast_device_product_type_target` (`tenant_id`,`product_type_id`,`product_type_code`),
  KEY `fk_ast_device_product_type_mapping_target` (`tenant_id`,`source_mapping_id`,`product_type_id`),
  CONSTRAINT `fk_ast_device_product_type_mapping` FOREIGN KEY (`tenant_id`, `source_mapping_id`) REFERENCES `ast_product_type_source_mapping` (`tenant_id`, `id`),
  CONSTRAINT `fk_ast_device_product_type_mapping_target` FOREIGN KEY (`tenant_id`, `source_mapping_id`, `product_type_id`) REFERENCES `ast_product_type_source_mapping` (`tenant_id`, `id`, `product_type_id`),
  CONSTRAINT `fk_ast_device_product_type_target` FOREIGN KEY (`tenant_id`, `product_type_id`, `product_type_code`) REFERENCES `ast_product_type` (`tenant_id`, `id`, `type_code`),
  CONSTRAINT `chk_ast_device_product_type_effective` CHECK (((`effective_to` is null) or (`effective_to` >= `effective_from`))),
  CONSTRAINT `chk_ast_device_product_type_resolution` CHECK ((((`resolution_status` = _utf8mb4'RESOLVED') and (`product_type_id` is not null) and (`product_type_code` is not null) and (`source_mapping_id` is not null)) or ((`resolution_status` <> _utf8mb4'RESOLVED') and (`product_type_id` is null) and (`product_type_code` is null)))),
  CONSTRAINT `chk_ast_device_product_type_status` CHECK ((`resolution_status` in (_utf8mb4'RESOLVED',_utf8mb4'UNKNOWN',_utf8mb4'CONFLICT',_utf8mb4'UNRESOLVED')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `ast_device_customer_relationship` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '客户关系编号',
  `device_sn` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '设备序列号',
  `customer_id` bigint NOT NULL COMMENT '客户编号',
  `relationship_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关系类型',
  `effective_from` datetime(3) NOT NULL COMMENT '生效时间',
  `effective_to` datetime(3) DEFAULT NULL COMMENT '失效时间',
  `assignment_version` int unsigned NOT NULL COMMENT '归属版本',
  `reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '变更原因',
  `operation_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '操作编号',
  `source_system` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源系统',
  `source_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源键',
  `source_version` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源版本',
  `current_direct_device_sn` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci GENERATED ALWAYS AS ((case when ((`relationship_type` = _utf8mb4'DIRECT') and (`effective_to` is null) and (`deleted` = 0x00)) then `device_sn` else NULL end)) STORED,
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '创建人',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '更新人',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ast_device_customer_relationship_source` (`tenant_id`,`source_system`,`source_key`),
  UNIQUE KEY `uk_ast_device_customer_relationship_current` (`tenant_id`,`current_direct_device_sn`),
  KEY `idx_ast_device_customer_relationship_device` (`tenant_id`,`device_sn`,`effective_to`,`customer_id`,`id`),
  KEY `idx_ast_device_customer_relationship_customer` (`tenant_id`,`customer_id`,`effective_to`,`device_sn`,`id`),
  CONSTRAINT `fk_ast_device_customer_relationship_device` FOREIGN KEY (`tenant_id`, `device_sn`) REFERENCES `ast_device` (`tenant_id`, `sn`),
  CONSTRAINT `chk_ast_device_customer_relationship_dates` CHECK (((`effective_to` is null) or (`effective_to` >= `effective_from`)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AST设备客户时态关系';

CREATE TABLE `ast_device_cutover_result` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint NOT NULL,
  `project_id` bigint NOT NULL,
  `device_id` bigint NOT NULL,
  `sn` varchar(128) NOT NULL,
  `assignment_version` bigint NOT NULL,
  `task_id` bigint NOT NULL,
  `closure_id` bigint NOT NULL,
  `closure_version` bigint NOT NULL,
  `event_id` varchar(128) NOT NULL,
  `result_ref` varchar(128) NOT NULL,
  `cutover_time` datetime NOT NULL,
  `refresh_status_code` varchar(32) NOT NULL,
  `result_snapshot` json DEFAULT NULL COMMENT '旧CUT成功结果原件；新业务写入NULL，禁止更改历史原值',
  `creator` varchar(64) NOT NULL DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) NOT NULL DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `task_no` varchar(64) DEFAULT NULL COMMENT '割接任务号；历史原件缺失时可空，新业务按既有来源/提交规则必填',
  `task_name` varchar(282) DEFAULT NULL COMMENT '割接任务名称；历史原件缺失时可空，新业务按既有来源/提交规则必填',
  `submit_user_id` bigint DEFAULT NULL COMMENT '原闭环提交人；历史原件缺失时可空，新业务按既有来源/提交规则必填',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ast_cutover_device_result` (`tenant_id`,`device_id`,`closure_id`,`closure_version`),
  UNIQUE KEY `uk_cut_structured_owner_id` (`tenant_id`,`id`),
  KEY `idx_ast_cutover_task` (`tenant_id`,`project_id`,`task_id`),
  CONSTRAINT `chk_ast_cutover_refresh` CHECK (((`refresh_status_code` in (_utf8mb4'REFRESHED',_utf8mb4'HISTORICAL_SCOPE_CHANGED')) = true))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='资产割接成功服务记录与文件引用';

CREATE TABLE `ast_device_cutover_result_file` (
  `id` bigint NOT NULL COMMENT '本表主键',
  `tenant_id` bigint NOT NULL COMMENT '所属租户；必须与父对象一致',
  `device_cutover_result_id` bigint NOT NULL COMMENT '本设备的AST割接结果根',
  `file_source_code` varchar(32) NOT NULL COMMENT 'COLLECTION或MANUAL',
  `collection_stage_code` varchar(64) NOT NULL COMMENT '来源采集/证据阶段',
  `actor_user_id` bigint DEFAULT NULL COMMENT '原采集操作者',
  `platform_task_id` varchar(128) DEFAULT NULL COMMENT '原平台采集任务',
  `result_version` bigint DEFAULT NULL COMMENT '原平台结果版本',
  `file_version_id` bigint DEFAULT NULL COMMENT '原采集文件版本ID',
  `file_artifact_id` bigint DEFAULT NULL COMMENT '人工附件工件ID',
  `file_version_no` int DEFAULT NULL COMMENT '人工附件固定版本',
  `file_reference_key` varchar(128) DEFAULT NULL COMMENT '人工附件业务引用',
  `file_sha256` char(64) DEFAULT NULL COMMENT '原附件摘要',
  `sort_order` int NOT NULL COMMENT '原文件顺序',
  `create_user_id` bigint NOT NULL COMMENT '创建人；历史投影由迁移执行身份记录，不冒充原业务办理人',
  `create_time` datetime(3) NOT NULL COMMENT '本行创建时间；原业务发生时间另按来源字段保留',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_owner_id` (`tenant_id`,`id`),
  UNIQUE KEY `uk_business_1` (`tenant_id`,`device_cutover_result_id`,`platform_task_id`,`result_version`,`file_version_id`),
  UNIQUE KEY `uk_business_2` (`tenant_id`,`device_cutover_result_id`,`file_artifact_id`,`file_version_no`,`file_reference_key`),
  CONSTRAINT `fk_cut_structured_84` FOREIGN KEY (`tenant_id`, `device_cutover_result_id`) REFERENCES `ast_device_cutover_result` (`tenant_id`, `id`),
  CONSTRAINT `chk_device_cutover_result_file_1` CHECK ((((`file_source_code` = _utf8mb4'COLLECTION') and (`platform_task_id` is not null) and (`result_version` is not null) and (`file_version_id` is not null) and (`file_artifact_id` is null) and (`file_version_no` is null) and (`file_reference_key` is null) and (`file_sha256` is null)) or ((`file_source_code` = _utf8mb4'MANUAL') and (`file_artifact_id` is not null) and (`file_version_no` is not null) and (`file_reference_key` is not null) and (`file_sha256` is not null) and (`platform_task_id` is null) and (`result_version` is null) and (`file_version_id` is null) and (`actor_user_id` is null))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='AST设备割接文件事实';

CREATE TABLE `ast_device_download_grant` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '下载授权编号',
  `token_digest` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '一次性令牌SHA-256摘要',
  `user_id` bigint NOT NULL COMMENT '授权用户编号',
  `device_sn` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '设备序列号',
  `configuration_log_id` bigint NOT NULL COMMENT '配置Log编号',
  `expires_at` datetime(3) NOT NULL COMMENT '过期时间',
  `consumed_at` datetime(3) DEFAULT NULL COMMENT '消费时间',
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '创建人',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '更新人',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ast_device_download_grant_token` (`token_digest`),
  KEY `idx_ast_device_download_grant_subject` (`tenant_id`,`user_id`,`device_sn`,`configuration_log_id`),
  KEY `idx_ast_device_download_grant_expiry` (`expires_at`,`consumed_at`),
  KEY `fk_ast_device_download_grant_device` (`tenant_id`,`device_sn`),
  CONSTRAINT `fk_ast_device_download_grant_device` FOREIGN KEY (`tenant_id`, `device_sn`) REFERENCES `ast_device` (`tenant_id`, `sn`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AST设备配置Log一次性下载授权';

CREATE TABLE `ast_device_factory_info` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '出厂信息编号',
