) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='设备许可历史记录';

CREATE TABLE `ast_device_location` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '设备位置记录编号',
  `device_sn` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '设备序列号',
  `site_id` bigint DEFAULT NULL COMMENT '站点编号',
  `site_location_id` bigint DEFAULT NULL COMMENT '站点位置编号',
  `resolution_status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'UNRESOLVED' COMMENT '位置解析状态',
  `location_snapshot` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '位置快照',
  `effective_from` datetime(3) NOT NULL COMMENT '位置生效时间',
  `effective_to` datetime(3) DEFAULT NULL COMMENT '位置失效时间',
  `installation_id` bigint DEFAULT NULL COMMENT '安装记录编号',
  `source_system` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源系统',
  `source_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源键',
  `source_version` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源版本',
  `current_device_sn` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci GENERATED ALWAYS AS ((case when ((`effective_to` is null) and (`deleted` = 0x00)) then `device_sn` else NULL end)) STORED,
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '创建人',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '更新人',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ast_device_location_source` (`tenant_id`,`source_system`,`source_key`),
  UNIQUE KEY `uk_ast_device_location_current` (`tenant_id`,`current_device_sn`),
  KEY `idx_ast_device_location_device` (`tenant_id`,`device_sn`,`effective_to`,`effective_from`,`id`),
  KEY `idx_ast_device_location_site` (`tenant_id`,`site_id`,`site_location_id`,`effective_to`,`id`),
  CONSTRAINT `fk_ast_device_location_device` FOREIGN KEY (`tenant_id`, `device_sn`) REFERENCES `ast_device` (`tenant_id`, `sn`),
  CONSTRAINT `chk_ast_device_location_dates` CHECK (((`effective_to` is null) or (`effective_to` >= `effective_from`))),
  CONSTRAINT `chk_ast_device_location_fact_resolution` CHECK ((`resolution_status` in (_utf8mb4'UNRESOLVED',_utf8mb4'RESOLVED')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AST设备位置时态事实';

