  UNIQUE KEY `uk_ast_device_network_version_source` (`tenant_id`,`source_system`,`source_key`),
  KEY `idx_ast_device_network_version_conp` (`tenant_id`,`conp_version`,`device_sn`),
  KEY `idx_ast_device_network_version_conp_parse` (`tenant_id`,`conp_type`,`conp_series`,`conp_mark`,`device_sn`),
  CONSTRAINT `fk_ast_device_network_version_device` FOREIGN KEY (`tenant_id`, `device_sn`) REFERENCES `ast_device` (`tenant_id`, `sn`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AST设备当前在网软件版本';

CREATE TABLE `ast_device_network_version_event` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '在网版本事件编号',
  `device_sn` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '已映射设备序列号',
  `source_device_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源设备键',
  `source_event_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源事件键',
  `conp_version` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'CONP原始版本',
  `conp_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'CONP类型',
  `conp_series` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'CONP系列',
  `conp_mark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'CONP版本掩码',
  `boot_version` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'BOOT版本',
  `cpld_version` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'CPLD版本',
  `pcb_version` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'PCB版本',
  `customized` bit(1) DEFAULT NULL COMMENT '是否定制版本',
  `release_date` date DEFAULT NULL COMMENT '版本发布日期',
  `version_desc` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '版本说明',
  `event_time` datetime(3) NOT NULL COMMENT '来源事件发生时间',
  `received_time` datetime(3) NOT NULL COMMENT '平台接收时间',
  `change_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '版本变更原因',
  `changed_by` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '版本变更人',
  `revoked` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否撤销',
  `mapping_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '设备映射状态',
  `source_system` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源系统',
  `source_version` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源版本',
  `sync_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '同步状态',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '创建人',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '更新人',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ast_device_network_event_source` (`tenant_id`,`source_system`,`source_device_key`,`source_event_key`),
  KEY `idx_ast_device_network_event_device` (`tenant_id`,`device_sn`,`event_time`,`id`),
  KEY `idx_ast_device_network_event_mapping` (`tenant_id`,`mapping_status`,`received_time`,`id`),
  CONSTRAINT `fk_ast_device_network_event_device` FOREIGN KEY (`tenant_id`, `device_sn`) REFERENCES `ast_device` (`tenant_id`, `sn`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AST设备在网软件版本来源事件';

CREATE TABLE `ast_device_project_ancestor` (
  `device_sn` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '设备序列号',
  `project_id` bigint NOT NULL COMMENT '直接归属项目编号',
  `ancestor_project_id` bigint NOT NULL COMMENT '祖先项目编号',
  `tree_version` int unsigned NOT NULL COMMENT '项目树版本',
  `assignment_version` int unsigned NOT NULL COMMENT '设备归属版本',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  PRIMARY KEY (`tenant_id`,`device_sn`,`project_id`,`ancestor_project_id`,`tree_version`),
  KEY `idx_ast_device_project_ancestor_project` (`tenant_id`,`ancestor_project_id`,`device_sn`),
  CONSTRAINT `fk_ast_device_project_ancestor_device` FOREIGN KEY (`tenant_id`, `device_sn`) REFERENCES `ast_device` (`tenant_id`, `sn`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AST设备项目祖先投影';

CREATE TABLE `ast_device_project_relationship` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '项目关系编号',
  `device_sn` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '设备序列号',
  `project_id` bigint NOT NULL COMMENT '项目编号',
  `relationship_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关系类型',
  `effective_from` datetime(3) NOT NULL COMMENT '生效时间',
  `effective_to` datetime(3) DEFAULT NULL COMMENT '失效时间',
  `assignment_version` int unsigned NOT NULL COMMENT '归属版本',
  `reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '变更原因',
  `operation_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '操作编号',
  `source_system` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源系统',
  `source_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源键',
  `source_version` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源版本',
  `current_direct_device_sn` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci GENERATED ALWAYS AS ((case when ((`relationship_type` = _utf8mb4'DIRECT') and (`effective_to` is null) and (`deleted` = 0x00)) then `device_sn` else NULL end)) STORED,
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '创建人',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '更新人',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ast_device_project_relationship_source` (`tenant_id`,`source_system`,`source_key`),
  UNIQUE KEY `uk_ast_device_project_relationship_current` (`tenant_id`,`current_direct_device_sn`),
  KEY `idx_ast_device_project_relationship_device` (`tenant_id`,`device_sn`,`effective_to`,`project_id`,`id`),
  KEY `idx_ast_device_project_relationship_project` (`tenant_id`,`project_id`,`effective_to`,`device_sn`,`id`),
  CONSTRAINT `fk_ast_device_project_relationship_device` FOREIGN KEY (`tenant_id`, `device_sn`) REFERENCES `ast_device` (`tenant_id`, `sn`),
  CONSTRAINT `chk_ast_device_project_relationship_dates` CHECK (((`effective_to` is null) or (`effective_to` >= `effective_from`)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AST设备项目时态关系';

CREATE TABLE `ast_device_relationship` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '设备关系编号',
  `source_device_sn` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源设备序列号',
  `target_device_sn` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '目标设备序列号',
  `relationship_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关系类型',
  `contract_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '合同编号',
  `effective_from` datetime(3) DEFAULT NULL COMMENT '生效时间',
  `effective_to` datetime(3) DEFAULT NULL COMMENT '失效时间',
  `source_system` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源系统',
  `source_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源键',
  `source_version` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源版本',
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '创建人',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '更新人',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  `source_item` varchar(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源主SN物料 item1',
  `target_item` varchar(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源目标SN物料 item2',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ast_device_relationship_source` (`tenant_id`,`source_system`,`source_key`),
  KEY `idx_ast_device_relationship_source_device` (`tenant_id`,`source_device_sn`,`relationship_type`,`effective_to`,`id`),
  KEY `idx_ast_device_relationship_target_device` (`tenant_id`,`target_device_sn`,`relationship_type`,`effective_to`,`id`),
  CONSTRAINT `chk_ast_device_relationship_dates` CHECK (((`effective_to` is null) or (`effective_from` is null) or (`effective_to` >= `effective_from`))),
  CONSTRAINT `chk_ast_device_relationship_self` CHECK ((`source_device_sn` <> `target_device_sn`))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AST一般设备时态关系';

CREATE TABLE `ast_device_shipment` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '发货记录编号',
  `device_sn` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '设备序列号',
  `shipment_time` datetime(3) DEFAULT NULL COMMENT '发货时间',
  `package_no` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `contract_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '合同编号',
  `event_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '发货事件类型',
  `warranty_start_date` date DEFAULT NULL COMMENT '发货约定维保开始日期',
  `warranty_months` int unsigned DEFAULT NULL COMMENT '发货约定维保月数',
  `rma_no` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'RMA编号',
  `related_device_sn` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关联设备序列号',
  `source_system` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源系统',
  `source_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源键',
  `source_version` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源版本',
  `source_updated_at` datetime(3) DEFAULT NULL COMMENT '来源更新时间',
  `synced_at` datetime(3) DEFAULT NULL COMMENT '最近成功同步时间',
  `sync_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '同步状态',
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '创建人',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '更新人',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  `legacy_package_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源装箱单键，未解析时仍保留',
  `rma_related_sn` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源RMA关联SN候选，不生成替换关系',
  `rma_marked` tinyint NOT NULL DEFAULT '0' COMMENT '来源RMA标识',
  `order_line_id` bigint DEFAULT NULL COMMENT '唯一解析的ERP订单行ID',
  `source_payload` json DEFAULT NULL COMMENT '来源条码记录',
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源订单号',
  `line_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源订单行号',
  `product_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源物料编码 item',
  `secondary_sn` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源附加SN barcode2',
  `secondary_item` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源附加物料 item2',
  `internal_serial_no` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源组合条码 com_barcode',
  `is_rma` int DEFAULT NULL COMMENT '来源RMA标识 isRMA',
  `profit_center` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源利润中心 profitCenter',
  `sole_agent_suffix` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源独家代理后缀 soleAgentSuffix',
  `sync_time` datetime DEFAULT NULL COMMENT '来源同步时间 syncTime',
  `uuid` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源UUID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ast_device_shipment_source` (`tenant_id`,`source_system`,`source_key`),
  KEY `idx_ast_device_shipment_device` (`tenant_id`,`device_sn`,`shipment_time`,`id`),
  KEY `idx_ast_device_shipment_package` (`tenant_id`,`package_no`,`device_sn`),
  KEY `idx_ast_device_shipment_contract` (`tenant_id`,`contract_no`,`device_sn`),
  KEY `fk_ast_device_shipment_related_device` (`tenant_id`,`related_device_sn`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AST设备发货记录';

CREATE TABLE `ast_device_software_change_batch` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `project_id` bigint NOT NULL,
  `change_version` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `change_remark` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `latest` int DEFAULT NULL,
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `create_time` datetime(3) NOT NULL,
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `update_time` datetime(3) NOT NULL,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  KEY `idx_project` (`tenant_id`,`project_id`,`deleted`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Project software registration batches';

CREATE TABLE `ast_device_software_version_record` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `device_id` bigint DEFAULT NULL,
  `device_sn` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `project_id` bigint DEFAULT NULL,
  `previous_record_id` bigint DEFAULT NULL,
  `conp_version` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `conp_type` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `conp_series` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `conp_mark` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `boot_version` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cpld_version` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pcb_version` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `customized` bit(1) DEFAULT NULL,
  `release_date` date DEFAULT NULL,
  `version_desc` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `recorded_at` datetime(3) DEFAULT NULL,
  `data_source` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `parsed_fact_id` bigint DEFAULT NULL,
  `request_key` varchar(180) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `change_batch_id` bigint DEFAULT NULL,
  `contract_no` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `product_code` varchar(25) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `execute_time` date DEFAULT NULL,
  `data_state` int DEFAULT NULL,
  `custom_info` json DEFAULT NULL,
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `create_time` datetime(3) NOT NULL,
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `update_time` datetime(3) NOT NULL,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_software_request` (`tenant_id`,`request_key`),
  UNIQUE KEY `uk_software_parsed_fact` (`tenant_id`,`parsed_fact_id`),
  KEY `idx_software_device` (`tenant_id`,`device_id`,`recorded_at`,`id`),
  KEY `idx_software_project` (`tenant_id`,`project_id`,`recorded_at`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Device software version registrations';

CREATE TABLE `ast_device_version` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `device_id` bigint NOT NULL COMMENT '设备ID',
  `version_no` int NOT NULL COMMENT '设备内递增版本号',
  `change_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '变更类型 CREATE/UPDATE/DEPLOY/REPORT_FAULT/START_REPAIR/COMPLETE_REPAIR/SCRAP',
  `change_description` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '变更说明',
  `before_snapshot` json DEFAULT NULL COMMENT '变更前快照',
  `after_snapshot` json DEFAULT NULL COMMENT '变更后快照',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '删除标志：0否，1是',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户ID',
  PRIMARY KEY (`id`),
  KEY `idx_ast_device_version_device` (`tenant_id`,`device_id`,`version_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AST 设备档案版本历史（追加只读）';

CREATE TABLE `ast_device_warranty` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '当前维保编号',
  `device_sn` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '设备序列号',
  `warranty_start_date` date DEFAULT NULL COMMENT '维保开始日期',
  `warranty_end_date` date DEFAULT NULL COMMENT '维保结束日期',
  `warranty_months` int unsigned DEFAULT NULL COMMENT '维保期限月数',
  `warranty_grade` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '维保等级',
  `warranty_contract_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '维保合同编号',
  `warranty_provider` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '维保服务商',
  `warranty_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '维保类型',
  `warranty_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客观维保状态',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `source_system` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源系统',
  `source_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源键',
  `source_version` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源版本',
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '创建人',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '更新人',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ast_device_warranty_device` (`tenant_id`,`device_sn`),
  UNIQUE KEY `uk_ast_device_warranty_source` (`tenant_id`,`source_system`,`source_key`),
  KEY `idx_ast_device_warranty_status` (`tenant_id`,`warranty_status`,`warranty_end_date`,`device_sn`),
  CONSTRAINT `fk_ast_device_warranty_device` FOREIGN KEY (`tenant_id`, `device_sn`) REFERENCES `ast_device` (`tenant_id`, `sn`),
  CONSTRAINT `chk_ast_device_warranty_fact_dates` CHECK (((`warranty_end_date` is null) or (`warranty_start_date` is null) or (`warranty_end_date` >= `warranty_start_date`)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AST设备当前维保投影';

CREATE TABLE `ast_device_warranty_record` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '维保记录编号',
  `device_sn` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '设备序列号',
  `warranty_start_date` date DEFAULT NULL COMMENT '维保开始日期',
  `warranty_end_date` date DEFAULT NULL COMMENT '维保结束日期',
  `warranty_months` int unsigned DEFAULT NULL COMMENT '维保期限月数',
  `warranty_grade` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '维保等级',
  `warranty_contract_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '维保合同编号',
  `extended` bit(1) DEFAULT NULL COMMENT '是否延保',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `source_system` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源系统',
  `source_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源键',
  `source_version` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源版本',
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '创建人',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '更新人',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ast_device_warranty_record_source` (`tenant_id`,`source_system`,`source_key`),
  KEY `idx_ast_device_warranty_record_device` (`tenant_id`,`device_sn`,`warranty_start_date`,`id`),
  KEY `idx_ast_device_warranty_record_contract` (`tenant_id`,`warranty_contract_no`,`device_sn`),
  CONSTRAINT `fk_ast_device_warranty_record_device` FOREIGN KEY (`tenant_id`, `device_sn`) REFERENCES `ast_device` (`tenant_id`, `sn`),
  CONSTRAINT `chk_ast_device_warranty_record_dates` CHECK (((`warranty_end_date` is null) or (`warranty_start_date` is null) or (`warranty_end_date` >= `warranty_start_date`)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AST设备维保与续保记录';

CREATE TABLE `ast_device_warranty_renewal_record` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `device_sn` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '设备序列号',
  `warranty_contract_no` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '续保合同号',
  `warranty_grade` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '维保等级编码',
  `warranty_start_date` date DEFAULT NULL COMMENT '实际开始日期',
  `warranty_end_date` date DEFAULT NULL COMMENT '实际结束日期',
  `warranty_months` int unsigned DEFAULT NULL COMMENT '参考月数，不据此重算实际日期',
  `extended` bit(1) DEFAULT NULL COMMENT '是否延保，NULL为未记录',
  `is_latest` bit(1) DEFAULT NULL COMMENT '原最新选择标记，不代表在保状态',
  `remark` text COLLATE utf8mb4_unicode_ci COMMENT '续保备注',
  `version` int unsigned NOT NULL DEFAULT '0',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `create_time` datetime(3) NOT NULL,
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `update_time` datetime(3) NOT NULL,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  KEY `idx_renewal_device` (`tenant_id`,`device_sn`,`warranty_start_date`,`id`),
  KEY `idx_renewal_contract` (`tenant_id`,`warranty_contract_no`,`device_sn`),
  CONSTRAINT `ck_renewal_dates` CHECK (((`warranty_start_date` is null) or (`warranty_end_date` is null) or (`warranty_end_date` >= `warranty_start_date`)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='设备续保记录';

CREATE TABLE `ast_location_code_sequence` (
  `tenant_id` bigint NOT NULL,
  `code_namespace` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `next_value` bigint NOT NULL DEFAULT '1',
