) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `ast_location_source_mapping` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint NOT NULL DEFAULT '1',
  `source_system` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `object_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_version` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `address_id` bigint DEFAULT NULL,
  `site_id` bigint DEFAULT NULL,
  `site_location_id` bigint DEFAULT NULL,
  `sync_watermark` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `match_status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `location_resolution_status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'UNRESOLVED',
  `last_synced_at` datetime(3) DEFAULT NULL,
  `version` int unsigned NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ast_location_source_key` (`tenant_id`,`source_system`,`object_type`,`source_key`,`deleted`),
  CONSTRAINT `chk_ast_location_match_status` CHECK ((`match_status` in (_utf8mb4'PENDING',_utf8mb4'MATCHED',_utf8mb4'CONFLICT',_utf8mb4'INVALID'))),
  CONSTRAINT `chk_ast_location_resolution_status` CHECK ((`location_resolution_status` in (_utf8mb4'UNRESOLVED',_utf8mb4'RESOLVED')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='地点外部来源映射';

CREATE TABLE `ast_product_official_info` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '官网产品信息编号',
  `product_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '产品编码（CRM itemCode）',
  `product_model` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '产品型号',
  `product_name` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '产品名称（CRM itemDesc）',
  `product_desc` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '产品描述',
  `technical_spec` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '技术规格（CRM remark）',
  `document_id` bigint DEFAULT NULL COMMENT '官方文档稳定引用',
  `source_system` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源系统',
  `source_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源键',
  `source_version` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源版本',
  `source_updated_at` datetime(3) DEFAULT NULL COMMENT '来源更新时间',
  `synced_at` datetime(3) DEFAULT NULL COMMENT '最近成功同步时间',
  `sync_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '同步状态',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '状态',
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '创建人',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '更新人',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  `crm_product_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'CRM productCode',
  `product_sub_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'CRM productSubCode',
  `list_price` decimal(23,10) DEFAULT NULL COMMENT 'CRM listPrice',
  `crm_status` int DEFAULT NULL COMMENT 'CRM status',
  `business_unit` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'CRM BU',
  `product_line` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'CRM productLine',
  `org_id` int DEFAULT NULL COMMENT 'CRM orgId',
  `source_created_at` datetime(3) DEFAULT NULL COMMENT 'CRM createTime',
  `crm_state_code` int DEFAULT NULL COMMENT 'CRM statecode',
  `crm_status_code` int DEFAULT NULL COMMENT 'CRM statuscode',
  `product_stage` int DEFAULT NULL COMMENT 'CRM productStage',
  `end_of_sale_date` datetime(3) DEFAULT NULL COMMENT 'CRM endOfSaleDate',
  `end_of_support_date` datetime(3) DEFAULT NULL COMMENT 'CRM endOfSupportDate',
  `end_of_life_date` datetime(3) DEFAULT NULL COMMENT 'CRM endOfLifeDate',
  `last_renewal_date` datetime(3) DEFAULT NULL COMMENT 'CRM lastRenewalDate',
  `product_category` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'CRM productCode',
  `product_type` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'CRM productSubCode',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ast_product_official_info_source` (`tenant_id`,`source_system`,`source_key`),
  UNIQUE KEY `uk_product_official_tenant_code` (`tenant_id`,`product_code`),
  KEY `idx_ast_product_official_info_product` (`tenant_id`,`product_code`,`product_model`,`deleted`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AST官网产品信息副本';

