  `service_level_effective_end_time` datetime(3) DEFAULT NULL COMMENT '来源等级失效时间',
  `service_level_source_record_id` bigint DEFAULT NULL COMMENT 'CUS maintenance record ID, not revision ID',
  `manual_customer_service_level_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Explicit selection only when CUS is not configured',
  `manual_customer_service_level_selected_by` bigint DEFAULT NULL,
