  UNIQUE KEY `uk_cut_structured_owner_id` (`tenant_id`,`id`),
  UNIQUE KEY `uk_cut_assessment_current` (`tenant_id`,`task_id`,`current_marker`),
  CONSTRAINT `chk_cut_assessment_grade` CHECK ((((`manual_grade_code` is null) or (`manual_grade_code` in (_utf8mb4'A',_utf8mb4'B',_utf8mb4'C',_utf8mb4'D'))) = true)),
  CONSTRAINT `chk_cut_assessment_marker` CHECK (((`current_marker` is null) or (`current_marker` = 1))),
  CONSTRAINT `chk_cut_assessment_status` CHECK (((`assessment_status_code` in (_utf8mb4'DRAFT',_utf8mb4'SUBMITTED',_utf8mb4'INVALIDATED')) = true)),
  CONSTRAINT `chk_cut_assessment_status_union` CHECK ((coalesce((((`assessment_status_code` = _utf8mb4'DRAFT') and (`submit_user_id` is null) and (`submit_time` is null) and (`invalidate_user_id` is null) and (`invalidate_time` is null) and (`invalidation_reason` is null) and (`simple_flow_flag` = 0x00)) or ((`assessment_status_code` in (_utf8mb4'SUBMITTED',_utf8mb4'INVALIDATED')) and (`manual_grade_code` in (_utf8mb4'A',_utf8mb4'B',_utf8mb4'C',_utf8mb4'D')) and (`submit_user_id` > 0) and (`submit_time` is not null) and (((`manual_grade_code` = _utf8mb4'D') and (`simple_flow_flag` = 0x01)) or ((`manual_grade_code` in (_utf8mb4'A',_utf8mb4'B',_utf8mb4'C')) and (`simple_flow_flag` = 0x00))) and (`business_importance_level` is not null) and (`operation_complexity_level` is not null) and (`hidden_risk_level` is not null) and (`spare_part_applied_flag` is not null) and (((`readiness_decision_code` = _utf8mb4'READY') and (`implementation_readiness_snapshot_id` > 0) and (`implementation_readiness_snapshot_version` >= 0)) or ((`intake_source_type_code` in (_utf8mb4'SELF_CREATED',_utf8mb4'ITR')) and (`readiness_decision_code` = _utf8mb4'NOT_APPLICABLE') and (`implementation_readiness_snapshot_id` is null) and (`implementation_readiness_snapshot_version` is null))) and (((`assessment_status_code` = _utf8mb4'SUBMITTED') and (`invalidate_user_id` is null) and (`invalidate_time` is null) and (`invalidation_reason` is null) and (`current_marker` = 1)) or ((`assessment_status_code` = _utf8mb4'INVALIDATED') and (`invalidate_user_id` > 0) and (`invalidate_time` is not null) and (char_length(trim(`invalidation_reason`)) between 1 and 1000) and (`current_marker` is null))))),false) = true)),
  CONSTRAINT `chk_cut_assessment_values` CHECK (((`assessment_version` > 0) and (`questionnaire_template_version` > 0) and (`version` >= 0)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='F-CUT-002人工分级评估';

