CREATE TABLE `cut_cutover_checklist` (
  `id` bigint NOT NULL COMMENT '主键ID',
  `tenant_id` bigint NOT NULL COMMENT '租户ID',
  `task_id` bigint NOT NULL COMMENT 'CUT-01割接任务逻辑引用',
  `assessment_id` bigint NOT NULL COMMENT 'CUT-02等级评估逻辑引用',
  `assessment_version` int NOT NULL,
  `checklist_version` int NOT NULL,
  `status_code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `input_snapshot` json DEFAULT NULL COMMENT '旧清单匹配输入原件；新业务写入NULL，禁止更改历史原值',
  `input_snapshot_hash` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `config_revision_snapshot` json DEFAULT NULL COMMENT '旧清单配置修订事实原件；新业务写入NULL，禁止更改历史原值',
  `match_trace` json DEFAULT NULL COMMENT '旧清单规则匹配轨迹原件；新业务写入NULL，禁止更改历史原值',
  `config_gap_snapshot` json DEFAULT NULL COMMENT '旧配置缺口事实原件；新业务写入NULL，禁止更改历史原值',
  `submit_user_id` bigint DEFAULT NULL,
  `submit_time` datetime(3) DEFAULT NULL,
  `invalidate_time` datetime(3) DEFAULT NULL,
  `invalidated_reason` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `current_marker` tinyint GENERATED ALWAYS AS ((case when (`invalidate_time` is null) then 1 else NULL end)) STORED,
  `version` int NOT NULL COMMENT '草稿重匹配乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `create_time` datetime(3) NOT NULL,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `update_time` datetime(3) NOT NULL,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `source_task_version` bigint DEFAULT NULL COMMENT '生成时任务并发版本；历史原件缺失时可空，新业务按既有来源/提交规则必填',
  `project_scope_version` bigint DEFAULT NULL COMMENT '生成时项目范围版本；历史原件缺失时可空，新业务按既有来源/提交规则必填',
  `configuration_revision_id` bigint DEFAULT NULL COMMENT '消费的配置修订ID；历史原件缺失时可空，新业务按既有来源/提交规则必填',
  `configuration_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '消费的配置编码；历史原件缺失时可空，新业务按既有来源/提交规则必填',
  `configuration_revision_no` int DEFAULT NULL COMMENT '消费的配置修订号；历史原件缺失时可空，新业务按既有来源/提交规则必填',
  `config_gap_reason_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '原缺口原因编码',
  `matching_project_version` bigint DEFAULT NULL COMMENT '匹配项目主数据维度时锁定的项目版本；历史未消费时为空',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cut_checklist_version` (`tenant_id`,`task_id`,`checklist_version`),
  UNIQUE KEY `uk_cut_structured_owner_id` (`tenant_id`,`id`),
  UNIQUE KEY `uk_cut_checklist_current` (`tenant_id`,`task_id`,`current_marker`),
  KEY `idx_cut_checklist_assessment` (`tenant_id`,`assessment_id`,`assessment_version`),
  KEY `fk_cut_structured_15` (`tenant_id`,`configuration_revision_id`),
  KEY `fk_cut_checklist_task` (`task_id`),
  CONSTRAINT `fk_cut_checklist_task` FOREIGN KEY (`task_id`) REFERENCES `cut_task` (`id`),
  CONSTRAINT `fk_cut_structured_15` FOREIGN KEY (`tenant_id`, `configuration_revision_id`) REFERENCES `cut_cutover_configuration_revision` (`tenant_id`, `id`),
  CONSTRAINT `chk_cut_checklist_invalidation` CHECK (((((`status_code` <> _utf8mb4'INVALIDATED') and (`invalidate_time` is null) and (`invalidated_reason` is null)) or ((`status_code` = _utf8mb4'INVALIDATED') and (`invalidate_time` is not null) and (nullif(trim(`invalidated_reason`),_utf8mb4'') is not null))) = true)),
  CONSTRAINT `chk_cut_checklist_status` CHECK ((`status_code` in (_utf8mb4'DRAFT',_utf8mb4'SUBMITTED',_utf8mb4'INVALIDATED'))),
  CONSTRAINT `chk_cut_checklist_submit` CHECK ((coalesce((((`status_code` = _utf8mb4'DRAFT') and (`submit_user_id` is null) and (`submit_time` is null)) or ((`status_code` = _utf8mb4'SUBMITTED') and (`submit_user_id` > 0) and (`submit_time` is not null)) or ((`status_code` = _utf8mb4'INVALIDATED') and (((`submit_user_id` > 0) and (`submit_time` is not null)) or ((`submit_user_id` is null) and (`submit_time` is null))))),false) = true)),
  CONSTRAINT `chk_cut_checklist_values` CHECK (((`assessment_version` > 0) and (`checklist_version` > 0) and (`version` >= 0)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='F-CUT-003 P3动态采集清单';

