  UNIQUE KEY `uk_cut_structured_owner_id` (`tenant_id`,`id`),
  UNIQUE KEY `uk_cut_checklist_result_current` (`tenant_id`,`checklist_item_id`,`current_marker`),
  KEY `idx_cut_checklist_result_collection` (`tenant_id`,`collection_task_id`),
  KEY `fk_cut_checklist_result_item` (`checklist_item_id`),
  KEY `fk_cut_structured_16` (`tenant_id`,`field_definition_id`),
  KEY `fk_cut_structured_17` (`tenant_id`,`base_checklist_result_id`),
  KEY `fk_cut_structured_18` (`tenant_id`,`collection_log_id`),
  CONSTRAINT `fk_cut_checklist_result_item` FOREIGN KEY (`checklist_item_id`) REFERENCES `cut_cutover_checklist_item` (`id`),
  CONSTRAINT `fk_cut_structured_16` FOREIGN KEY (`tenant_id`, `field_definition_id`) REFERENCES `cut_checklist_field_definition` (`tenant_id`, `id`),
  CONSTRAINT `fk_cut_structured_17` FOREIGN KEY (`tenant_id`, `base_checklist_result_id`) REFERENCES `cut_cutover_checklist_item_result` (`tenant_id`, `id`),
  CONSTRAINT `fk_cut_structured_18` FOREIGN KEY (`tenant_id`, `collection_log_id`) REFERENCES `cut_collection_log` (`tenant_id`, `id`),
  CONSTRAINT `chk_cut_checklist_manual_fact` CHECK ((((`manual_evidence_file_reference` is null) or ((`result_source_code` = _utf8mb4'MANUAL') and (nullif(trim(`manual_evidence_file_reference`),_utf8mb4'') is not null))) = true)),
  CONSTRAINT `chk_cut_checklist_result_interval` CHECK ((((`selection_end_time` is null) or (`selection_end_time` >= `selection_start_time`)) = true)),
  CONSTRAINT `chk_cut_checklist_result_source` CHECK ((`result_source_code` in (_utf8mb4'DIRECT',_utf8mb4'COLLECTION',_utf8mb4'EXTERNAL',_utf8mb4'MANUAL'))),
  CONSTRAINT `chk_cut_checklist_result_values` CHECK ((((`result_version` > 0) and (`select_user_id` > 0) and (`create_user_id` > 0)) = true))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='F-CUT-003 P3动态采集清单项结果';

CREATE TABLE `cut_cutover_closure` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `task_id` bigint NOT NULL,
  `project_id` bigint NOT NULL,
  `approval_instance_id` bigint NOT NULL,
  `approval_version` int NOT NULL,
  `plan_revision_id` bigint NOT NULL COMMENT '已批准CUT-04方案版本',
  `plan_revision_no` int NOT NULL,
  `plan_version` int NOT NULL,
  `task_version_at_p6` int NOT NULL,
  `device_scope_watermark` json DEFAULT NULL COMMENT '旧设备范围水位原件；新业务写入NULL，禁止更改历史原值',
  `status_code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `pre_check_normal_flag` bit(1) DEFAULT NULL,
  `pre_check_detail` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `execution_normal_flag` bit(1) DEFAULT NULL,
  `execution_detail` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `test_normal_flag` bit(1) DEFAULT NULL,
  `test_detail` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `rollback_occurred_flag` bit(1) DEFAULT NULL,
  `rollback_successful_flag` bit(1) DEFAULT NULL,
  `rollback_reason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `legacy_items` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `final_result_code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `result_ref` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `submit_user_id` bigint DEFAULT NULL,
  `submit_time` datetime(3) DEFAULT NULL,
  `archive_time` datetime(3) DEFAULT NULL,
  `version` int NOT NULL,
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `create_time` datetime(3) NOT NULL,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `update_time` datetime(3) NOT NULL,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cut_closure_task` (`tenant_id`,`task_id`),
  UNIQUE KEY `uk_cut_structured_owner_id` (`tenant_id`,`id`),
  KEY `idx_cut_closure_project_status` (`tenant_id`,`project_id`,`status_code`,`id`),
  KEY `fk_cut_closure_task` (`task_id`),
  CONSTRAINT `fk_cut_closure_task` FOREIGN KEY (`task_id`) REFERENCES `cut_task` (`id`),
  CONSTRAINT `chk_cut_closure_details` CHECK (((((`pre_check_detail` is null) or (char_length(`pre_check_detail`) <= 4000)) and ((`execution_detail` is null) or (char_length(`execution_detail`) <= 4000)) and ((`test_detail` is null) or (char_length(`test_detail`) <= 4000)) and ((`legacy_items` is null) or (char_length(`legacy_items`) <= 4000)) and ((`pre_check_normal_flag` is null) or (`pre_check_normal_flag` = 0x01) or (0 <> coalesce((char_length(trim(`pre_check_detail`)) between 1 and 4000),false))) and ((`execution_normal_flag` is null) or (`execution_normal_flag` = 0x01) or (0 <> coalesce((char_length(trim(`execution_detail`)) between 1 and 4000),false))) and ((`test_normal_flag` is null) or (`test_normal_flag` = 0x01) or (0 <> coalesce((char_length(trim(`test_detail`)) between 1 and 4000),false)))) = true)),
  CONSTRAINT `chk_cut_closure_lifecycle` CHECK (((((`status_code` = _utf8mb4'DRAFT') and (`final_result_code` is null) and (`result_ref` is null) and (`submit_user_id` is null) and (`submit_time` is null) and (`archive_time` is null)) or (0 <> coalesce(((`status_code` = _utf8mb4'SUBMITTED') and (`pre_check_normal_flag` is not null) and (`execution_normal_flag` is not null) and (`test_normal_flag` is not null) and (`rollback_occurred_flag` is not null) and (`final_result_code` in (_utf8mb4'SUCCESS',_utf8mb4'FAILED')) and (`submit_user_id` > 0) and (`submit_time` is not null) and (`archive_time` = `submit_time`) and (((`final_result_code` = _utf8mb4'SUCCESS') and (cast(`result_ref` as char charset binary) = cast(concat(_utf8mb4'CUTOVER_CLOSURE:',`id`,_utf8mb4':',`version`) as char charset binary))) or ((`final_result_code` = _utf8mb4'FAILED') and (`result_ref` is null)))),false))) = true)),
  CONSTRAINT `chk_cut_closure_result_code` CHECK (((`final_result_code` is null) or (`final_result_code` in (_utf8mb4'SUCCESS',_utf8mb4'FAILED')))),
  CONSTRAINT `chk_cut_closure_rollback` CHECK (((((`rollback_occurred_flag` is null) and (`rollback_successful_flag` is null) and (`rollback_reason` is null)) or ((`rollback_occurred_flag` = 0x00) and (`rollback_successful_flag` is null) and (`rollback_reason` is null)) or (0 <> coalesce(((`rollback_occurred_flag` = 0x01) and (`rollback_successful_flag` is not null) and (char_length(trim(`rollback_reason`)) between 1 and 4000)),false))) = true)),
  CONSTRAINT `chk_cut_closure_status` CHECK ((`status_code` in (_utf8mb4'DRAFT',_utf8mb4'SUBMITTED'))),
  CONSTRAINT `chk_cut_closure_values` CHECK (((`id` > 0) and (`project_id` > 0) and (`approval_instance_id` > 0) and (`approval_version` >= 0) and (`plan_revision_id` > 0) and (`plan_revision_no` > 0) and (`plan_version` >= 0) and (`task_version_at_p6` >= 0) and (`version` >= 0)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='F-CUT-006 P6割接闭环';

CREATE TABLE `cut_cutover_closure_attachment` (
