  KEY `fk_cut_closure_attachment_root` (`closure_id`),
  CONSTRAINT `fk_cut_closure_attachment_root` FOREIGN KEY (`closure_id`) REFERENCES `cut_cutover_closure` (`id`),
  CONSTRAINT `chk_cut_closure_attachment_purpose` CHECK ((`purpose_code` in (_utf8mb4'POST_COLLECTION_CHECKLIST',_utf8mb4'IMPLEMENTATION_COMMITMENT',_utf8mb4'OTHER_EVIDENCE',_utf8mb4'MANUAL_COLLECTION_RESULT'))),
  CONSTRAINT `chk_cut_closure_attachment_values` CHECK ((((`file_artifact_id` > 0) and (`file_version_no` > 0) and (`file_scope_version` >= 0) and (`version` >= 0) and (char_length(trim(`file_reference_key`)) between 1 and 128) and regexp_like(`file_sha256`,_ascii'^[0-9a-f]{64}$',_utf8mb4'c')) = true)),
  CONSTRAINT `chk_cut_structured_file_58` CHECK ((coalesce(((`file_artifact_fact_version` is not null) and (`file_reference_fact_version` is not null) and (`file_availability_fact_version` is not null) and (`file_artifact_fact_version` >= 0) and (`file_reference_fact_version` >= 0) and (`file_availability_fact_version` >= 0)),false) = true))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='F-CUT-006闭环文件事实';

CREATE TABLE `cut_cutover_collection_evidence` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `closure_id` bigint NOT NULL,
  `task_id` bigint NOT NULL,
  `project_id` bigint NOT NULL,
  `device_id` bigint NOT NULL,
  `collection_stage_code` varchar(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `evidence_type_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `collection_task_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `callback_event_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `result_ref` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `result_version` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `original_failed_collection_task_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `manual_attachment_id` bigint DEFAULT NULL,
  `dispatch_marker` tinyint GENERATED ALWAYS AS ((case when (`evidence_type_code` in (_utf8mb4'DISPATCH_ACCEPTED',_utf8mb4'DISPATCH_FAILED')) then 1 else NULL end)) STORED,
  `callback_marker` tinyint GENERATED ALWAYS AS ((case when (`evidence_type_code` in (_utf8mb4'CALLBACK_SUCCEEDED',_utf8mb4'CALLBACK_FAILED')) then 1 else NULL end)) STORED,
  `manual_marker` tinyint GENERATED ALWAYS AS ((case when (`evidence_type_code` = _utf8mb4'MANUAL_UPLOAD') then 1 else NULL end)) STORED,
  `occur_time` datetime(3) NOT NULL,
  `record_user_id` bigint NOT NULL,
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `create_time` datetime(3) NOT NULL,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cut_collection_dispatch` (`tenant_id`,`collection_task_id`,`dispatch_marker`),
  UNIQUE KEY `uk_cut_collection_callback` (`tenant_id`,`collection_task_id`,`callback_marker`),
  UNIQUE KEY `uk_cut_collection_manual` (`tenant_id`,`original_failed_collection_task_id`,`manual_marker`),
  UNIQUE KEY `uk_cut_collection_callback_event` (`tenant_id`,`callback_event_id`),
  KEY `idx_cut_collection_closure_order` (`tenant_id`,`closure_id`,`occur_time`,`id`),
  KEY `fk_cut_collection_closure` (`closure_id`),
  KEY `fk_cut_collection_task` (`task_id`),
  KEY `fk_cut_collection_manual_attachment` (`manual_attachment_id`),
  CONSTRAINT `fk_cut_collection_closure` FOREIGN KEY (`closure_id`) REFERENCES `cut_cutover_closure` (`id`),
  CONSTRAINT `fk_cut_collection_manual_attachment` FOREIGN KEY (`manual_attachment_id`) REFERENCES `cut_cutover_closure_attachment` (`id`),
  CONSTRAINT `fk_cut_collection_task` FOREIGN KEY (`task_id`) REFERENCES `cut_task` (`id`),
  CONSTRAINT `chk_cut_collection_stage` CHECK ((`collection_stage_code` in (_utf8mb4'PRE_CHECK',_utf8mb4'EXECUTION',_utf8mb4'TEST',_utf8mb4'ROLLBACK',_utf8mb4'POST_COLLECTION'))),
  CONSTRAINT `chk_cut_collection_type` CHECK ((`evidence_type_code` in (_utf8mb4'DISPATCH_ACCEPTED',_utf8mb4'DISPATCH_FAILED',_utf8mb4'CALLBACK_SUCCEEDED',_utf8mb4'CALLBACK_FAILED',_utf8mb4'MANUAL_UPLOAD'))),
  CONSTRAINT `chk_cut_collection_union` CHECK (((((`evidence_type_code` in (_utf8mb4'DISPATCH_ACCEPTED',_utf8mb4'DISPATCH_FAILED')) and (`callback_event_id` is null) and (`result_ref` is null) and (`result_version` is null) and (`original_failed_collection_task_id` is null) and (`manual_attachment_id` is null) and (`record_user_id` > 0)) or (0 <> coalesce(((`evidence_type_code` in (_utf8mb4'CALLBACK_SUCCEEDED',_utf8mb4'CALLBACK_FAILED')) and (char_length(trim(`callback_event_id`)) between 1 and 128) and (char_length(trim(`result_ref`)) between 1 and 256) and (char_length(trim(`result_version`)) between 1 and 128) and (`original_failed_collection_task_id` is null) and (`manual_attachment_id` is null) and (`record_user_id` = 0)),false)) or (0 <> coalesce(((`evidence_type_code` = _utf8mb4'MANUAL_UPLOAD') and (`callback_event_id` is null) and (`result_ref` is null) and (`result_version` is null) and (cast(`collection_task_id` as char charset binary) = cast(`original_failed_collection_task_id` as char charset binary)) and (`manual_attachment_id` > 0) and (`record_user_id` > 0)),false))) = true)),
  CONSTRAINT `chk_cut_collection_values` CHECK ((((`project_id` > 0) and (`device_id` > 0) and (`record_user_id` >= 0) and (char_length(trim(`collection_task_id`)) between 1 and 128)) = true))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='F-CUT-006采集证据追加历史';

CREATE TABLE `cut_cutover_configuration_revision` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `configuration_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `configuration_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `revision_no` int NOT NULL,
  `status_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `effective_start_time` datetime DEFAULT NULL,
  `effective_end_time` datetime DEFAULT NULL,
  `dictionary_snapshot` json DEFAULT NULL COMMENT '旧配置字典快照原件；新业务写入NULL，禁止更改历史原值',
  `dimension_definition_snapshot` json DEFAULT NULL COMMENT '旧配置维度定义原件；新业务写入NULL，禁止更改历史原值',
  `plan_template_section_snapshot` json DEFAULT NULL COMMENT '旧配置方案章节模板原件；新业务写入NULL，禁止更改历史原值',
  `navigation_rule_snapshot` json DEFAULT NULL COMMENT '旧提交后导航规则快照原件；新业务写入NULL，禁止更改历史原值',
  `validation_result_snapshot` json DEFAULT NULL COMMENT '旧配置完整性校验结果原件；新业务写入NULL，禁止更改历史原值',
  `change_summary` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `publish_user_id` bigint DEFAULT NULL,
  `publish_time` datetime DEFAULT NULL,
  `disable_user_id` bigint DEFAULT NULL,
  `disable_time` datetime DEFAULT NULL,
  `published_marker` tinyint GENERATED ALWAYS AS ((case when ((`status_code` = _utf8mb4'PUBLISHED') and (`deleted` = 0)) then 1 else NULL end)) STORED,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  `navigation_target_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '原导航目标CURRENT_STAGE_WORKBENCH或TASK_OVERVIEW',
  `validation_valid_flag` bit(1) DEFAULT NULL COMMENT '最近一次完整性校验结论',
  `current_validation_no` int DEFAULT NULL COMMENT '最近一次校验序号；问题明细按该序号读取',
  `validate_time` datetime(3) DEFAULT NULL COMMENT '最近一次校验时间',
  `validate_user_id` bigint DEFAULT NULL COMMENT '最近一次校验人',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cut_config_code_revision` (`tenant_id`,`configuration_code`,`revision_no`),
  UNIQUE KEY `uk_cut_structured_owner_id` (`tenant_id`,`id`),
  UNIQUE KEY `uk_cut_config_current_published` (`tenant_id`,`configuration_code`,`published_marker`),
  KEY `idx_cut_config_status` (`tenant_id`,`status_code`,`update_time`,`id`),
  CONSTRAINT `chk_cut_config_status` CHECK ((`status_code` in (_utf8mb4'DRAFT',_utf8mb4'PUBLISHED',_utf8mb4'DISABLED'))),
  CONSTRAINT `chk_cut_configuration_navigation_rule` CHECK ((((`navigation_target_code` is null) or (`navigation_target_code` in (_utf8mb4'CURRENT_STAGE_WORKBENCH',_utf8mb4'TASK_OVERVIEW'))) = true))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='CUT-07割接配置根修订';

CREATE TABLE `cut_cutover_support_arrangement` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `plan_revision_id` bigint NOT NULL COMMENT 'CUT-04方案版本逻辑引用',
  `role_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `person_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `duty_description` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `phone` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `arrive_time` datetime(3) DEFAULT NULL COMMENT '到位时间；草稿未填时为空',
  `version` int NOT NULL,
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `create_time` datetime(3) NOT NULL,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `update_time` datetime(3) NOT NULL,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `current_support_contact_change_id` bigint DEFAULT NULL COMMENT '当前采用的批准后联系信息变更记录',
  `customer_contact_id` bigint DEFAULT NULL COMMENT '客户联系记录基线引用',
  `customer_contact_version` bigint DEFAULT NULL COMMENT '客户联系记录基线版本',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '方案内填写顺序',
  `person_source_code` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '选择来源 PROJECT_MEMBER/SYSTEM_USER',
  `person_source_id` bigint DEFAULT NULL COMMENT '来源成员区间或系统用户ID',
  `person_source_version` bigint DEFAULT NULL COMMENT '来源版本',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cut_structured_owner_id` (`tenant_id`,`id`),
  KEY `idx_cut_support_plan` (`tenant_id`,`plan_revision_id`,`role_code`,`id`),
  KEY `fk_cut_support_plan` (`plan_revision_id`),
  KEY `fk_cut_structured_61` (`tenant_id`,`current_support_contact_change_id`),
  KEY `idx_cut_support_order` (`tenant_id`,`plan_revision_id`,`sort_order`,`id`),
  CONSTRAINT `fk_cut_structured_61` FOREIGN KEY (`tenant_id`, `current_support_contact_change_id`) REFERENCES `cut_plan_support_contact_change` (`tenant_id`, `id`),
  CONSTRAINT `fk_cut_support_plan` FOREIGN KEY (`plan_revision_id`) REFERENCES `cut_plan_revision` (`id`),
  CONSTRAINT `chk_cut_support_customer_reference` CHECK ((((`customer_contact_id` is null) and (`customer_contact_version` is null)) or ((`role_code` = _utf8mb4'CUSTOMER') and (`customer_contact_id` > 0) and (`customer_contact_version` >= 0) and (`customer_contact_id` is not null) and (`customer_contact_version` is not null)))),
  CONSTRAINT `chk_cut_support_person_source` CHECK ((((`person_source_code` is null) and (`person_source_id` is null) and (`person_source_version` is null)) or ((`person_source_code` is not null) and (`person_source_id` is not null) and (`person_source_version` is not null) and (`person_source_id` > 0) and (`person_source_version` >= 0) and (((`role_code` = _utf8mb4'CUSTOMER') and (`person_source_code` = _utf8mb4'PROJECT_MEMBER')) or ((`role_code` <> _utf8mb4'CUSTOMER') and (`person_source_code` = _utf8mb4'SYSTEM_USER'))) and (`customer_contact_id` is null)))),
  CONSTRAINT `chk_cut_support_role` CHECK ((`role_code` in (_utf8mb4'CUSTOMER',_utf8mb4'DP_FIRST_LINE',_utf8mb4'DP_SECOND_LINE',_utf8mb4'DP_RND'))),
  CONSTRAINT `chk_cut_support_values` CHECK (((`version` >= 0) and (char_length(trim(`person_name`)) between 0 and 128) and (char_length(trim(`duty_description`)) between 0 and 1000) and (char_length(trim(`phone`)) between 0 and 64) and (`sort_order` >= 0)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='F-CUT-004割接保障安排';

CREATE TABLE `cut_plan_device` (
  `id` bigint NOT NULL COMMENT '本表主键',
  `tenant_id` bigint NOT NULL COMMENT '所属租户；必须与父对象一致',
  `plan_revision_id` bigint NOT NULL COMMENT '既有方案修订ID',
  `assessment_device_id` bigint DEFAULT NULL COMMENT '评估冻结设备行',
  `device_id` bigint NOT NULL COMMENT '设备ID',
  `sn` varchar(128) NOT NULL COMMENT '来源序列号',
  `project_assignment_version` bigint NOT NULL COMMENT '来源归属水位',
  `device_type_code` varchar(64) DEFAULT NULL COMMENT '来源设备类型',
  `device_type_source_version` varchar(128) DEFAULT NULL COMMENT '来源设备类型版本',
  `product_model` text COMMENT '填写值：方案设备型号',
  `current_software_version` text COMMENT '填写值：方案当前版本',
  `target_software_version` text COMMENT '填写值：方案目标版本',
  `remark` text COMMENT '填写值：备注',
  `sort_order` int NOT NULL COMMENT '顺序',
  `creator` varchar(64) NOT NULL COMMENT '创建审计账号；服务端写入',
  `create_time` datetime(3) NOT NULL COMMENT '创建审计时间',
  `updater` varchar(64) NOT NULL COMMENT '更新审计账号；服务端写入',
  `update_time` datetime(3) NOT NULL COMMENT '更新审计时间',
  `deleted` bit(1) NOT NULL COMMENT '草稿明细逻辑删除标记；已发布或已提交历史不开放删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_owner_id` (`tenant_id`,`id`),
  UNIQUE KEY `uk_business_1` (`tenant_id`,`plan_revision_id`,`device_id`),
  KEY `fk_cut_structured_64` (`tenant_id`,`assessment_device_id`),
  CONSTRAINT `fk_cut_structured_63` FOREIGN KEY (`tenant_id`, `plan_revision_id`) REFERENCES `cut_plan_revision` (`tenant_id`, `id`),
  CONSTRAINT `fk_cut_structured_64` FOREIGN KEY (`tenant_id`, `assessment_device_id`) REFERENCES `cut_assessment_device` (`tenant_id`, `id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='方案设备资料行';

CREATE TABLE `cut_plan_file` (
  `id` bigint NOT NULL COMMENT '本表主键',
  `tenant_id` bigint NOT NULL COMMENT '所属租户；必须与父对象一致',
  `plan_revision_id` bigint NOT NULL COMMENT '既有方案修订ID',
  `file_role_code` varchar(64) NOT NULL COMMENT '既有附件槽位',
  `file_artifact_id` bigint NOT NULL COMMENT 'PLT工件ID；文件本体仍由PLT保存',
  `file_version_no` int NOT NULL COMMENT '固定文件版本号',
  `file_reference_key` varchar(128) NOT NULL COMMENT 'PLT业务引用键',
  `file_artifact_fact_version` bigint NOT NULL COMMENT '文件工件事实水位',
  `file_reference_fact_version` bigint NOT NULL COMMENT '文件引用事实水位',
  `file_availability_fact_version` bigint NOT NULL COMMENT '文件可用性事实水位',
  `file_scope_version` bigint NOT NULL COMMENT '登记时范围版本；不据此否定当前合法下载',
  `file_sha256` char(64) NOT NULL COMMENT '已有文件内容摘要',
  `creator` varchar(64) NOT NULL COMMENT '创建审计账号；服务端写入',
  `create_time` datetime(3) NOT NULL COMMENT '创建审计时间',
  `updater` varchar(64) NOT NULL COMMENT '更新审计账号；服务端写入',
  `update_time` datetime(3) NOT NULL COMMENT '更新审计时间',
  `deleted` bit(1) NOT NULL COMMENT '草稿明细逻辑删除标记；已发布或已提交历史不开放删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_owner_id` (`tenant_id`,`id`),
  UNIQUE KEY `uk_business_1` (`tenant_id`,`plan_revision_id`,`file_role_code`),
  CONSTRAINT `fk_cut_structured_65` FOREIGN KEY (`tenant_id`, `plan_revision_id`) REFERENCES `cut_plan_revision` (`tenant_id`, `id`),
  CONSTRAINT `chk_cut_structured_file_47` CHECK ((coalesce(((`file_artifact_fact_version` is not null) and (`file_reference_fact_version` is not null) and (`file_availability_fact_version` is not null) and (`file_artifact_fact_version` >= 0) and (`file_reference_fact_version` >= 0) and (`file_availability_fact_version` >= 0)),false) = true))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='方案固定槽位文件';

CREATE TABLE `cut_plan_generated_file` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `task_id` bigint NOT NULL,
  `plan_revision_id` bigint NOT NULL,
  `plan_version` bigint NOT NULL,
  `artifact_id` bigint NOT NULL,
  `file_version_no` int NOT NULL,
  `reference_key` varchar(128) NOT NULL,
  `artifact_fact_version` int NOT NULL,
  `reference_fact_version` int NOT NULL,
  `availability_fact_version` int NOT NULL,
  `scope_version` bigint NOT NULL,
  `sha256` char(64) NOT NULL,
  `generated_at` bigint NOT NULL COMMENT '生成成功时间，EpochMillis',
  `creator` bigint NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_cut_plan_generated_version` (`tenant_id`,`plan_revision_id`,`plan_version`,`generated_at`,`id`),
  CONSTRAINT `chk_cut_plan_generated_fact` CHECK (((`plan_version` >= 0) and (`artifact_id` > 0) and (`file_version_no` > 0) and (`artifact_fact_version` >= 0) and (`reference_fact_version` >= 0) and (`availability_fact_version` >= 0) and (`scope_version` >= 0) and (`generated_at` > 0) and (char_length(trim(`reference_key`)) > 0) and regexp_like(`sha256`,_utf8mb4'^[0-9a-f]{64}$')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='CUT在线方案按正文版本保存的生成文件引用';

CREATE TABLE `cut_plan_revision` (
