  `grade_code` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `assessment_id` bigint DEFAULT NULL,
  `assessment_version` int DEFAULT NULL,
  `checklist_id` bigint DEFAULT NULL,
  `checklist_version` int DEFAULT NULL,
  `configuration_revision_id` bigint DEFAULT NULL,
  `configuration_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `configuration_revision_no` int DEFAULT NULL,
  `template_section_snapshot` json DEFAULT NULL COMMENT '旧方案采用的模板章节原件；新业务写入NULL，禁止更改历史原值',
  `source_snapshot` json DEFAULT NULL COMMENT '旧方案来源事实原件；新业务写入NULL，禁止更改历史原值',
  `content_snapshot` json DEFAULT NULL COMMENT '旧方案正文原件；新业务写入NULL，禁止更改历史原值',
  `file_artifact_id` bigint DEFAULT NULL,
  `file_version_no` int DEFAULT NULL,
  `file_reference_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `file_fact_version` json DEFAULT NULL COMMENT '旧文件三项事实水位原件；新业务写入NULL，禁止更改历史原值',
  `file_scope_version` bigint DEFAULT NULL,
  `file_sha256` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ownership_confirmed_flag` bit(1) DEFAULT NULL,
  `status_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `current_marker` tinyint DEFAULT NULL,
  `submit_user_id` bigint DEFAULT NULL,
  `submit_time` datetime(3) DEFAULT NULL,
  `approval_instance_id` bigint DEFAULT NULL,
  `approval_version` int DEFAULT NULL,
  `source_plan_revision_id` bigint DEFAULT NULL,
  `revision_reason_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `invalidate_user_id` bigint DEFAULT NULL,
  `invalidate_time` datetime(3) DEFAULT NULL,
  `invalidation_reason_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `legacy_plan_id` bigint DEFAULT NULL,
  `legacy_status_raw` tinyint DEFAULT NULL,
  `legacy_source_version` int DEFAULT NULL,
  `legacy_mapping_version` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `version` int NOT NULL,
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `create_time` datetime(3) NOT NULL,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `update_time` datetime(3) NOT NULL,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `source_task_version` bigint DEFAULT NULL COMMENT '提交来源任务版本；历史原件缺失时可空，新业务按既有来源/提交规则必填',
