  `task_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '当时割接任务号；历史原件缺失时可空，新业务按既有来源/提交规则必填',
  `source_task_version` bigint DEFAULT NULL COMMENT '当时任务版本；历史原件缺失时可空，新业务按既有来源/提交规则必填',
  `correlation_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '原请求跟踪标识；历史原件缺失时可空，新业务按既有来源/提交规则必填',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cut_spare_platform_request` (`tenant_id`,`platform_request_id`),
  UNIQUE KEY `uk_cut_structured_owner_id` (`tenant_id`,`id`),
  UNIQUE KEY `uk_cut_spare_external_request` (`tenant_id`,`external_system_code`,`external_request_id`),
  UNIQUE KEY `uk_cut_spare_external_application` (`tenant_id`,`external_system_code`,`external_application_no`),
  KEY `idx_cut_spare_task` (`tenant_id`,`task_id`,`id`),
  KEY `idx_cut_spare_retry` (`tenant_id`,`integration_status_code`,`last_attempt_time`,`id`),
  KEY `fk_cut_spare_application_task` (`task_id`),
  CONSTRAINT `fk_cut_spare_application_task` FOREIGN KEY (`task_id`) REFERENCES `cut_task` (`id`),
  CONSTRAINT `chk_cut_spare_application_deleted` CHECK ((`deleted` = 0x00)),
  CONSTRAINT `chk_cut_spare_application_json` CHECK ((coalesce(((`need_required_flag` is not null) and (`task_no` is not null) and (`source_task_version` >= 0) and (`correlation_id` is not null)),false) = true)),
  CONSTRAINT `chk_cut_spare_application_status` CHECK (((`integration_status_code` in (_utf8mb4'REQUEST_PENDING',_utf8mb4'EXTERNAL_REFERENCED',_utf8mb4'RETRY_PENDING')) = true)),
  CONSTRAINT `chk_cut_spare_application_version` CHECK (((`retry_count` >= 0) and (`version` >= 0))),
  CONSTRAINT `chk_cut_spare_external_application_text` CHECK (((`external_application_no` is null) or ((char_length(`external_application_no`) between 1 and 128) and (char_length(`external_application_no`) = char_length(trim(`external_application_no`)))))),
  CONSTRAINT `chk_cut_spare_external_binding` CHECK (((`external_application_no` is null) or (`external_request_id` is not null))),
  CONSTRAINT `chk_cut_spare_external_request_text` CHECK (((`external_request_id` is null) or ((char_length(`external_request_id`) between 1 and 128) and (char_length(`external_request_id`) = char_length(trim(`external_request_id`)))))),
  CONSTRAINT `chk_cut_spare_external_result` CHECK (((`external_request_id` is null) or (`external_application_no` is not null) or (`launch_url` is not null))),
  CONSTRAINT `chk_cut_spare_external_system_text` CHECK (((char_length(`external_system_code`) between 1 and 64) and (char_length(`external_system_code`) = char_length(trim(`external_system_code`))))),
  CONSTRAINT `chk_cut_spare_launch_url_text` CHECK (((`launch_url` is null) or ((char_length(`launch_url`) between 1 and 2048) and (char_length(`launch_url`) = char_length(trim(`launch_url`)))))),
  CONSTRAINT `chk_cut_spare_pending_binding` CHECK ((((`integration_status_code` <> _utf8mb4'REQUEST_PENDING') or (`external_application_no` is null)) = true)),
  CONSTRAINT `chk_cut_spare_platform_request_text` CHECK (((char_length(`platform_request_id`) between 1 and 128) and (char_length(`platform_request_id`) = char_length(trim(`platform_request_id`))))),
  CONSTRAINT `chk_cut_spare_referenced_status` CHECK ((((`integration_status_code` <> _utf8mb4'EXTERNAL_REFERENCED') or ((`external_request_id` is not null) and (`external_application_no` is not null))) = true))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='F-CUT-010备件申请外部引用';

CREATE TABLE `cut_spare_manual_evidence` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `task_id` bigint NOT NULL,
  `application_reference_id` bigint DEFAULT NULL,
  `file_artifact_id` bigint NOT NULL,
  `file_reference_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `file_version_no` int NOT NULL,
  `file_fact_version` json DEFAULT NULL COMMENT '旧文件三项事实水位原件；新业务写入NULL，禁止更改历史原值',
  `file_scope_version` bigint NOT NULL,
  `description` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `upload_user_id` bigint NOT NULL,
  `create_time` datetime(3) NOT NULL,
  `file_artifact_fact_version` bigint DEFAULT NULL COMMENT '文件工件事实水位；历史原件缺失时可空，新业务按既有来源/提交规则必填',
  `file_reference_fact_version` bigint DEFAULT NULL COMMENT '文件引用事实水位；历史原件缺失时可空，新业务按既有来源/提交规则必填',
  `file_availability_fact_version` bigint DEFAULT NULL COMMENT '文件可用性事实水位；历史原件缺失时可空，新业务按既有来源/提交规则必填',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cut_spare_manual_file` (`tenant_id`,`task_id`,`file_artifact_id`,`file_version_no`),
  KEY `idx_cut_spare_manual_task` (`tenant_id`,`task_id`,`id`),
  KEY `idx_cut_spare_manual_application` (`tenant_id`,`application_reference_id`,`id`),
  KEY `fk_cut_spare_manual_application` (`application_reference_id`),
  KEY `fk_cut_spare_manual_task` (`task_id`),
  CONSTRAINT `fk_cut_spare_manual_application` FOREIGN KEY (`application_reference_id`) REFERENCES `cut_spare_application_reference` (`id`),
  CONSTRAINT `fk_cut_spare_manual_task` FOREIGN KEY (`task_id`) REFERENCES `cut_task` (`id`),
  CONSTRAINT `chk_cut_spare_manual_description` CHECK (((char_length(`description`) between 1 and 1000) and (char_length(`description`) = char_length(trim(`description`))))),
  CONSTRAINT `chk_cut_spare_manual_file_fact` CHECK ((coalesce(((`file_artifact_fact_version` is not null) and (`file_reference_fact_version` is not null) and (`file_availability_fact_version` is not null) and (`file_artifact_fact_version` >= 0) and (`file_reference_fact_version` >= 0) and (`file_availability_fact_version` >= 0)),false) = true)),
  CONSTRAINT `chk_cut_spare_manual_reference` CHECK (((char_length(`file_reference_key`) between 1 and 128) and (char_length(`file_reference_key`) = char_length(trim(`file_reference_key`))))),
  CONSTRAINT `chk_cut_spare_manual_values` CHECK ((((`file_artifact_id` > 0) and (`file_version_no` > 0) and (`file_scope_version` >= 0) and (`upload_user_id` > 0)) = true))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='F-CUT-010人工备件证据不可变引用';

CREATE TABLE `cut_spare_need_source` (
  `id` bigint NOT NULL COMMENT '本表主键',
  `tenant_id` bigint NOT NULL COMMENT '所属租户；必须与父对象一致',
  `application_reference_id` bigint NOT NULL COMMENT '外部申请引用',
  `source_type_code` varchar(32) NOT NULL COMMENT 'ASSESSMENT或CHECKLIST_RISK',
  `assessment_id` bigint DEFAULT NULL COMMENT '评估来源ID',
  `assessment_version` bigint DEFAULT NULL COMMENT '评估来源版本',
  `checklist_item_id` bigint DEFAULT NULL COMMENT '当时适用的重大备件采集项',
  `checklist_item_version` bigint DEFAULT NULL COMMENT '该清单项当时的并发版本；与结果修订无关',
  `spare_part_applied_flag` bit(1) DEFAULT NULL COMMENT '当时评估备件判断',
  `applicable_flag` bit(1) DEFAULT NULL COMMENT '当时清单项适用事实',
  `sort_order` int NOT NULL COMMENT '原顺序',
  `create_user_id` bigint NOT NULL COMMENT '创建人；历史投影由迁移执行身份记录，不冒充原业务办理人',
  `create_time` datetime(3) NOT NULL COMMENT '本行创建时间；原业务发生时间另按来源字段保留',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_owner_id` (`tenant_id`,`id`),
  UNIQUE KEY `uk_business_1` (`tenant_id`,`application_reference_id`,`assessment_id`),
  UNIQUE KEY `uk_business_2` (`tenant_id`,`application_reference_id`,`checklist_item_id`),
  KEY `fk_cut_structured_76` (`tenant_id`,`assessment_id`),
  KEY `fk_cut_structured_77` (`tenant_id`,`checklist_item_id`),
  CONSTRAINT `fk_cut_structured_75` FOREIGN KEY (`tenant_id`, `application_reference_id`) REFERENCES `cut_spare_application_reference` (`tenant_id`, `id`),
  CONSTRAINT `fk_cut_structured_76` FOREIGN KEY (`tenant_id`, `assessment_id`) REFERENCES `cut_assessment` (`tenant_id`, `id`),
  CONSTRAINT `fk_cut_structured_77` FOREIGN KEY (`tenant_id`, `checklist_item_id`) REFERENCES `cut_cutover_checklist_item` (`tenant_id`, `id`),
  CONSTRAINT `chk_spare_need_source_1` CHECK ((((`source_type_code` = _utf8mb4'ASSESSMENT') and (`assessment_id` is not null) and (`assessment_version` is not null) and (`assessment_version` > 0) and (`spare_part_applied_flag` = 0x01) and (`spare_part_applied_flag` is not null) and (`checklist_item_id` is null) and (`checklist_item_version` is null) and (`applicable_flag` is null)) or ((`source_type_code` = _utf8mb4'CHECKLIST_RISK') and (`checklist_item_id` is not null) and (`checklist_item_version` is not null) and (`checklist_item_version` >= 0) and (`applicable_flag` = 0x01) and (`applicable_flag` is not null) and (`assessment_id` is null) and (`assessment_version` is null) and (`spare_part_applied_flag` is null))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='备件需求来源';

CREATE TABLE `cut_spare_request_device` (
  `id` bigint NOT NULL COMMENT '本表主键',
  `tenant_id` bigint NOT NULL COMMENT '所属租户；必须与父对象一致',
  `application_reference_id` bigint NOT NULL COMMENT '外部申请引用',
  `device_id` bigint NOT NULL COMMENT '设备ID',
  `sn` varchar(128) NOT NULL COMMENT '当时序列号',
  `project_assignment_version` bigint NOT NULL COMMENT '当时归属水位',
  `sort_order` int NOT NULL COMMENT '原顺序',
  `create_user_id` bigint NOT NULL COMMENT '创建人；历史投影由迁移执行身份记录，不冒充原业务办理人',
  `create_time` datetime(3) NOT NULL COMMENT '本行创建时间；原业务发生时间另按来源字段保留',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_owner_id` (`tenant_id`,`id`),
  UNIQUE KEY `uk_business_1` (`tenant_id`,`application_reference_id`,`device_id`),
  CONSTRAINT `fk_cut_structured_78` FOREIGN KEY (`tenant_id`, `application_reference_id`) REFERENCES `cut_spare_application_reference` (`tenant_id`, `id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='备件请求设备范围';

CREATE TABLE `cut_spare_status_revision` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `application_reference_id` bigint NOT NULL,
  `status_version` bigint NOT NULL,
  `external_status_raw` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `status_snapshot` json DEFAULT NULL COMMENT '旧外部备件状态载荷原件；新业务写入NULL，禁止更改历史原值',
  `source_type_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `observe_time` datetime(3) NOT NULL,
  `external_occur_time` datetime(3) DEFAULT NULL,
  `event_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `correlation_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `current_marker` tinyint DEFAULT NULL,
  `create_user_id` bigint NOT NULL,
  `create_time` datetime(3) NOT NULL,
  `source_payload_digest` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '规范化接收载荷摘要，仅保持幂等冲突检测，不替代业务字段；历史原件缺失时可空，新业务按既有来源/提交规则必填',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cut_spare_status_version` (`tenant_id`,`application_reference_id`,`status_version`),
  UNIQUE KEY `uk_cut_spare_status_event` (`tenant_id`,`event_id`),
  UNIQUE KEY `uk_cut_spare_status_current` (`tenant_id`,`application_reference_id`,`current_marker`),
  KEY `idx_cut_spare_status_order` (`tenant_id`,`application_reference_id`,`status_version`,`id`),
  KEY `fk_cut_spare_status_application` (`application_reference_id`),
  CONSTRAINT `fk_cut_spare_status_application` FOREIGN KEY (`application_reference_id`) REFERENCES `cut_spare_application_reference` (`id`),
  CONSTRAINT `chk_cut_spare_status_correlation` CHECK (((char_length(`correlation_id`) between 1 and 128) and (char_length(`correlation_id`) = char_length(trim(`correlation_id`))))),
  CONSTRAINT `chk_cut_spare_status_event` CHECK (((char_length(`event_id`) between 1 and 128) and (char_length(`event_id`) = char_length(trim(`event_id`))))),
  CONSTRAINT `chk_cut_spare_status_marker` CHECK (((`current_marker` is null) or (`current_marker` = 1))),
  CONSTRAINT `chk_cut_spare_status_raw` CHECK (((char_length(`external_status_raw`) between 1 and 128) and (char_length(`external_status_raw`) = char_length(trim(`external_status_raw`))))),
  CONSTRAINT `chk_cut_spare_status_snapshot` CHECK ((((`source_payload_digest` is null) or regexp_like(`source_payload_digest`,_utf8mb4'^[0-9a-f]{64}$',_utf8mb4'c')) = true)),
  CONSTRAINT `chk_cut_spare_status_source` CHECK (((`source_type_code` in (_utf8mb4'INITIATE_RESPONSE',_utf8mb4'CALLBACK',_utf8mb4'REFRESH')) = true)),
  CONSTRAINT `chk_cut_spare_status_values` CHECK ((((`status_version` > 0) and (`create_user_id` >= 0)) = true))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='F-CUT-010外部备件状态不可变版本';

CREATE TABLE `cut_step` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `plan_revision_id` bigint NOT NULL,
  `section_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `step_no` int NOT NULL,
  `content` varchar(4000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `version` int NOT NULL,
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `create_time` datetime(3) NOT NULL,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `update_time` datetime(3) NOT NULL,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `step_name` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '填写值：步骤名称',
  `test_result` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '填写值：测试结果',
  `business_impact_time` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '填写值：业务影响时间说明',
  `operator_name` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '填写值：操作人员说明',
  `operation_time` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '填写值：操作时间说明，保持自由文本',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cut_step_order` (`tenant_id`,`plan_revision_id`,`section_code`,`step_no`),
  KEY `idx_cut_step_plan` (`tenant_id`,`plan_revision_id`,`section_code`,`step_no`,`id`),
  KEY `fk_cut_step_plan` (`plan_revision_id`),
  CONSTRAINT `fk_cut_step_plan` FOREIGN KEY (`plan_revision_id`) REFERENCES `cut_plan_revision` (`id`),
  CONSTRAINT `chk_cut_step_section` CHECK ((`section_code` in (_utf8mb4'PRE_OPERATION',_utf8mb4'OPERATION',_utf8mb4'CLOSING_COLLECTION',_utf8mb4'POST_BUSINESS_TEST',_utf8mb4'ROLLBACK',_utf8mb4'POST_CUTOVER_SUPPORT'))),
  CONSTRAINT `chk_cut_step_values` CHECK (((`step_no` > 0) and (`version` >= 0) and (char_length(trim(`content`)) between 1 and 4000)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='F-CUT-004方案步骤';

CREATE TABLE `cut_task` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `project_id` bigint NOT NULL,
  `previous_task_id` bigint DEFAULT NULL,
  `task_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `task_name` varchar(282) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `background` varchar(4000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cutover_type_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `network_mode_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `schedule_time` datetime(3) DEFAULT NULL,
  `task_origin_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `intake_source_type_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_system` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source_business_no` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `business_event_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `current_stage_code` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `task_status_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `owner_user_id` bigint DEFAULT NULL,
  `customer_id` bigint DEFAULT NULL,
  `implementation_readiness_snapshot_id` bigint DEFAULT NULL,
  `implementation_readiness_snapshot_version` bigint DEFAULT NULL,
  `project_scope_version` bigint DEFAULT NULL,
  `project_context_snapshot` json DEFAULT NULL COMMENT '旧项目上下文原件；新业务写入NULL，禁止更改历史原值',
  `device_scope_watermark` json DEFAULT NULL COMMENT '旧设备范围水位原件；新业务写入NULL，禁止更改历史原值',
  `customer_context_snapshot` json DEFAULT NULL COMMENT '旧客户等级来源事实原件；新业务写入NULL，禁止更改历史原值',
  `readiness_context_snapshot` json DEFAULT NULL COMMENT '旧准入就绪来源事实原件；新业务写入NULL，禁止更改历史原值',
  `manual_grade_code` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `current_assessment_id` bigint DEFAULT NULL,
  `configuration_revision_id` bigint DEFAULT NULL,
  `configuration_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `configuration_revision_no` int DEFAULT NULL,
  `legacy_task_id` bigint DEFAULT NULL,
  `legacy_cutover_type_raw` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `legacy_network_mode_raw` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `legacy_status_value` tinyint DEFAULT NULL,
  `legacy_source_version` int DEFAULT NULL,
  `legacy_mapping_version` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `version` int NOT NULL,
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `create_time` datetime(3) NOT NULL,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `update_time` datetime(3) NOT NULL,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `project_version` bigint DEFAULT NULL COMMENT '来源项目版本；历史原件缺失时可空，新业务按既有来源/提交规则必填',
  `project_code` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源项目编码；历史原件缺失时可空，新业务按既有来源/提交规则必填',
  `project_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源项目名称；历史原件缺失时可空，新业务按既有来源/提交规则必填',
  `customer_code` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源客户编码',
  `customer_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源客户名称',
  `department_id` bigint DEFAULT NULL COMMENT '来源部门ID',
  `department_code` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源部门编码',
  `department_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源部门名称',
  `customer_fact_status_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '原客户等级事实状态；原无事实时不造默认状态',
  `service_level_revision_id` bigint DEFAULT NULL COMMENT '客户服务等级修订引用',
  `service_level_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源服务等级编码',
  `customer_fact_version` bigint DEFAULT NULL COMMENT 'CustomerLevelFact.factVersion；保留long类型',
  `service_level_effective_start_time` datetime(3) DEFAULT NULL COMMENT '来源等级生效时间',
  `service_level_effective_end_time` datetime(3) DEFAULT NULL COMMENT '来源等级失效时间',
  `readiness_decision_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '所引用就绪快照的原结论；独立准入不造READY',
  `service_level_source_record_id` bigint DEFAULT NULL COMMENT 'CUS maintenance record ID, not revision ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cut_task_project_no` (`tenant_id`,`project_id`,`task_no`),
  UNIQUE KEY `uk_cut_task_previous` (`tenant_id`,`previous_task_id`),
  UNIQUE KEY `uk_cut_task_source` (`tenant_id`,`source_system`,`source_business_no`),
