P2') and (`to_status_code` = _utf8mb4'GRADE_CONFIRMING')) or ((`from_stage_code` = _utf8mb4'P4') and (`from_status_code` = _utf8mb4'PLAN_DRAFTING') and (((`to_stage_code` = _utf8mb4'P2') and (`to_status_code` = _utf8mb4'GRADE_CONFIRMING')) or ((`to_stage_code` = _utf8mb4'P3') and (`to_status_code` = _utf8mb4'SURVEYING')))) or ((`from_stage_code` = _utf8mb4'P5') and (`from_status_code` = _utf8mb4'APPROVING') and (((`to_stage_code` = _utf8mb4'P2') and (`to_status_code` = _utf8mb4'GRADE_CONFIRMING')) or ((`to_stage_code` = _utf8mb4'P3') and (`to_status_code` = _utf8mb4'SURVEYING')) or ((`to_stage_code` = _utf8mb4'P4') and (`to_status_code` = _utf8mb4'PLAN_DRAFTING'))))))),false) = true)),
