  `revision_no` int NOT NULL,
  `difference_type` varchar(48) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `resolution_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'OPEN',
  `reason` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `risk_description` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `scope_snapshot` json NOT NULL,
  `project_fact_version` bigint DEFAULT NULL,
  `fact_impact_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `approved_by` bigint DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `exemption_expires_at` datetime DEFAULT NULL,
  `evidence_id` bigint DEFAULT NULL,
  `evidence_revision` int DEFAULT NULL,
  `current_marker` tinyint DEFAULT '1',
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_imp_arrival_difference_tenant_id` (`tenant_id`,`id`),
  UNIQUE KEY `uk_imp_arrival_difference_revision` (`tenant_id`,`arrival_acceptance_id`,`difference_no`,`revision_no`),
  UNIQUE KEY `uk_imp_arrival_difference_current` (`tenant_id`,`arrival_acceptance_id`,`difference_no`,`current_marker`),
  KEY `idx_imp_arrival_difference_line` (`tenant_id`,`arrival_line_id`,`resolution_status`,`id`),
  KEY `idx_imp_arrival_difference_evidence` (`tenant_id`,`evidence_id`,`evidence_revision`),
  CONSTRAINT `fk_imp_arrival_difference_evidence` FOREIGN KEY (`tenant_id`, `evidence_id`, `evidence_revision`) REFERENCES `imp_delivery_evidence_revision` (`tenant_id`, `evidence_id`, `revision_no`),
  CONSTRAINT `fk_imp_arrival_difference_line` FOREIGN KEY (`tenant_id`, `arrival_line_id`) REFERENCES `imp_arrival_line` (`tenant_id`, `id`),
  CONSTRAINT `fk_imp_arrival_difference_root` FOREIGN KEY (`tenant_id`, `arrival_acceptance_id`) REFERENCES `imp_arrival_acceptance` (`tenant_id`, `id`),
  CONSTRAINT `chk_imp_arrival_difference_current` CHECK (((`current_marker` is null) or (`current_marker` = 1))),
  CONSTRAINT `chk_imp_arrival_difference_exemption` CHECK (((`resolution_status` <> _utf8mb4'EXEMPTED') or ((`approved_by` is not null) and (`approved_at` is not null) and (`evidence_id` is not null) and (`evidence_revision` > 0)))),
  CONSTRAINT `chk_imp_arrival_difference_fact_impact` CHECK (((`fact_impact_type` is null) or (`fact_impact_type` in (_utf8mb4'CORRECTION',_utf8mb4'REOPEN',_utf8mb4'EXEMPTION_INVALIDATION')))),
  CONSTRAINT `chk_imp_arrival_difference_fact_pair` CHECK ((((`project_fact_version` is null) and (`fact_impact_type` is null)) or ((`project_fact_version` is not null) and (`fact_impact_type` is not null)))),
  CONSTRAINT `chk_imp_arrival_difference_fact_version` CHECK (((`project_fact_version` is null) or (`project_fact_version` >= 0))),
  CONSTRAINT `chk_imp_arrival_difference_revision` CHECK (((`difference_no` > 0) and (`revision_no` > 0))),
  CONSTRAINT `chk_imp_arrival_difference_status` CHECK ((`resolution_status` in (_utf8mb4'OPEN',_utf8mb4'SUPPLEMENTED',_utf8mb4'REJECTED',_utf8mb4'EXEMPTED',_utf8mb4'CLOSED'))),
  CONSTRAINT `chk_imp_arrival_difference_type` CHECK ((`difference_type` in (_utf8mb4'QUANTITY_MISMATCH',_utf8mb4'MODEL_OR_SN_MISMATCH',_utf8mb4'APPEARANCE_OR_QUALITY',_utf8mb4'EVIDENCE_INCOMPLETE')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='EXE-01到货差异拒收与明确豁免追加版本';

CREATE TABLE `imp_arrival_line` (
  `id` bigint NOT NULL,
  `arrival_acceptance_id` bigint NOT NULL,
  `line_no` int NOT NULL,
  `line_revision` int NOT NULL,
  `scope_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `device_id` bigint DEFAULT NULL,
  `device_assignment_version` bigint DEFAULT NULL,
  `order_line_id` bigint DEFAULT NULL,
  `product_code` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `product_model` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '产品型号/物料型号（原model_code）',
  `expected_quantity` decimal(20,6) NOT NULL,
  `accepted_quantity` decimal(20,6) NOT NULL DEFAULT '0.000000',
  `unit` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'NOT_ARRIVED',
  `current_marker` tinyint DEFAULT '1',
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_imp_arrival_line_tenant_id` (`tenant_id`,`id`),
  UNIQUE KEY `uk_imp_arrival_line_revision` (`tenant_id`,`arrival_acceptance_id`,`line_no`,`line_revision`),
  UNIQUE KEY `uk_imp_arrival_line_current` (`tenant_id`,`arrival_acceptance_id`,`line_no`,`current_marker`),
  KEY `idx_imp_arrival_line_device` (`tenant_id`,`device_id`,`status`,`arrival_acceptance_id`,`id`),
  KEY `idx_imp_arrival_line_order` (`tenant_id`,`order_line_id`,`product_model`,`status`,`arrival_acceptance_id`,`id`),
  CONSTRAINT `fk_imp_arrival_line_root` FOREIGN KEY (`tenant_id`, `arrival_acceptance_id`) REFERENCES `imp_arrival_acceptance` (`tenant_id`, `id`),
  CONSTRAINT `chk_imp_arrival_line_current` CHECK (((`current_marker` is null) or (`current_marker` = 1))),
  CONSTRAINT `chk_imp_arrival_line_quantity` CHECK (((`expected_quantity` >= 0) and (`accepted_quantity` >= 0) and (`accepted_quantity` <= `expected_quantity`))),
  CONSTRAINT `chk_imp_arrival_line_revision` CHECK (((`line_no` > 0) and (`line_revision` > 0))),
  CONSTRAINT `chk_imp_arrival_line_scope` CHECK ((((`scope_type` = _utf8mb4'DEVICE') and (`device_id` is not null) and (`device_assignment_version` is not null) and (`order_line_id` is null)) or ((`scope_type` = _utf8mb4'ORDER_MODEL_QUANTITY') and (`device_id` is null) and (`order_line_id` is not null) and ((`product_code` is not null) or (`product_model` is not null))))),
  CONSTRAINT `chk_imp_arrival_line_scope_type` CHECK ((`scope_type` in (_utf8mb4'DEVICE',_utf8mb4'ORDER_MODEL_QUANTITY'))),
  CONSTRAINT `chk_imp_arrival_line_status` CHECK ((`status` in (_utf8mb4'NOT_ARRIVED',_utf8mb4'ACCEPTED',_utf8mb4'DIFFERENCE_PENDING',_utf8mb4'REJECTED')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='EXE-01到货签收明细追加版本';

CREATE TABLE `imp_collection_log` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `entry` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `object_id` bigint NOT NULL,
  `project_id` bigint NOT NULL,
  `device_id` bigint NOT NULL,
  `execution_id` bigint NOT NULL,
  `actor_id` bigint NOT NULL,
  `platform_task_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `result_version` bigint NOT NULL,
