  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_imp_collection_log_result` (`tenant_id`,`platform_task_id`,`result_version`),
  KEY `idx_imp_collection_log_source` (`tenant_id`,`entry`,`object_id`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `imp_configuration_collection` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `configuration_id` bigint NOT NULL,
  `equipment_id` bigint NOT NULL,
  `actor_id` bigint NOT NULL,
  `request_key` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `request_digest` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `platform_task_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
