  UNIQUE KEY `uk_imp_configuration_collection_task` (`tenant_id`,`platform_task_id`),
  KEY `idx_imp_configuration_collection_history` (`tenant_id`,`configuration_id`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `imp_cutover_readiness_device` (
  `id` bigint NOT NULL COMMENT '本表主键',
  `tenant_id` bigint NOT NULL COMMENT '所属租户；必须与父对象一致',
  `snapshot_id` bigint NOT NULL COMMENT '原IMP快照ID',
  `device_id` bigint NOT NULL COMMENT '设备ID',
  `sn` varchar(128) NOT NULL COMMENT '来源序列号',
  `project_assignment_version` bigint NOT NULL COMMENT '来源归属水位',
  `sort_order` int NOT NULL COMMENT '原顺序',
  `create_user_id` bigint NOT NULL COMMENT '创建人；历史投影由迁移执行身份记录，不冒充原业务办理人',
  `create_time` datetime(3) NOT NULL COMMENT '本行创建时间；原业务发生时间另按来源字段保留',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_owner_id` (`tenant_id`,`id`),
  UNIQUE KEY `uk_business_1` (`tenant_id`,`snapshot_id`,`device_id`),
  CONSTRAINT `fk_cut_structured_79` FOREIGN KEY (`tenant_id`, `snapshot_id`) REFERENCES `imp_cutover_readiness_snapshot` (`tenant_id`, `id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='IMP就绪冻结设备';

CREATE TABLE `imp_cutover_readiness_snapshot` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint NOT NULL,
  `project_id` bigint NOT NULL,
  `device_scope_key` char(64) NOT NULL,
  `snapshot_no` int NOT NULL,
  `readiness_decision_code` varchar(16) NOT NULL,
  `context_json` json DEFAULT NULL COMMENT '旧IMP就绪来源上下文原件；新业务写入NULL，禁止更改历史原值',
  `unmet_codes_json` json DEFAULT NULL COMMENT '旧IMP未满足原因集合原件；新业务写入NULL，禁止更改历史原值',
  `evaluate_user_id` bigint NOT NULL,
  `creator` varchar(64) NOT NULL DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) NOT NULL DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `project_scope_version` bigint DEFAULT NULL COMMENT '冻结项目范围版本；历史原件缺失时可空，新业务按既有来源/提交规则必填',
  `approved_plan_id` bigint DEFAULT NULL COMMENT '原已批准实施计划ID；历史原件缺失时可空，新业务按既有来源/提交规则必填',
  `approved_plan_version` bigint DEFAULT NULL COMMENT '原计划版本；历史原件缺失时可空，新业务按既有来源/提交规则必填',
  `project_plan_version_id` bigint DEFAULT NULL COMMENT 'PROJ显式适用性的冻结计划ID',
  `project_plan_version` bigint DEFAULT NULL COMMENT 'PROJ冻结计划版本',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_imp_cutover_readiness_no` (`tenant_id`,`project_id`,`snapshot_no`),
  UNIQUE KEY `uk_cut_structured_owner_id` (`tenant_id`,`id`),
  KEY `idx_imp_cutover_readiness_scope` (`tenant_id`,`project_id`,`device_scope_key`,`snapshot_no`),
  CONSTRAINT `chk_imp_cutover_readiness_decision` CHECK (((`readiness_decision_code` in (_utf8mb4'READY',_utf8mb4'NOT_READY')) = true)),
  CONSTRAINT `chk_imp_cutover_readiness_number` CHECK ((`snapshot_no` > 0)),
  CONSTRAINT `chk_imp_readiness_project_plan` CHECK ((((`project_plan_version_id` is null) and (`project_plan_version` is null)) or ((`project_plan_version_id` is not null) and (`project_plan_version` is not null) and (`project_plan_version_id` > 0) and (`project_plan_version` >= 0))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='EXE-06割接前不可变就绪校验快照';

CREATE TABLE `imp_cutover_readiness_source` (
  `id` bigint NOT NULL COMMENT '本表主键',
  `tenant_id` bigint NOT NULL COMMENT '所属租户；必须与父对象一致',
  `snapshot_id` bigint NOT NULL COMMENT '原IMP快照ID',
  `source_code` varchar(32) NOT NULL COMMENT 'EXE_01～EXE_04原来源',
  `completion_status_code` varchar(32) NOT NULL COMMENT '原来源完成状态',
  `fact_version` bigint NOT NULL COMMENT '原来源事实版本',
  `reopened_flag` bit(1) NOT NULL COMMENT '原来源是否重开',
  `create_user_id` bigint NOT NULL COMMENT '创建人；历史投影由迁移执行身份记录，不冒充原业务办理人',
  `create_time` datetime(3) NOT NULL COMMENT '本行创建时间；原业务发生时间另按来源字段保留',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_owner_id` (`tenant_id`,`id`),
  UNIQUE KEY `uk_business_1` (`tenant_id`,`snapshot_id`,`source_code`),
  CONSTRAINT `fk_cut_structured_80` FOREIGN KEY (`tenant_id`, `snapshot_id`) REFERENCES `imp_cutover_readiness_snapshot` (`tenant_id`, `id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='IMP实施完成来源';

CREATE TABLE `imp_cutover_readiness_source_object` (
  `id` bigint NOT NULL COMMENT '本表主键',
  `tenant_id` bigint NOT NULL COMMENT '所属租户；必须与父对象一致',
  `source_fact_id` bigint NOT NULL COMMENT '所属快照来源事实',
  `source_object_id` bigint NOT NULL COMMENT '原来源对象ID',
  `sort_order` int NOT NULL COMMENT '原顺序',
  `create_user_id` bigint NOT NULL COMMENT '创建人；历史投影由迁移执行身份记录，不冒充原业务办理人',
  `create_time` datetime(3) NOT NULL COMMENT '本行创建时间；原业务发生时间另按来源字段保留',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_owner_id` (`tenant_id`,`id`),
  UNIQUE KEY `uk_business_1` (`tenant_id`,`source_fact_id`,`source_object_id`),
  CONSTRAINT `fk_cut_structured_81` FOREIGN KEY (`tenant_id`, `source_fact_id`) REFERENCES `imp_cutover_readiness_source` (`tenant_id`, `id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='IMP来源业务对象集合';

CREATE TABLE `imp_cutover_readiness_source_watermark` (
  `id` bigint NOT NULL COMMENT '本表主键',
  `tenant_id` bigint NOT NULL COMMENT '所属租户；必须与父对象一致',
  `source_fact_id` bigint NOT NULL COMMENT '所属快照来源事实',
  `axis_code` varchar(64) NOT NULL COMMENT '原水位轴',
  `object_id` bigint NOT NULL COMMENT '原水位对象',
  `fact_version` bigint NOT NULL COMMENT '该轴/对象的原水位',
  `create_user_id` bigint NOT NULL COMMENT '创建人；历史投影由迁移执行身份记录，不冒充原业务办理人',
  `create_time` datetime(3) NOT NULL COMMENT '本行创建时间；原业务发生时间另按来源字段保留',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_owner_id` (`tenant_id`,`id`),
  UNIQUE KEY `uk_business_1` (`tenant_id`,`source_fact_id`,`axis_code`,`object_id`),
  CONSTRAINT `fk_cut_structured_82` FOREIGN KEY (`tenant_id`, `source_fact_id`) REFERENCES `imp_cutover_readiness_source` (`tenant_id`, `id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='IMP来源水位集合';

CREATE TABLE `imp_cutover_readiness_unmet` (
  `id` bigint NOT NULL COMMENT '本表主键',
  `tenant_id` bigint NOT NULL COMMENT '所属租户；必须与父对象一致',
  `snapshot_id` bigint NOT NULL COMMENT '原IMP快照ID',
  `unmet_code` varchar(128) NOT NULL COMMENT '原未满足原因编码',
  `sort_order` int NOT NULL COMMENT '原顺序',
  `create_user_id` bigint NOT NULL COMMENT '创建人；历史投影由迁移执行身份记录，不冒充原业务办理人',
  `create_time` datetime(3) NOT NULL COMMENT '本行创建时间；原业务发生时间另按来源字段保留',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_owner_id` (`tenant_id`,`id`),
  UNIQUE KEY `uk_business_1` (`tenant_id`,`snapshot_id`,`unmet_code`),
  CONSTRAINT `fk_cut_structured_83` FOREIGN KEY (`tenant_id`, `snapshot_id`) REFERENCES `imp_cutover_readiness_snapshot` (`tenant_id`, `id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='IMP未满足原因集合';

CREATE TABLE `imp_delivery_evidence` (
  `id` bigint NOT NULL,
  `project_id` bigint NOT NULL,
  `source_requirement` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_object_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_object_id` bigint NOT NULL,
  `current_revision_no` int NOT NULL,
  `acc_sync_status` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'NOT_PUBLISHED',
  `acc_last_published_at` datetime DEFAULT NULL,
  `acc_next_retry_at` datetime DEFAULT NULL,
  `acc_retry_count` int NOT NULL DEFAULT '0',
  `acc_last_event_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `acc_correlation_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `acc_accepted_record_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `acc_archived_record_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_imp_delivery_evidence_tenant_id` (`tenant_id`,`id`),
  UNIQUE KEY `uk_imp_delivery_evidence_source` (`tenant_id`,`source_requirement`,`source_object_type`,`source_object_id`),
  KEY `idx_imp_delivery_evidence_project` (`tenant_id`,`project_id`,`source_requirement`,`acc_sync_status`,`id`),
  KEY `idx_imp_delivery_evidence_retry` (`tenant_id`,`acc_sync_status`,`acc_next_retry_at`,`id`),
  CONSTRAINT `chk_imp_delivery_evidence_correlation` CHECK ((((`acc_sync_status` = _utf8mb4'NOT_PUBLISHED') and (`acc_correlation_id` is null)) or ((`acc_sync_status` <> _utf8mb4'NOT_PUBLISHED') and (`acc_correlation_id` is not null) and (char_length(trim(`acc_correlation_id`)) between 1 and 128) and (char_length(`acc_correlation_id`) = char_length(trim(`acc_correlation_id`)))))),
  CONSTRAINT `chk_imp_delivery_evidence_retry_count` CHECK ((`acc_retry_count` >= 0)),
  CONSTRAINT `chk_imp_delivery_evidence_revision` CHECK ((`current_revision_no` > 0)),
  CONSTRAINT `chk_imp_delivery_evidence_source` CHECK (((`source_requirement` = _utf8mb4'EXE-01') and (`source_object_type` = _utf8mb4'ARRIVAL_ACCEPTANCE'))),
  CONSTRAINT `chk_imp_delivery_evidence_sync_status` CHECK ((`acc_sync_status` in (_utf8mb4'NOT_PUBLISHED',_utf8mb4'PUBLISHED_PENDING_ACC',_utf8mb4'ARCHIVE_PENDING_RETRY',_utf8mb4'ACCEPTED_PENDING_ARCHIVE',_utf8mb4'ARCHIVE_ACK_PENDING_RETRY',_utf8mb4'ARCHIVED')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='EXE-01到货签收证据根及ACC同步投影';

CREATE TABLE `imp_delivery_evidence_revision` (
  `id` bigint NOT NULL,
  `evidence_id` bigint NOT NULL,
  `revision_no` int NOT NULL,
  `file_artifact_id` bigint NOT NULL,
  `file_reference_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `file_version_no` int NOT NULL,
  `file_scope_version` bigint NOT NULL,
  `file_fact_version` json NOT NULL,
  `file_hash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_record_id` bigint NOT NULL,
  `source_version` bigint NOT NULL,
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_imp_delivery_evidence_revision_id` (`tenant_id`,`id`),
  UNIQUE KEY `uk_imp_delivery_evidence_revision` (`tenant_id`,`evidence_id`,`revision_no`),
  KEY `idx_imp_delivery_evidence_file` (`tenant_id`,`file_reference_id`,`file_version_no`,`id`),
  CONSTRAINT `fk_imp_delivery_evidence_revision_root` FOREIGN KEY (`tenant_id`, `evidence_id`) REFERENCES `imp_delivery_evidence` (`tenant_id`, `id`),
  CONSTRAINT `chk_imp_delivery_evidence_file_artifact` CHECK ((`file_artifact_id` > 0)),
  CONSTRAINT `chk_imp_delivery_evidence_file_fact_version` CHECK (((json_type(`file_fact_version`) = _utf8mb4'OBJECT') and (json_length(`file_fact_version`) = 3) and (json_type(json_extract(`file_fact_version`,_utf8mb4'$.artifactVersion')) in (_utf8mb4'INTEGER',_utf8mb4'UNSIGNED INTEGER')) and (json_type(json_extract(`file_fact_version`,_utf8mb4'$.referenceVersion')) in (_utf8mb4'INTEGER',_utf8mb4'UNSIGNED INTEGER')) and (json_type(json_extract(`file_fact_version`,_utf8mb4'$.availabilityVersion')) in (_utf8mb4'INTEGER',_utf8mb4'UNSIGNED INTEGER')) and (cast(json_unquote(json_extract(`file_fact_version`,_utf8mb4'$.artifactVersion')) as signed) >= 0) and (cast(json_unquote(json_extract(`file_fact_version`,_utf8mb4'$.referenceVersion')) as signed) >= 0) and (cast(json_unquote(json_extract(`file_fact_version`,_utf8mb4'$.availabilityVersion')) as signed) >= 0))),
  CONSTRAINT `chk_imp_delivery_evidence_file_scope` CHECK ((`file_scope_version` >= 0)),
  CONSTRAINT `chk_imp_delivery_evidence_file_version` CHECK ((`file_version_no` > 0)),
  CONSTRAINT `chk_imp_delivery_evidence_revision_no` CHECK ((`revision_no` > 0)),
  CONSTRAINT `chk_imp_delivery_evidence_source_version` CHECK ((`source_version` >= 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='EXE-01到货签收不可变证据修订';

CREATE TABLE `imp_eng_arrival` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `project_id` bigint NOT NULL COMMENT '所属项目编号',
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '签收编码，项目内唯一',
  `arrival_time` datetime NOT NULL COMMENT '到货时间',
  `receiver_user_id` bigint DEFAULT NULL COMMENT '签收人',
  `equipment_id` bigint DEFAULT NULL COMMENT '关联设备编号',
  `quantity` int NOT NULL DEFAULT '1' COMMENT '到货数量',
  `inspection_result` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '外观与清单检查结果',
  `exception_record` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '异常记录',
  `attachment_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '签收单附件',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0待签收 1已签收 2异常',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_pms_eng_arrival_code` (`project_id`,`code`),
  KEY `idx_pms_eng_arrival_project` (`project_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='到货签收';

CREATE TABLE `imp_eng_configuration` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `project_id` bigint NOT NULL COMMENT '所属项目编号',
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '配置编码，项目内唯一',
  `equipment_id` bigint NOT NULL COMMENT '设备编号',
  `config_log_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '配置Log文件',
  `debug_result` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '调试结果',
  `debugger_user_id` bigint DEFAULT NULL COMMENT '调试人',
  `debug_time` datetime DEFAULT NULL COMMENT '调试时间',
  `config_snapshot` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '配置档案快照',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0待调试 1进行中 2已完成 3异常',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  `imported_log_file_id` bigint DEFAULT NULL COMMENT 'AST immutable archived log file ID',
  `imported_log_batch_id` bigint DEFAULT NULL COMMENT 'AST immutable log import batch ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_pms_eng_configuration_code` (`project_id`,`code`),
  UNIQUE KEY `uk_imp_configuration_imported_log` (`tenant_id`,`imported_log_file_id`),
  KEY `idx_pms_eng_configuration_project` (`project_id`),
  KEY `idx_pms_eng_configuration_equipment` (`equipment_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='配置调试记录';

CREATE TABLE `imp_eng_deliverable` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `project_id` bigint NOT NULL COMMENT '所属项目编号',
  `phase_id` bigint DEFAULT NULL COMMENT '阶段编号',
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '交付件编码，项目内唯一',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '交付件名称',
  `deliverable_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '类型 DAILY 日报 / RECEIPT 签收单 / SERVICE 服务单 / COMPLETION 完工证明 / TEST 测试记录 / CONFIG 配置档案 / TRAINING 现场培训记录',
  `source_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源业务类型',
  `source_id` bigint DEFAULT NULL COMMENT '来源业务编号',
  `file_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '文件地址',
  `file_size` bigint DEFAULT NULL COMMENT '文件大小',
  `file_checksum` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '文件校验值',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0待归集 1已归集 2已作废',
  `archived_time` datetime DEFAULT NULL COMMENT '归集时间',
  `archived_by` bigint DEFAULT NULL COMMENT '归集人',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_pms_eng_deliverable_code` (`project_id`,`code`),
  KEY `idx_pms_eng_deliverable_project` (`project_id`),
  KEY `idx_pms_eng_deliverable_phase` (`phase_id`),
  KEY `idx_pms_eng_deliverable_source` (`source_type`,`source_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='阶段交付件归集';

CREATE TABLE `imp_eng_doc_template` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `code` varchar(64) NOT NULL COMMENT '模板编号（如 DT-REQ-2026-001），全局唯一',
  `name` varchar(200) NOT NULL COMMENT '模板名称',
  `doc_category` varchar(32) NOT NULL COMMENT '文档类别：REQUIREMENT 需求分析 / SOLUTION 实施方案',
  `parent_template_id` bigint DEFAULT NULL COMMENT '父模板ID（支持继承，NULL表示基础模板）',
  `applicability` json NOT NULL COMMENT '适用条件JSON：projectType/networkType/productType/implementMode/priority/isDefault',
  `description` varchar(500) DEFAULT NULL COMMENT '模板说明',
  `current_version_id` bigint DEFAULT NULL COMMENT '当前生效版本ID（指向 pms_eng_doc_template_version.id）',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '状态：0 草稿 1 已发布 2 已停用',
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本号',
  `creator` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_pms_eng_doc_template_code` (`code`,`tenant_id`),
  KEY `idx_pms_eng_doc_template_category` (`doc_category`,`status`),
  KEY `idx_pms_eng_doc_template_parent` (`parent_template_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='工程文档模板（需求分析/实施方案）';

CREATE TABLE `imp_eng_doc_template_version` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `template_id` bigint NOT NULL COMMENT '模板ID',
  `version_label` varchar(32) NOT NULL COMMENT '版本标签（SemVer，如 1.0.0）',
  `sections` json NOT NULL COMMENT '章节定义JSON（sections数组，每个section含code/title/fields的form-create规则）',
  `section_overrides` json DEFAULT NULL COMMENT '相对父模板的章节覆盖声明（key=章节编码，value=覆盖配置）',
  `excluded_sections` json DEFAULT NULL COMMENT '排除的父模板章节编码列表（如 ["wireless","log_retention"]）',
  `change_log` text COMMENT '版本变更说明',
  `published` tinyint NOT NULL DEFAULT '0' COMMENT '0 未发布 1 已发布（已发布版本不可修改）',
  `creator` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_pms_eng_doc_template_version` (`template_id`,`version_label`,`tenant_id`),
  KEY `idx_pms_eng_doc_template_version_template` (`template_id`,`published`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='工程文档模板版本';

CREATE TABLE `imp_eng_external_procurement` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `project_id` bigint NOT NULL COMMENT '所属项目编号',
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '外采单号，全局唯一',
  `name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '外采名称',
  `procurement_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'GOODS' COMMENT '外采类型 GOODS 物资 / SERVICE 服务',
  `product_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '产品名称/物料名称（含服务名称）',
  `product_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '产品编码/物料编码',
  `specification` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '规格型号',
  `brand` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '品牌',
  `product_model` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '产品型号/物料型号（原model）',
  `quantity` decimal(12,2) NOT NULL COMMENT '数量',
  `unit` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '个' COMMENT '单位',
  `unit_price` decimal(14,2) DEFAULT NULL COMMENT '单价',
  `total_price` decimal(14,2) DEFAULT NULL COMMENT '总价',
  `currency` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'CNY' COMMENT '币种',
  `supplier_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '供应商名称',
  `supplier_contact` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '供应商联系人',
  `supplier_phone` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '供应商电话',
  `needed_date` date DEFAULT NULL COMMENT '需求日期',
  `expected_delivery_date` date DEFAULT NULL COMMENT '预计到货日期',
  `attachment_files` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '附件URL列表（JSON数组）',
  `trigger_source` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MANUAL' COMMENT '触发来源 MANUAL / RESOURCE_READY / SOLUTION',
  `trigger_ref_id` bigint DEFAULT NULL COMMENT '触发来源业务编号',
  `applicant_user_id` bigint NOT NULL COMMENT '申请人编号',
  `apply_time` datetime NOT NULL COMMENT '申请时间',
  `approver_user_id` bigint DEFAULT NULL COMMENT '审批人编号',
  `approve_time` datetime DEFAULT NULL COMMENT '审批时间',
  `approve_opinion` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审批意见',
  `approve_action` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审批动作 PASS/REJECT/RETURN/TRANSFER/COUNTERSIGN',
  `bpm_process_instance_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'BPM流程实例ID',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0草稿 1已提交 2审批中 3已通过 4已驳回 5已撤回 6已终止',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_pms_eng_ext_proc_code` (`code`),
  KEY `idx_pms_eng_ext_proc_project` (`project_id`),
  KEY `idx_pms_eng_ext_proc_status` (`status`),
  KEY `idx_pms_eng_ext_proc_applicant` (`applicant_user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PMS 外采申请单（FR-ENG-002）';

CREATE TABLE `imp_eng_installation` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `project_id` bigint NOT NULL COMMENT '所属项目编号',
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '安装编码，项目内唯一',
  `equipment_id` bigint NOT NULL COMMENT '设备编号',
  `install_location` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '安装位置',
  `address_id` bigint DEFAULT NULL,
  `address_version` int unsigned DEFAULT NULL,
  `site_id` bigint DEFAULT NULL,
  `site_version` int unsigned DEFAULT NULL,
  `site_location_id` bigint DEFAULT NULL,
  `site_location_version` int unsigned DEFAULT NULL,
  `location_resolution_status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'UNRESOLVED',
  `address_snapshot` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `location_snapshot` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `effective_from` datetime(3) DEFAULT NULL,
  `effective_to` datetime(3) DEFAULT NULL,
  `current_equipment_id` bigint GENERATED ALWAYS AS ((case when ((`status` = 2) and (`effective_to` is null) and (`deleted` = 0x00)) then `equipment_id` else NULL end)) STORED,
  `install_time` datetime DEFAULT NULL COMMENT '安装时间',
  `installer_user_id` bigint DEFAULT NULL COMMENT '安装人',
  `environment_check` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '环境检查',
  `spec_check` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '安装规范检查',
  `photo_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '安装照片',
  `result` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '安装结果',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0待安装 1进行中 2已完成 3异常',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_pms_eng_installation_code` (`project_id`,`code`),
  UNIQUE KEY `uk_pms_eng_installation_current_equipment` (`tenant_id`,`current_equipment_id`),
  KEY `idx_pms_eng_installation_project` (`project_id`),
  KEY `idx_pms_eng_installation_equipment` (`equipment_id`),
  KEY `idx_pms_eng_installation_effective` (`tenant_id`,`equipment_id`,`effective_from`,`effective_to`),
  KEY `idx_install_repair_latest` (`tenant_id`,`deleted`,`status`,`equipment_id`,`id`),
  KEY `imp_eng_installation_project_id_IDX` (`project_id`,`id`) USING BTREE,
  CONSTRAINT `chk_pms_eng_installation_location_resolution` CHECK ((`location_resolution_status` in (_utf8mb4'UNRESOLVED',_utf8mb4'RESOLVED')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='硬件安装记录';

CREATE TABLE `imp_eng_issue` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `project_id` bigint NOT NULL COMMENT '所属项目编号',
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '问题编码，项目内唯一',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '问题名称',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '问题描述',
  `source` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'INSTALLATION' COMMENT '来源 INSTALLATION 安装 / CONFIGURATION 配置 / JOINT_TEST 联调 / OTHER 其他',
  `severity` tinyint NOT NULL DEFAULT '1' COMMENT '严重等级 1低 2中 3高',
  `owner_user_id` bigint DEFAULT NULL COMMENT '责任人',
  `deadline` datetime DEFAULT NULL COMMENT '整改时限',
  `solution` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '整改方案',
  `verification_standard` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '验证标准',
  `verify_result` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '复测结果',
  `verified_by` bigint DEFAULT NULL COMMENT '验证人',
  `verified_time` datetime DEFAULT NULL COMMENT '验证时间',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0待处理 1整改中 2待验证 3已关闭 4已挂起',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_pms_eng_issue_code` (`project_id`,`code`),
  KEY `idx_pms_eng_issue_project` (`project_id`),
  KEY `idx_pms_eng_issue_status` (`project_id`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='实施问题与整改';

CREATE TABLE `imp_eng_joint_test` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `project_id` bigint NOT NULL COMMENT '所属项目编号',
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '联调编码，项目内唯一',
  `test_case` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '联调用例',
  `equipment_id` bigint DEFAULT NULL COMMENT '关联设备编号',
  `participants` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '参与方',
  `test_time` datetime DEFAULT NULL COMMENT '联调时间',
  `tester_user_id` bigint DEFAULT NULL COMMENT '联调人',
  `result` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '联调结果',
  `exception_record` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '异常记录',
  `evidence_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '证据附件',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0待联调 1进行中 2通过 3失败',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_pms_eng_joint_test_code` (`project_id`,`code`),
  KEY `idx_pms_eng_joint_test_project` (`project_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='业务联调记录';

CREATE TABLE `imp_eng_material_exchange` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `project_id` bigint NOT NULL COMMENT '所属项目编号',
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '换货单号，全局唯一',
  `name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '换货名称',
  `exchange_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'INCOMPATIBLE' COMMENT '换货类型 INCOMPATIBLE 物料不适配 / DAMAGE 到货损坏 / WRONG 发货错误 / OTHER 其他',
  `device_id` bigint DEFAULT NULL COMMENT '受影响设备编号',
  `product_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '产品名称',
  `product_code` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '产品编码（订单行去重拼接）',
  `product_model` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '产品型号',
  `quantity` decimal(12,2) NOT NULL COMMENT '换货数量',
  `unit` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '个' COMMENT '单位',
  `original_order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '原订单号',
  `reason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '换货原因（富文本）',
  `reason_files` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '原因附件URL列表（JSON数组）',
  `crm_push_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING' COMMENT 'CRM推送状态 PENDING 待推送 / SENT 已推送 / RECEIVED 已接收 / CLOSED 已关闭',
  `crm_push_time` datetime DEFAULT NULL COMMENT 'CRM推送时间',
  `crm_order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '新订单号（CRM回填）',
  `new_device_id` bigint DEFAULT NULL COMMENT '换货后新设备编号',
  `exchange_progress` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '换货进展记录（JSON数组）',
  `applicant_user_id` bigint NOT NULL COMMENT '申请人编号',
  `apply_time` datetime NOT NULL COMMENT '申请时间',
  `approver_user_id` bigint DEFAULT NULL COMMENT '审批人编号',
  `approve_time` datetime DEFAULT NULL COMMENT '审批时间',
  `approve_opinion` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审批意见',
  `approve_action` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审批动作 PASS/REJECT/RETURN/TRANSFER/COUNTERSIGN',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0草稿 1已提交 2审批中 3已通过 4已驳回 5已撤回 6已终止',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_pms_eng_material_exch_code` (`code`),
  KEY `idx_pms_eng_material_exch_project` (`project_id`),
  KEY `idx_pms_eng_material_exch_status` (`status`),
  KEY `idx_pms_eng_material_exch_equipment` (`device_id`),
  KEY `idx_pms_eng_material_exch_crm` (`crm_push_status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PMS 物料不适配与换货协同（FR-ENG-003）';

CREATE TABLE `imp_eng_material_exchange_serial` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `exchange_id` bigint NOT NULL COMMENT '换货申请ID',
  `device_id` bigint DEFAULT NULL COMMENT '设备稳定ID（旧序列号快照，新行不写入）',
  `product_id` bigint DEFAULT NULL COMMENT '换货产品ID（产品信息引用）',
  `quantity` decimal(18,2) NOT NULL DEFAULT '1.00' COMMENT '换货数量',
  `scope_detail_id` bigint DEFAULT NULL COMMENT '设备清单明细拆分行稳定ID（与scope_id二选一）',
  `scope_id` bigint DEFAULT NULL COMMENT '未拆分交付范围行稳定ID（与scope_detail_id二选一）',
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '销售订单号快照',
  `line_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '销售订单行号快照',
  `item_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '物料编码快照',
  `device_type_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '设备类型编码快照',
  `device_type_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '设备类型名称快照',
  `sn` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '设备序列号（旧序列号快照，新行不写入）',
  `product_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '换货产品名称（快照）',
  `product_code` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '换货产品编码（快照）',
  `product_model` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '换货产品型号（快照）',
  `contract_no` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  `active_ref` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci GENERATED ALWAYS AS (if((`deleted` = 0x00),(case when (`scope_detail_id` is not null) then concat(_utf8mb4'D',`scope_detail_id`) when (`scope_id` is not null) then concat(_utf8mb4'S',`scope_id`) when (`device_id` is not null) then concat(_utf8mb4'V',`device_id`) end),NULL)) STORED COMMENT '当前生效清单行引用键',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_exchange_active_ref` (`tenant_id`,`exchange_id`,`active_ref`),
  KEY `idx_exchange_serial` (`tenant_id`,`exchange_id`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='换货申请序列号子表';

CREATE TABLE `imp_eng_material_requisition` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `project_id` bigint NOT NULL COMMENT '所属项目编号',
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '领料单号，全局唯一',
  `name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '领料名称',
  `requisition_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'SPARE' COMMENT '领料类型 SPARE 备件 / TOOL 工具 / CONSUMABLE 耗材',
  `equipment_id` bigint DEFAULT NULL COMMENT '关联设备编号',
  `product_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '产品名称/物料名称',
  `product_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '产品编码/物料编码',
  `specification` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '规格型号',
  `quantity` decimal(12,2) NOT NULL COMMENT '数量',
  `unit` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '个' COMMENT '单位',
  `needed_date` date DEFAULT NULL COMMENT '需求日期',
  `warehouse_id` bigint DEFAULT NULL COMMENT '备件库编号',
  `warehouse_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备件库名称',
  `stock_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '库存状态 IN_STOCK 有库存 / OUT_OF_STOCK 缺货 / RESERVED 已预留',
  `attachment_files` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '附件URL列表（JSON数组）',
  `trigger_source` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MANUAL' COMMENT '触发来源 MANUAL / RESOURCE_READY / SOLUTION',
  `trigger_ref_id` bigint DEFAULT NULL COMMENT '触发来源业务编号',
  `applicant_user_id` bigint NOT NULL COMMENT '申请人编号',
  `apply_time` datetime NOT NULL COMMENT '申请时间',
  `approver_user_id` bigint DEFAULT NULL COMMENT '审批人编号',
  `approve_time` datetime DEFAULT NULL COMMENT '审批时间',
  `approve_opinion` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审批意见',
  `approve_action` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审批动作 PASS/REJECT/RETURN/TRANSFER/COUNTERSIGN',
  `bpm_process_instance_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'BPM流程实例ID',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0草稿 1已提交 2审批中 3已通过 4已驳回 5已撤回 6已终止',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_pms_eng_material_req_code` (`code`),
  KEY `idx_pms_eng_material_req_project` (`project_id`),
  KEY `idx_pms_eng_material_req_status` (`status`),
  KEY `idx_pms_eng_material_req_applicant` (`applicant_user_id`),
  KEY `idx_pms_eng_material_req_equipment` (`equipment_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PMS OA领料申请单（FR-ENG-002）';

CREATE TABLE `imp_eng_risk` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '风险编号（如 RK-2026-001）',
  `project_id` bigint NOT NULL COMMENT '关联项目ID',
  `name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '风险名称',
  `risk_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'SINGLE_DEVICE' COMMENT '风险类型：SINGLE_DEVICE单机/SCENARIO场景',
  `device_id` bigint DEFAULT NULL COMMENT '关联设备ID',
  `device_serial` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '设备序列号',
  `device_model` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '设备型号',
  `scenario` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '风险场景描述',
  `risk_level` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MEDIUM' COMMENT '风险等级：HIGH高/MEDIUM中/LOW低',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '状态：0草稿/1已识别/2已确认/3已同步CRM/4已关闭',
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本号',
  `crm_synced` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否已同步CRM',
  `crm_sync_time` datetime DEFAULT NULL COMMENT 'CRM同步时间',
  `handler_user_id` bigint DEFAULT NULL COMMENT '处理人',
  `handle_opinion` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '处理意见',
  `handle_time` datetime DEFAULT NULL COMMENT '处理时间',
  `creator_user_id` bigint DEFAULT NULL COMMENT '创建人',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_pms_eng_risk_code` (`code`,`tenant_id`),
  KEY `idx_pms_eng_risk_project` (`project_id`),
  KEY `idx_pms_eng_risk_status` (`status`),
  KEY `idx_pms_eng_risk_device` (`device_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='单机风险识别';

CREATE TABLE `imp_eng_training` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `project_id` bigint NOT NULL COMMENT '所属项目编号',
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '培训记录编码，项目内唯一',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '培训名称',
  `contact_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户联系人（自动带入用户联系人）',
  `contact_phone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户联系电话（自动带入）',
  `training_types` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '培训类型，逗号分隔：TECHNICAL_PRINCIPLE/PRODUCT_OPS/OTHER',
  `training_time` date NOT NULL COMMENT '培训时间',
  `trainer_user_id` bigint NOT NULL COMMENT '培训工程师用户编号（默认当前登录人）',
  `trainer_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '培训工程师姓名快照',
  `trainee_count` int DEFAULT NULL COMMENT '参训人数',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '培训内容',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0草稿 1已外发 2客户已确认 3已作废',
  `sign_token_digest` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '外发令牌SHA-256摘要（原始令牌不落库）',
  `token_expires_at` datetime DEFAULT NULL COMMENT '外发令牌有效期',
  `skill_rating` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户评价：培训工程师技术水平及表达能力',
  `effect_rating` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户评价：培训内容及讲解效果',
  `satisfaction_rating` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户评价：培训满意度',
  `sign_opinion` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户综合意见',
  `sign_confirmer_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户签字人',
  `sign_time` datetime DEFAULT NULL COMMENT '客户确认时间',
  `file_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '培训记录表文件地址',
  `file_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '培训记录表文件名',
  `file_size` bigint DEFAULT NULL COMMENT '培训记录表文件大小',
  `file_checksum` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '培训记录表文件SHA-256校验值',
  `version` int NOT NULL DEFAULT '0',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  `confirmation_template_id` bigint DEFAULT NULL COMMENT 'Customer confirmation template',
  `confirmation_revision_id` bigint DEFAULT NULL COMMENT 'Frozen published revision',
  `confirmation_form_rules` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Safe FormCreate issue snapshot',
  `confirmation_values` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Customer confirmation answers',
  `signature_image_data_url` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Validated PNG signature',
  `print_template_id` bigint DEFAULT NULL COMMENT 'Independent print template',
  `print_revision_id` bigint DEFAULT NULL COMMENT 'Published revision captured on selection',
  `print_layout_snapshot` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Validated immutable layout for this selection',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_imp_eng_training_code` (`project_id`,`code`),
  KEY `idx_imp_eng_training_project` (`project_id`),
  KEY `idx_imp_eng_training_digest` (`sign_token_digest`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='现场培训记录（ACC-01）';

CREATE TABLE `imp_training_confirmation_grant` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint NOT NULL,
  `training_id` bigint NOT NULL,
  `issuance_version` bigint NOT NULL,
  `token_digest` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `issued_by_user_id` bigint NOT NULL,
  `issued_at` datetime(3) NOT NULL,
  `expires_at` datetime(3) NOT NULL,
  `scope_version` bigint NOT NULL,
  `confirmation_revision_id` bigint DEFAULT NULL,
  `confirmation_rules_sha256` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_training_grant_issuance` (`tenant_id`,`training_id`,`issuance_version`),
  UNIQUE KEY `uk_training_grant_token` (`tenant_id`,`training_id`,`token_digest`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `infra_api_access_log` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '日志主键',
  `trace_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '链路追踪编号',
  `user_id` bigint NOT NULL DEFAULT '0' COMMENT '用户编号',
  `user_type` tinyint NOT NULL DEFAULT '0' COMMENT '用户类型',
  `application_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '应用名',
  `request_method` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '请求方法名',
  `request_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '请求地址',
  `request_params` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '请求参数',
  `response_body` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '响应结果',
  `user_ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '用户 IP',
  `user_agent` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '浏览器 UA',
  `operate_module` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '操作模块',
  `operate_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '操作名',
  `operate_type` tinyint DEFAULT '0' COMMENT '操作分类',
  `begin_time` datetime NOT NULL COMMENT '开始请求时间',
  `end_time` datetime NOT NULL COMMENT '结束请求时间',
  `duration` int NOT NULL COMMENT '执行时长',
  `result_code` int NOT NULL DEFAULT '0' COMMENT '结果码',
  `result_msg` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '结果提示',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_create_time` (`create_time`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='API 访问日志表';

CREATE TABLE `infra_api_error_log` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `trace_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '链路追踪编号',
  `user_id` bigint NOT NULL DEFAULT '0' COMMENT '用户编号',
  `user_type` tinyint NOT NULL DEFAULT '0' COMMENT '用户类型',
  `application_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '应用名',
  `request_method` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '请求方法名',
  `request_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '请求地址',
  `request_params` varchar(8000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '请求参数',
  `user_ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '用户 IP',
  `user_agent` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '浏览器 UA',
  `exception_time` datetime NOT NULL COMMENT '异常发生时间',
  `exception_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '异常名',
  `exception_message` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '异常导致的消息',
  `exception_root_cause_message` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '异常导致的根消息',
  `exception_stack_trace` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '异常的栈轨迹',
  `exception_class_name` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '异常发生的类全名',
  `exception_file_name` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '异常发生的类文件',
  `exception_method_name` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '异常发生的方法名',
  `exception_line_number` int NOT NULL COMMENT '异常发生的方法所在行',
  `process_status` tinyint NOT NULL COMMENT '处理状态',
  `process_time` datetime DEFAULT NULL COMMENT '处理时间',
  `process_user_id` int DEFAULT '0' COMMENT '处理用户编号',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_create_time` (`create_time`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='系统异常日志';

CREATE TABLE `infra_codegen_column` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `table_id` bigint NOT NULL COMMENT '表编号',
  `column_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '字段名',
  `data_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '字段类型',
  `column_comment` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '字段描述',
  `nullable` bit(1) NOT NULL COMMENT '是否允许为空',
  `primary_key` bit(1) NOT NULL COMMENT '是否主键',
  `ordinal_position` int NOT NULL COMMENT '排序',
  `java_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Java 属性类型',
  `java_field` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Java 属性名',
  `dict_type` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '字典类型',
  `example` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '数据示例',
  `create_operation` bit(1) NOT NULL COMMENT '是否为 Create 创建操作的字段',
  `update_operation` bit(1) NOT NULL COMMENT '是否为 Update 更新操作的字段',
  `list_operation` bit(1) NOT NULL COMMENT '是否为 List 查询操作的字段',
  `list_operation_condition` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '=' COMMENT 'List 查询操作的条件类型',
  `list_operation_result` bit(1) NOT NULL COMMENT '是否为 List 查询操作的返回字段',
  `html_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '显示类型',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_table_id` (`table_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='代码生成表字段定义';

CREATE TABLE `infra_codegen_table` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `data_source_config_id` bigint NOT NULL COMMENT '数据源配置的编号',
  `scene` tinyint NOT NULL DEFAULT '1' COMMENT '生成场景',
  `table_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '表名称',
  `table_comment` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '表描述',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `module_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模块名',
  `business_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务名',
  `class_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '类名称',
  `class_comment` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '类描述',
  `author` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '作者',
  `template_type` tinyint NOT NULL DEFAULT '1' COMMENT '模板类型',
  `front_type` tinyint NOT NULL COMMENT '前端类型',
  `parent_menu_id` bigint DEFAULT NULL COMMENT '父菜单编号',
  `master_table_id` bigint DEFAULT NULL COMMENT '主表的编号',
  `sub_join_column_id` bigint DEFAULT NULL COMMENT '子表关联主表的字段编号',
  `sub_join_many` bit(1) DEFAULT NULL COMMENT '主表与子表是否一对多',
  `tree_parent_column_id` bigint DEFAULT NULL COMMENT '树表的父字段编号',
  `tree_name_column_id` bigint DEFAULT NULL COMMENT '树表的名字字段编号',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='代码生成表定义';

CREATE TABLE `infra_config` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '参数主键',
  `category` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '参数分组',
  `type` tinyint NOT NULL COMMENT '参数类型',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '参数名称',
  `config_key` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '参数键名',
  `value` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '参数键值',
  `visible` bit(1) NOT NULL COMMENT '是否可见',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_config_key` (`config_key`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='参数配置表';

CREATE TABLE `infra_data_source_config` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键编号',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '参数名称',
  `url` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '数据源连接',
  `username` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '用户名',
  `password` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '密码',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='数据源配置表';

CREATE TABLE `infra_file` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '文件编号',
  `config_id` bigint DEFAULT NULL COMMENT '配置编号',
  `name` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '文件名',
  `path` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '文件路径',
  `url` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '文件 URL',
  `type` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '文件类型',
  `size` int NOT NULL COMMENT '文件大小',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='文件表';

CREATE TABLE `infra_file_config` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `name` varchar(63) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '配置名',
  `storage` tinyint NOT NULL COMMENT '存储器',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `master` bit(1) NOT NULL COMMENT '是否为主配置',
  `config` varchar(4096) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '存储配置',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='文件配置表';

CREATE TABLE `infra_file_content` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `config_id` bigint NOT NULL COMMENT '配置编号',
  `path` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '文件路径',
  `content` mediumblob NOT NULL COMMENT '文件内容',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_config_id_path` (`config_id`,`path`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='文件表';

CREATE TABLE `infra_job` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '任务编号',
  `name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '任务名称',
  `status` tinyint NOT NULL COMMENT '任务状态',
  `handler_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '处理器的名字',
  `handler_param` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '处理器的参数',
  `cron_expression` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'CRON 表达式',
  `retry_count` int NOT NULL DEFAULT '0' COMMENT '重试次数',
  `retry_interval` int NOT NULL DEFAULT '0' COMMENT '重试间隔',
  `monitor_timeout` int NOT NULL DEFAULT '0' COMMENT '监控超时时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='定时任务表';

CREATE TABLE `infra_job_log` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '日志编号',
  `job_id` bigint NOT NULL COMMENT '任务编号',
  `handler_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '处理器的名字',
  `handler_param` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '处理器的参数',
  `execute_index` tinyint NOT NULL DEFAULT '1' COMMENT '第几次执行',
  `begin_time` datetime NOT NULL COMMENT '开始执行时间',
  `end_time` datetime DEFAULT NULL COMMENT '结束执行时间',
  `duration` int DEFAULT NULL COMMENT '执行时长',
  `status` tinyint NOT NULL COMMENT '任务状态',
  `result` varchar(4000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '结果数据',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_job_id` (`job_id`) USING BTREE,
  KEY `idx_create_time` (`create_time`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='定时任务日志表';

CREATE TABLE `int_base_sync_binding` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `task_id` bigint NOT NULL,
  `object_key` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `target_id` bigint NOT NULL,
  `fingerprint` char(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `last_run_id` bigint NOT NULL,
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_int_base_sync_binding_source` (`tenant_id`,`task_id`,`object_key`,`source_key`),
  KEY `idx_int_base_sync_binding_target` (`tenant_id`,`task_id`,`object_key`,`target_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `int_base_sync_run` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `task_id` bigint NOT NULL,
  `request_key` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `preview` bit(1) NOT NULL,
  `task_code` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL,
  `connection_id` bigint NOT NULL,
  `batch_size` int NOT NULL,
  `max_rows` int NOT NULL,
  `read_count` bigint NOT NULL DEFAULT '0',
  `inserted_count` bigint NOT NULL DEFAULT '0',
  `updated_count` bigint NOT NULL DEFAULT '0',
  `unchanged_count` bigint NOT NULL DEFAULT '0',
  `deleted_count` bigint NOT NULL DEFAULT '0',
  `error_message` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `started_at` datetime(3) NOT NULL,
  `finished_at` datetime(3) DEFAULT NULL,
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_int_base_sync_run_request` (`tenant_id`,`task_id`,`request_key`),
  KEY `idx_int_base_sync_run_task` (`tenant_id`,`task_id`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `int_base_sync_task` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `task_code` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_system` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `connection_id` bigint NOT NULL,
  `batch_size` int NOT NULL,
  `max_rows` int NOT NULL,
  `active_run_id` bigint DEFAULT NULL,
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_int_base_sync_task` (`tenant_id`,`task_code`,`connection_id`),
  CONSTRAINT `ck_int_base_sync_batch_size` CHECK ((`batch_size` between 1 and 2000)),
  CONSTRAINT `ck_int_base_sync_max_rows` CHECK ((`max_rows` between 1 and 5000000))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

