  `product_sub_model` text,
  `product_sub_name` text,
  `quantity` decimal(24,6) DEFAULT NULL,
  `memo` text,
  `data_source` varchar(25) DEFAULT NULL,
  `creator` varchar(64) NOT NULL DEFAULT '',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) NOT NULL DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  KEY `idx_project` (`tenant_id`,`project_id`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `proj_project_risk` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `project_id` bigint NOT NULL COMMENT '所属项目编号',
  `title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '风险标题',
  `risk_level` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '风险等级 HIGH/MEDIUM/LOW',
  `risk_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '风险类型',
  `cause` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '风险原因',
  `impact` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '风险影响',
  `mitigation` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '缓解措施',
  `contingency` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '应急措施',
  `owner_user_id` bigint DEFAULT NULL COMMENT '风险负责人',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0已识别 1处理中 2已关闭 3已发生',
  `warning_threshold` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预警阈值',
  `review_notes` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '复核备注',
  `identified_at` datetime DEFAULT NULL COMMENT '识别时间',
  `closed_at` datetime DEFAULT NULL COMMENT '关闭时间',
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本号',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_pms_project_risk_project` (`project_id`),
  KEY `idx_pms_project_risk_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目风险';

CREATE TABLE `proj_project_site` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '关系ID',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  `project_id` bigint NOT NULL COMMENT '项目ID',
  `site_id` bigint NOT NULL COMMENT 'AST站点稳定ID（无物理外键）',
  `site_version_snapshot` int NOT NULL COMMENT '站点引用版本快照',
  `primary_site` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否主站点',
  `scope_status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ACTIVE' COMMENT '范围状态',
  `effective_from` datetime NOT NULL COMMENT '生效开始时间',
  `effective_to` datetime DEFAULT NULL COMMENT '失效时间',
  `site_code_snapshot` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '站点编码快照',
  `site_name_snapshot` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '站点名称快照',
  `address_snapshot` json DEFAULT NULL COMMENT '地址快照',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `current_primary_project_id` bigint GENERATED ALWAYS AS ((case when ((`primary_site` = 0x01) and (`effective_to` is null) and (`scope_status` = _utf8mb4'ACTIVE') and (`deleted` = 0x00)) then `project_id` else NULL end)) STORED,
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_proj_site_interval` (`tenant_id`,`project_id`,`site_id`,`effective_from`),
  UNIQUE KEY `uk_proj_current_primary` (`tenant_id`,`current_primary_project_id`),
  KEY `idx_proj_site_project` (`tenant_id`,`project_id`,`effective_to`),
  KEY `idx_proj_site_site` (`tenant_id`,`site_id`,`effective_to`),
  CONSTRAINT `chk_proj_site_interval` CHECK (((`effective_to` is null) or (`effective_to` > `effective_from`)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目实施站点时态关系';

CREATE TABLE `proj_project_split_item` (
  `id` bigint NOT NULL,
  `split_request_id` bigint NOT NULL,
  `client_item_key` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `project_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `business_level_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tree_sort` int NOT NULL DEFAULT '0',
  `department_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '办事处编码',
  `item_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `validation_result` json DEFAULT NULL,
  `created_project_id` bigint DEFAULT NULL,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  `template_revision_id` bigint DEFAULT NULL COMMENT '子项目显式选择的已发布模板版本',
  `template_selection_reason` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '模板匹配覆盖原因',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_proj_split_item_client` (`tenant_id`,`split_request_id`,`client_item_key`),
  KEY `idx_proj_split_item_request` (`tenant_id`,`split_request_id`,`tree_sort`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目拆分方案项';

CREATE TABLE `proj_project_split_request` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '项目拆分申请编号',
  `parent_project_id` bigint NOT NULL,
  `status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `draft_version` int NOT NULL DEFAULT '0',
  `parent_version` int DEFAULT NULL,
  `scope_version` bigint DEFAULT NULL,
  `tree_version` bigint DEFAULT NULL,
  `template_revision_id` bigint DEFAULT NULL,
  `preview_hash` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `validation_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `validation_summary` json DEFAULT NULL,
  `validated_at` datetime DEFAULT NULL,
  `applied_change_batch_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_proj_split_request_parent` (`tenant_id`,`parent_project_id`,`status`,`update_time`,`id`),
  CONSTRAINT `ck_proj_split_request_status` CHECK ((`status` in (_utf8mb4'DRAFT',_utf8mb4'APPLIED')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目拆分申请';

CREATE TABLE `proj_project_split_scope` (
  `id` bigint NOT NULL,
  `split_item_id` bigint NOT NULL,
  `order_line_id` bigint NOT NULL,
  `allocated_qty` decimal(18,6) NOT NULL,
  `department_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '办事处编码',
  `serial_no` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source_scope_version` bigint NOT NULL,
  `source_snapshot` json DEFAULT NULL,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_proj_split_scope_dimension` (`tenant_id`,`split_item_id`,`order_line_id`,`department_code`,`serial_no`),
  KEY `idx_proj_split_scope_item` (`tenant_id`,`split_item_id`,`id`),
  CONSTRAINT `ck_proj_split_scope_quantity` CHECK ((`allocated_qty` > 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目拆分范围发生时快照';

CREATE TABLE `proj_project_stage` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '阶段实例ID',
  `project_id` bigint NOT NULL COMMENT '项目ID（proj_project）',
  `stage_code` varchar(32) NOT NULL COMMENT '阶段码（S0～S6，实例化时冻结）',
  `name` varchar(128) NOT NULL COMMENT '阶段名称（快照）',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '阶段顺序（快照）',
  `entry_criteria` varchar(500) DEFAULT NULL COMMENT '准入条件说明（快照）',
  `exit_criteria` varchar(500) DEFAULT NULL COMMENT '准出条件说明（快照）',
  `source_definition_id` bigint DEFAULT NULL COMMENT '冻结来源：模板阶段定义ID（proj_project_template_stage_definition）',
  `status` varchar(32) NOT NULL DEFAULT 'PENDING' COMMENT '阶段实例状态（字典 pms_project_stage_status，S0 初始 ACTIVE）',
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `deleted_time` datetime DEFAULT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '0',
  `definition_revision_id` bigint DEFAULT NULL,
  `graph_version` bigint DEFAULT NULL,
  `start_node` bit(1) DEFAULT NULL,
  `terminal_node` bit(1) DEFAULT NULL,
  `active_stage_code` varchar(32) GENERATED ALWAYS AS ((case when (`deleted` = 0) then `stage_code` else NULL end)) VIRTUAL,
  `suggested_start_time` datetime(3) DEFAULT NULL COMMENT '建议开始时间',
  `suggested_end_time` datetime(3) DEFAULT NULL COMMENT '建议结束时间',
  `plan_start_time` datetime(3) DEFAULT NULL COMMENT '计划开始时间',
  `plan_end_time` datetime(3) DEFAULT NULL COMMENT '计划结束时间',
  `actual_start_time` datetime(3) DEFAULT NULL COMMENT '当前轮次阶段激活时间',
  `actual_end_time` datetime(3) DEFAULT NULL COMMENT '当前轮次阶段结束时间',
  `deviation_reason` varchar(500) DEFAULT NULL COMMENT '偏差原因',
  `responsible_role` varchar(64) DEFAULT NULL COMMENT '保留字段，暂不参与业务',
  `responsible_user_id` bigint DEFAULT NULL COMMENT '保留字段，暂不参与业务',
  `acceptance_time` datetime(3) DEFAULT NULL COMMENT '验收时间，与实际结束时间独立',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_proj_stage` (`tenant_id`,`project_id`,`active_stage_code`),
  KEY `idx_proj_stage_project` (`project_id`,`sort_order`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='项目阶段实例（实例化时从模板冻结）';

CREATE TABLE `proj_project_stage_execution_contract` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `project_id` bigint NOT NULL,
  `stage_id` bigint NOT NULL,
  `source_node_key` varchar(128) DEFAULT NULL,
  `graph_version` bigint NOT NULL,
  `definition_revision_id` bigint DEFAULT NULL,
  `work_binding_revision_id` bigint DEFAULT NULL,
  `binding_version` int NOT NULL,
  `binding_type` varchar(32) NOT NULL,
  `binding_snapshot` json NOT NULL,
  `permission_snapshot` json DEFAULT NULL,
  `permission_policy_revision_id` bigint DEFAULT NULL,
  `completion_rule_snapshot` json DEFAULT NULL,
  `completion_rule_revision_id` bigint DEFAULT NULL,
  `definition_snapshot` json NOT NULL,
  `effective_from` datetime NOT NULL,
  `effective_to` datetime DEFAULT NULL,
  `current_marker` tinyint GENERATED ALWAYS AS ((case when (`effective_to` is null) then 1 else NULL end)) STORED,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) NOT NULL DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) NOT NULL DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_psec_version` (`tenant_id`,`project_id`,`stage_id`,`binding_version`),
  UNIQUE KEY `uk_psec_current` (`tenant_id`,`project_id`,`stage_id`,`current_marker`),
  KEY `idx_psec_project` (`tenant_id`,`project_id`,`stage_id`),
  KEY `idx_psec_source_node` (`tenant_id`,`project_id`,`source_node_key`),
  CONSTRAINT `ck_psec_time` CHECK (((`effective_to` is null) or (`effective_to` >= `effective_from`))),
  CONSTRAINT `ck_psec_type` CHECK ((`binding_type` in (_utf8mb4'STAGE_NATIVE',_utf8mb4'BUSINESS_OBJECT',_utf8mb4'BUSINESS_COMPONENT',_utf8mb4'DYNAMIC_FORM',_utf8mb4'APPROVAL',_utf8mb4'COMPOSITE'))),
  CONSTRAINT `ck_psec_version` CHECK (((`binding_version` > 0) and (`graph_version` > 0)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `proj_project_stage_snapshot` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '阶段快照ID',
  `project_id` bigint NOT NULL COMMENT '项目ID',
  `stage_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '快照阶段编码',
  `snapshot_no` int NOT NULL COMMENT '同项目同阶段快照序号',
  `operation_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'PM-10动作类型：ROLLBACK/EXCEPTION_CLOSE/REOPEN',
  `before_stage` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '动作前阶段',
  `after_stage` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '动作后阶段',
  `before_lifecycle_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '动作前生命周期状态',
  `after_lifecycle_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '动作后生命周期状态',
  `before_assignment_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '动作前指派状态',
  `after_assignment_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '动作后指派状态',
  `reason_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '动作原因编码',
  `reason_detail` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '动作原因说明',
  `reassignment_requirement` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '回退后的重新指派要求',
  `business_basis` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '异常关闭业务依据',
  `legacy_items_json` json DEFAULT NULL COMMENT '异常关闭遗留事项快照',
  `guard_snapshot_json` json DEFAULT NULL COMMENT '提交使用的守卫令牌快照',
  `tree_version` bigint DEFAULT NULL COMMENT '守卫冻结的完整树版本',
  `provider_facts_json` json DEFAULT NULL COMMENT '守卫冻结的提供方事实版本与摘要',
  `related_snapshot_id` bigint DEFAULT NULL COMMENT '重开关联的异常关闭快照ID',
  `operation_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'PM-10稳定业务操作ID',
  `operator_user_id` bigint DEFAULT NULL COMMENT 'PM-10操作者用户ID',
  `operated_at` datetime(3) DEFAULT NULL COMMENT 'PM-10业务操作时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_proj_stage_snapshot_project_stage_no` (`tenant_id`,`project_id`,`stage_code`,`snapshot_no`),
  UNIQUE KEY `uk_proj_stage_snapshot_operation` (`tenant_id`,`operation_id`),
  KEY `idx_proj_stage_snapshot_project_time` (`tenant_id`,`project_id`,`operated_at`,`id`),
  KEY `idx_proj_stage_snapshot_related` (`tenant_id`,`project_id`,`related_snapshot_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PM-03、PM-10、EXE-06共享项目阶段快照（只追加）';

CREATE TABLE `proj_project_stage_transition` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `project_id` bigint NOT NULL,
  `template_revision_id` bigint NOT NULL,
  `source_transition_key` varchar(128) DEFAULT NULL,
  `source_transition_id` bigint DEFAULT NULL,
  `transition_code` varchar(128) NOT NULL,
  `transition_revision` bigint DEFAULT NULL,
  `from_stage_id` bigint NOT NULL,
  `to_stage_id` bigint NOT NULL,
  `priority` int NOT NULL,
  `is_default` bit(1) NOT NULL,
  `default_marker` tinyint GENERATED ALWAYS AS ((case when (`is_default` = 1) then 1 else NULL end)) STORED,
  `condition_rule_revision_id` bigint DEFAULT NULL,
  `condition_snapshot` json DEFAULT NULL,
  `graph_version` bigint NOT NULL,
  `creator` varchar(64) NOT NULL DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) NOT NULL DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_pst_code` (`tenant_id`,`project_id`,`graph_version`,`transition_code`),
  UNIQUE KEY `uk_pst_edge` (`tenant_id`,`project_id`,`graph_version`,`source_transition_id`),
  UNIQUE KEY `uk_pst_default` (`tenant_id`,`project_id`,`graph_version`,`from_stage_id`,`default_marker`),
  UNIQUE KEY `uk_pst_source_key_v2` (`tenant_id`,`project_id`,`graph_version`,`source_transition_key`),
  KEY `idx_pst_out` (`tenant_id`,`project_id`,`graph_version`,`from_stage_id`,`priority`),
  CONSTRAINT `ck_pst_condition_v2` CHECK (((`condition_rule_revision_id` is null) or (`condition_snapshot` is not null))),
  CONSTRAINT `ck_pst_default_v2` CHECK (((`is_default` in (0,1)) and ((`is_default` = 0) or ((`condition_rule_revision_id` is null) and (`condition_snapshot` is null))))),
  CONSTRAINT `ck_pst_self` CHECK ((`from_stage_id` <> `to_stage_id`)),
  CONSTRAINT `ck_pst_versions` CHECK (((`transition_revision` > 0) and (`graph_version` > 0)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `proj_project_task` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '任务实例ID',
  `project_id` bigint NOT NULL COMMENT '项目ID',
  `task_code` varchar(64) NOT NULL COMMENT '任务码（实例化时冻结，项目内唯一）',
  `name` varchar(128) NOT NULL COMMENT '任务名称（快照）',
  `parent_task_code` varchar(64) DEFAULT NULL COMMENT '父任务码（NULL=顶层）',
  `parent_task_id` bigint DEFAULT NULL COMMENT '当前直接父任务ID',
  `root_task_id` bigint NOT NULL COMMENT '当前根任务ID',
  `tree_depth` int unsigned NOT NULL DEFAULT '0' COMMENT '结构深度，根任务为0',
  `business_level_code` varchar(64) DEFAULT NULL COMMENT '业务层级编码，与结构深度无关',
  `milestone_id` bigint DEFAULT NULL COMMENT '关联里程碑实例ID',
  `plan_start_time` datetime(3) DEFAULT NULL COMMENT '计划开始时间',
  `plan_end_time` datetime(3) DEFAULT NULL COMMENT '计划结束时间',
  `actual_start_time` datetime(3) DEFAULT NULL COMMENT '实际开始时间',
  `actual_end_time` datetime(3) DEFAULT NULL COMMENT '实际结束时间',
  `progress` decimal(5,2) NOT NULL DEFAULT '0.00' COMMENT '任务进度0～100',
  `state_machine_revision_id` bigint NOT NULL COMMENT '创建时冻结的任务状态机版本ID',
  `stage_code` varchar(32) NOT NULL COMMENT '所属阶段码',
  `priority` int NOT NULL DEFAULT '2' COMMENT '优先级（快照）',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '排序（快照）',
  `estimated_hours` decimal(6,1) DEFAULT NULL COMMENT '预估工时（快照）',
  `satisfaction_timing` varchar(32) DEFAULT NULL COMMENT '满意度适用时点（快照，由 ACC-02 消费）',
  `acc_satisfaction_template_id` bigint DEFAULT NULL COMMENT 'ACC满意度模板ID',
  `template_revision_id` bigint DEFAULT NULL COMMENT 'ACC模板修订ID',
  `template_version` int DEFAULT NULL COMMENT 'ACC模板版本',
  `satisfaction_rule_version` varchar(64) DEFAULT NULL COMMENT '满意度规则版本',
  `satisfaction_threshold` decimal(7,2) DEFAULT NULL COMMENT '满意度达标阈值',
  `description` longtext COMMENT '任务说明，格式由description_format明确',
  `source_definition_id` bigint DEFAULT NULL COMMENT '冻结来源：模板任务定义ID（proj_project_template_task_definition）',
  `status` varchar(32) NOT NULL DEFAULT 'PENDING_ASSIGN' COMMENT '任务实例状态（字典 pms_project_task_status，初始待分配）',
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `deleted_time` datetime DEFAULT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '0',
  `description_format` varchar(16) NOT NULL DEFAULT 'PLAIN' COMMENT 'PLAIN保留旧纯文本；HTML为安全富文本',
  `active_task_code` varchar(64) GENERATED ALWAYS AS ((case when (`deleted` = 0) then `task_code` else NULL end)) VIRTUAL,
  `suggested_start_time` datetime(3) DEFAULT NULL COMMENT '建议开始时间',
  `suggested_end_time` datetime(3) DEFAULT NULL COMMENT '建议结束时间',
  `acceptance_time` datetime(3) DEFAULT NULL COMMENT '验收时间，与实际结束时间独立',
  `required_task` bit(1) NOT NULL DEFAULT b'1' COMMENT '任务必选标志，旧任务保持必选',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_proj_task_tenant_row` (`tenant_id`,`id`),
  UNIQUE KEY `uk_proj_task_tenant_project_row` (`tenant_id`,`project_id`,`id`),
  UNIQUE KEY `uk_proj_task` (`tenant_id`,`project_id`,`active_task_code`),
  KEY `idx_proj_task_parent` (`project_id`,`parent_task_code`),
  KEY `idx_proj_task_stage` (`project_id`,`stage_code`),
  KEY `idx_proj_task_direct_children` (`tenant_id`,`project_id`,`parent_task_id`,`sort_order`,`id`),
  KEY `idx_proj_task_root_depth` (`tenant_id`,`project_id`,`root_task_id`,`tree_depth`,`id`),
  KEY `idx_proj_task_business_level` (`tenant_id`,`project_id`,`business_level_code`,`sort_order`,`id`),
  KEY `fk_proj_task_state_revision` (`tenant_id`,`state_machine_revision_id`),
  CONSTRAINT `fk_proj_task_parent` FOREIGN KEY (`tenant_id`, `project_id`, `parent_task_id`) REFERENCES `proj_project_task` (`tenant_id`, `project_id`, `id`),
  CONSTRAINT `fk_proj_task_root` FOREIGN KEY (`tenant_id`, `project_id`, `root_task_id`) REFERENCES `proj_project_task` (`tenant_id`, `project_id`, `id`),
  CONSTRAINT `fk_proj_task_state_revision` FOREIGN KEY (`tenant_id`, `state_machine_revision_id`) REFERENCES `proj_task_state_machine_revision` (`tenant_id`, `id`),
  CONSTRAINT `chk_proj_task_plan_time` CHECK (((`plan_end_time` is null) or (`plan_start_time` is null) or (`plan_end_time` >= `plan_start_time`))),
  CONSTRAINT `chk_proj_task_progress` CHECK (((`progress` >= 0) and (`progress` <= 100)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='项目任务实例（初始待分配）';

CREATE TABLE `proj_project_task_assignment` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '任务责任区间ID',
  `project_task_id` bigint NOT NULL COMMENT '项目任务ID',
  `assignee_user_id` bigint NOT NULL COMMENT '负责人用户ID',
  `effective_from` datetime(3) NOT NULL COMMENT '责任开始时间',
  `effective_to` datetime(3) DEFAULT NULL COMMENT '责任结束时间',
  `current_marker` tinyint GENERATED ALWAYS AS ((case when (`effective_to` is null) then 1 else NULL end)) STORED,
  `assigned_by` bigint NOT NULL COMMENT '指派人用户ID',
  `reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '指派或转派原因',
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `deleted_time` datetime(3) DEFAULT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_proj_task_assignment_current` (`tenant_id`,`project_task_id`,`current_marker`),
  KEY `idx_proj_task_assignment_assignee` (`tenant_id`,`assignee_user_id`,`effective_to`,`project_task_id`),
  CONSTRAINT `fk_proj_task_assignment_task` FOREIGN KEY (`tenant_id`, `project_task_id`) REFERENCES `proj_project_task` (`tenant_id`, `id`),
  CONSTRAINT `chk_proj_task_assignment_dates` CHECK (((`effective_to` is null) or (`effective_to` >= `effective_from`)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目任务负责人责任区间';

CREATE TABLE `proj_project_task_completion_evaluation` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `project_task_id` bigint NOT NULL COMMENT 'ProjectTask逻辑引用',
  `execution_contract_id` bigint NOT NULL COMMENT '执行契约版本逻辑引用',
  `task_version` int unsigned NOT NULL COMMENT '判定时任务版本',
  `contract_version` int unsigned NOT NULL COMMENT '判定时契约版本',
  `evaluation_result_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '完成判定结果编码',
  `unmet_items_json` json DEFAULT NULL COMMENT '未满足项快照',
  `command_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '稳定命令ID',
  `idempotency_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '幂等键',
  `fact_context_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '外部事实Owner Context',
  `fact_object_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '外部事实对象类型',
  `fact_object_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '外部事实对象稳定键',
  `fact_version` bigint DEFAULT NULL COMMENT '外部事实版本',
  `gate_snapshot_ref` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '门禁快照引用',
  `business_facts_json` json DEFAULT NULL COMMENT '冻结业务关联事实及逐项完成判定证据',
  `evaluated_by` bigint NOT NULL COMMENT '判定操作者用户ID',
  `evaluated_at` datetime(3) NOT NULL COMMENT '判定时间',
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `deleted_time` datetime(3) DEFAULT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_proj_task_completion_evaluation` (`tenant_id`,`project_task_id`,`idempotency_key`),
  KEY `idx_proj_task_completion_evaluation_time` (`tenant_id`,`project_task_id`,`evaluated_at`,`id`),
  KEY `fk_proj_task_completion_evaluation_contract` (`tenant_id`,`execution_contract_id`),
  CONSTRAINT `fk_proj_task_completion_evaluation_contract` FOREIGN KEY (`tenant_id`, `execution_contract_id`) REFERENCES `proj_project_task_execution_contract` (`tenant_id`, `id`),
  CONSTRAINT `fk_proj_task_completion_evaluation_task` FOREIGN KEY (`tenant_id`, `project_task_id`) REFERENCES `proj_project_task` (`tenant_id`, `id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目任务完成判定追加事实';

CREATE TABLE `proj_project_task_execution_contract` (
  `id` bigint NOT NULL COMMENT '主键ID',
  `tenant_id` bigint NOT NULL COMMENT '租户ID',
  `project_task_id` bigint NOT NULL COMMENT 'ProjectTask逻辑引用',
  `source_node_key` varchar(128) DEFAULT NULL,
  `template_task_definition_id` bigint DEFAULT NULL COMMENT '来源模板任务定义逻辑引用',
  `work_binding_type_code` varchar(32) NOT NULL,
  `target_context_code` varchar(32) DEFAULT NULL,
  `target_object_type` varchar(64) DEFAULT NULL,
  `target_object_key` varchar(128) DEFAULT NULL,
  `component_key` varchar(128) DEFAULT NULL,
  `dynamic_form_revision_id` bigint DEFAULT NULL,
  `approval_instance_id` bigint DEFAULT NULL,
  `binding_parameter_snapshot` json NOT NULL COMMENT '冻结绑定参数与Schema版本',
  `binding_view_snapshot` json DEFAULT NULL,
  `permission_policy_ref` varchar(512) DEFAULT NULL,
  `permission_snapshot` json DEFAULT NULL,
  `completion_rule_type_code` varchar(32) NOT NULL,
  `completion_rule_snapshot` json NOT NULL COMMENT '冻结完成规则与Schema版本',
  `gate_ref` varchar(512) DEFAULT NULL,
  `source_definition_version` int unsigned NOT NULL,
  `contract_version` int unsigned NOT NULL,
  `effective_from` datetime(3) NOT NULL,
  `effective_to` datetime(3) DEFAULT NULL,
  `current_marker` tinyint GENERATED ALWAYS AS ((case when (`effective_to` is null) then 1 else NULL end)) STORED,
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '受控换绑乐观锁版本',
  `creator` varchar(64) DEFAULT '',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updater` varchar(64) DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `deleted_time` datetime(3) DEFAULT NULL,
  `definition_revision_id` bigint DEFAULT NULL,
  `work_binding_revision_id` bigint DEFAULT NULL,
  `permission_policy_revision_id` bigint DEFAULT NULL,
  `completion_rule_revision_id` bigint DEFAULT NULL,
  `definition_snapshot` json DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_project_task_execution_contract_tenant_row` (`tenant_id`,`id`),
  UNIQUE KEY `uk_project_task_execution_contract_version` (`tenant_id`,`project_task_id`,`contract_version`),
  UNIQUE KEY `uk_project_task_execution_contract_current` (`tenant_id`,`project_task_id`,`current_marker`),
  KEY `idx_project_task_execution_contract_target` (`tenant_id`,`target_context_code`,`target_object_type`,`target_object_key`),
  KEY `fk_project_task_execution_contract_definition` (`tenant_id`,`template_task_definition_id`),
  KEY `idx_ptc_source_node` (`tenant_id`,`project_task_id`,`source_node_key`),
  CONSTRAINT `fk_project_task_execution_contract_definition` FOREIGN KEY (`tenant_id`, `template_task_definition_id`) REFERENCES `proj_project_template_task_definition` (`tenant_id`, `id`),
  CONSTRAINT `chk_project_task_execution_contract_dates` CHECK (((`effective_to` is null) or (`effective_to` >= `effective_from`))),
  CONSTRAINT `chk_project_task_execution_contract_version` CHECK (((`source_definition_version` > 0) and (`contract_version` > 0))),
  CONSTRAINT `ck_ptc_permission_v2` CHECK (((`permission_policy_ref` is not null) or (`permission_snapshot` is not null)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='ProjectTask执行契约';

CREATE TABLE `proj_project_task_responsible` (
  `id` bigint NOT NULL,
  `project_id` bigint NOT NULL,
  `project_task_id` bigint NOT NULL,
  `user_id` bigint NOT NULL,
  `effective_from` datetime(6) NOT NULL,
  `effective_to` datetime(6) DEFAULT NULL,
  `assigned_by` bigint NOT NULL,
  `reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `current_marker` tinyint GENERATED ALWAYS AS ((case when ((`effective_to` is null) and (`deleted` = 0)) then 1 else NULL end)) STORED,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_proj_task_responsible_current` (`tenant_id`,`project_task_id`,`current_marker`),
  KEY `idx_proj_task_responsible_user` (`tenant_id`,`user_id`,`project_id`,`effective_to`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='任务协调负责人责任区间，不授予办理或审批权限';

CREATE TABLE `proj_project_template` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '模板ID',
  `code` varchar(64) NOT NULL COMMENT '模板编码（租户内唯一，系统保留编码受保护）',
  `name` varchar(128) NOT NULL COMMENT '模板名称',
  `status` varchar(16) NOT NULL DEFAULT 'DRAFT' COMMENT '状态：DRAFT草稿/ACTIVE生效/RETIRED停用',
  `match_priority` int NOT NULL DEFAULT '100' COMMENT '匹配优先级（数值小者先命中）',
  `description` varchar(500) DEFAULT NULL COMMENT '业务场景描述',
  `system_reserved` bit(1) NOT NULL DEFAULT b'0' COMMENT '系统保留编码标志：不得删除/复用/改义',
  `creator` varchar(64) DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `deleted_time` datetime DEFAULT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '0',
  `version` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_tenant_code` (`tenant_id`,`code`),
  KEY `idx_status_priority` (`status`,`match_priority`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='项目模板（身份/状态/优先级）';

CREATE TABLE `proj_project_template_deliverable_definition` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '交付件定义ID',
  `template_revision_id` bigint NOT NULL COMMENT '模板版本ID',
  `deliverable_code` varchar(64) NOT NULL COMMENT '交付件码（版本内唯一）',
  `name` varchar(128) NOT NULL COMMENT '交付件名称',
  `stage_code` varchar(32) NOT NULL COMMENT '所属阶段码',
  `task_code` varchar(64) DEFAULT NULL COMMENT '关联任务码（NULL=阶段级）',
  `required` bit(1) NOT NULL DEFAULT b'1' COMMENT '必需标志',
  `creator` varchar(64) DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `deleted_time` datetime DEFAULT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '0',
  `definition_revision_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_revision_deliverable` (`template_revision_id`,`deliverable_code`),
  KEY `idx_revision` (`template_revision_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='项目模板交付件定义';

CREATE TABLE `proj_project_template_gate_definition` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '门禁定义ID',
  `template_revision_id` bigint NOT NULL COMMENT '模板版本ID',
  `gate_code` varchar(64) NOT NULL COMMENT '门禁码（版本内唯一）',
  `name` varchar(128) NOT NULL COMMENT '门禁名称',
  `gate_type` varchar(16) NOT NULL COMMENT '类型：ENTRY准入/EXIT准出',
  `stage_code` varchar(32) NOT NULL COMMENT '所属阶段码',
  `description` varchar(500) DEFAULT NULL COMMENT '门禁说明',
  `creator` varchar(64) DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `deleted_time` datetime DEFAULT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '0',
  `definition_revision_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_revision_gate` (`template_revision_id`,`gate_code`),
  KEY `idx_revision` (`template_revision_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='项目模板门禁定义';

CREATE TABLE `proj_project_template_gate_reference` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '门禁引用ID',
  `template_revision_id` bigint NOT NULL COMMENT '模板版本ID',
  `gate_code` varchar(64) NOT NULL COMMENT '所属门禁码',
  `ref_type` varchar(16) NOT NULL COMMENT '引用类型：TASK/DELIVERABLE/STATE/PROCESS',
  `ref_code` varchar(64) NOT NULL COMMENT '引用编码',
  `ref_version` varchar(32) DEFAULT NULL COMMENT '引用版本（流程引用时使用）',
  `creator` varchar(64) DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `deleted_time` datetime DEFAULT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_revision_gate_ref` (`template_revision_id`,`gate_code`,`ref_type`,`ref_code`),
  KEY `idx_revision` (`template_revision_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='项目模板门禁引用行';

CREATE TABLE `proj_project_template_match_history` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '匹配决策历史ID',
  `project_id` bigint NOT NULL COMMENT '项目ID',
  `trigger_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'INITIAL_CREATE/SOURCE_CORRECTION/MANUAL_ADJUSTMENT',
  `record_purpose` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'CREATE_DECISION/IMPACT_EVALUATION',
  `input_origin` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'MANUAL/SOURCE',
  `snapshot_schema_version` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '四属性快照结构版本',
  `before_attribute_snapshot` json DEFAULT NULL COMMENT '变更前四属性快照；首次创建为空',
  `attribute_snapshot` json NOT NULL COMMENT '本次判定使用的四属性完整快照',
  `attribute_owner_snapshot` json NOT NULL COMMENT '四属性Owner快照',
  `source_owner` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源事实Owner',
  `source_system` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源系统；手工为MANUAL',
  `source_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源业务键',
  `source_event_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源事件ID',
  `source_version` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源版本',
  `source_occurred_at` datetime(3) DEFAULT NULL COMMENT '来源发生时间',
  `source_value_digest` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源原值SHA-256',
  `mapping_version` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源映射版本',
  `matcher_version` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模板匹配规则版本',
  `match_result` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'UNIQUE/NO_MATCH/MULTIPLE_MATCHES',
  `candidate_digest` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '排序后候选集合SHA-256',
  `decision_mode` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '首次创建AUTO_UNIQUE/EXPLICIT_SELECTION',
  `matched_template_id` bigint DEFAULT NULL COMMENT '唯一命中或显式选中模板ID',
  `matched_template_revision_id` bigint DEFAULT NULL COMMENT '唯一命中或显式选中模板修订ID',
  `frozen_template_revision_id` bigint NOT NULL COMMENT '项目当前冻结模板修订ID',
  `impact_result` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'NOT_APPLICABLE/NO_IMPACT/CANDIDATE_CHANGED/NO_MATCH/MULTIPLE_MATCHES',
  `operator_id` bigint NOT NULL COMMENT '认证用户或注册服务主体稳定ID',
  `change_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '去除首尾空白后的创建或调整原因',
  `occurred_at` datetime(3) NOT NULL COMMENT '业务发生时间',
  `recorded_at` datetime(3) NOT NULL COMMENT '事实写入时间',
  `idempotency_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '命令幂等键',
  `request_digest` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '请求摘要',
  `operation_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '稳定业务操作ID',
  `trace_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '可选技术Trace关联',
  `audit_log_id` bigint DEFAULT NULL COMMENT '可选系统操作日志关联',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_proj_template_match_history_operation` (`tenant_id`,`operation_id`),
  UNIQUE KEY `uk_proj_template_match_history_idempotency` (`tenant_id`,`project_id`,`idempotency_key`),
  KEY `idx_proj_template_match_history_project_time` (`tenant_id`,`project_id`,`occurred_at`,`id`),
  KEY `idx_proj_template_match_history_result` (`tenant_id`,`project_id`,`match_result`,`impact_result`,`occurred_at`),
  CONSTRAINT `ck_proj_template_match_history_decision` CHECK (((`decision_mode` is null) or (`decision_mode` in (_utf8mb4'AUTO_UNIQUE',_utf8mb4'EXPLICIT_SELECTION')))),
  CONSTRAINT `ck_proj_template_match_history_impact` CHECK ((`impact_result` in (_utf8mb4'NOT_APPLICABLE',_utf8mb4'NO_IMPACT',_utf8mb4'CANDIDATE_CHANGED',_utf8mb4'NO_MATCH',_utf8mb4'MULTIPLE_MATCHES'))),
  CONSTRAINT `ck_proj_template_match_history_matched` CHECK ((((`match_result` = _utf8mb4'UNIQUE') and (`matched_template_id` is not null) and (`matched_template_revision_id` is not null)) or ((`match_result` = _utf8mb4'MULTIPLE_MATCHES') and (`trigger_type` = _utf8mb4'INITIAL_CREATE') and (`decision_mode` = _utf8mb4'EXPLICIT_SELECTION') and (`matched_template_id` is not null) and (`matched_template_revision_id` is not null)) or ((`match_result` in (_utf8mb4'NO_MATCH',_utf8mb4'MULTIPLE_MATCHES')) and (`trigger_type` <> _utf8mb4'INITIAL_CREATE') and (`matched_template_id` is null) and (`matched_template_revision_id` is null)))),
  CONSTRAINT `ck_proj_template_match_history_origin` CHECK ((`input_origin` in (_utf8mb4'MANUAL',_utf8mb4'SOURCE'))),
  CONSTRAINT `ck_proj_template_match_history_purpose` CHECK ((`record_purpose` in (_utf8mb4'CREATE_DECISION',_utf8mb4'IMPACT_EVALUATION'))),
  CONSTRAINT `ck_proj_template_match_history_result` CHECK ((`match_result` in (_utf8mb4'UNIQUE',_utf8mb4'NO_MATCH',_utf8mb4'MULTIPLE_MATCHES'))),
  CONSTRAINT `ck_proj_template_match_history_source` CHECK (((`trigger_type` <> _utf8mb4'SOURCE_CORRECTION') or ((`input_origin` = _utf8mb4'SOURCE') and (`source_owner` is not null) and (`source_key` is not null) and (`source_event_id` is not null) and (`source_version` is not null) and (`source_occurred_at` is not null) and (`source_value_digest` is not null) and (`mapping_version` is not null)))),
  CONSTRAINT `ck_proj_template_match_history_trigger` CHECK ((`trigger_type` in (_utf8mb4'INITIAL_CREATE',_utf8mb4'SOURCE_CORRECTION',_utf8mb4'MANUAL_ADJUSTMENT'))),
  CONSTRAINT `ck_proj_template_match_history_trigger_purpose` CHECK ((((`trigger_type` = _utf8mb4'INITIAL_CREATE') and (`record_purpose` = _utf8mb4'CREATE_DECISION') and (`before_attribute_snapshot` is null) and (`impact_result` = _utf8mb4'NOT_APPLICABLE') and (`decision_mode` is not null)) or ((`trigger_type` in (_utf8mb4'SOURCE_CORRECTION',_utf8mb4'MANUAL_ADJUSTMENT')) and (`record_purpose` = _utf8mb4'IMPACT_EVALUATION') and (`before_attribute_snapshot` is not null) and (`decision_mode` is null))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PM-07模板匹配决策与影响评估永久历史（业务字段只插入不更新）';

CREATE TABLE `proj_project_template_milestone_definition` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '里程碑定义ID',
  `template_revision_id` bigint NOT NULL COMMENT '模板版本ID',
  `milestone_code` varchar(64) NOT NULL COMMENT '里程碑码（版本内唯一）',
  `name` varchar(128) NOT NULL COMMENT '里程碑名称',
  `stage_code` varchar(32) NOT NULL COMMENT '所属阶段码',
  `timing` varchar(64) DEFAULT NULL COMMENT '时点说明',
  `criteria` varchar(500) DEFAULT NULL COMMENT '达成标准',
  `creator` varchar(64) DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `deleted_time` datetime DEFAULT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '0',
  `definition_revision_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_revision_milestone` (`template_revision_id`,`milestone_code`),
  KEY `idx_revision` (`template_revision_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='项目模板里程碑定义';

CREATE TABLE `proj_project_template_revision` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '版本ID',
  `template_id` bigint NOT NULL COMMENT '模板ID',
  `revision_no` int NOT NULL DEFAULT '0' COMMENT '版本号（0=草稿工作副本，发布时递增冻结）',
  `status` varchar(16) NOT NULL DEFAULT 'DRAFT' COMMENT 'DRAFT草稿/PUBLISHED已发布',
  `signing_method` varchar(64) DEFAULT NULL COMMENT '签约方式（字典 pms_signing_method，NULL=不限）',
  `project_category` varchar(64) DEFAULT NULL COMMENT '项目类别（字典 pms_project_category，NULL=不限）',
  `implementation_method` varchar(64) DEFAULT NULL COMMENT '实施方式（字典 pms_implementation_method，NULL=不限）',
  `major_project_level` varchar(64) DEFAULT NULL COMMENT '重大项目级别（CRM来源属性映射，NULL=不限）',
  `process_definition_key` varchar(64) DEFAULT NULL COMMENT '模板级流程定义引用（仅存引用，不校验流程内部）',
  `process_definition_version` varchar(32) DEFAULT NULL COMMENT '流程定义版本引用',
  `validation_summary` varchar(1000) DEFAULT NULL COMMENT '最近一次发布校验结果摘要（留痕）',
  `published_by` varchar(64) DEFAULT NULL COMMENT '发布人',
  `published_time` datetime DEFAULT NULL COMMENT '发布时间',
  `creator` varchar(64) DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `deleted_time` datetime DEFAULT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '0',
  `definition_snapshot` json DEFAULT NULL,
  `designer_schema_version` int unsigned DEFAULT NULL,
  `designer_document` json DEFAULT NULL,
  `execution_schema_version` int unsigned DEFAULT NULL,
  `execution_snapshot` json DEFAULT NULL,
  `compiler_version` varchar(64) DEFAULT NULL,
  `snapshot_hash` char(64) DEFAULT NULL,
  `closure_policy` json DEFAULT NULL COMMENT 'Explicit NORMAL policy frozen at template publication',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_tenant_template_revision` (`tenant_id`,`template_id`,`revision_no`),
  KEY `idx_template_status_revision` (`template_id`,`status`,`revision_no`),
  CONSTRAINT `ck_project_template_revision_designer_v2` CHECK ((((`designer_document` is null) and (`designer_schema_version` is null)) or ((`designer_document` is not null) and (`designer_schema_version` > 0)))),
  CONSTRAINT `ck_project_template_revision_execution_v2` CHECK ((((`execution_snapshot` is null) and (`execution_schema_version` is null) and (`compiler_version` is null) and (`snapshot_hash` is null)) or ((`execution_snapshot` is not null) and (`execution_schema_version` > 0) and (`compiler_version` is not null) and regexp_like(`snapshot_hash`,_utf8mb4'^[0-9a-f]{64}$'))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='项目模板版本（四维条件+流程引用，发布后只读）';

CREATE TABLE `proj_project_template_stage_definition` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '阶段定义ID',
  `template_revision_id` bigint NOT NULL COMMENT '模板版本ID',
  `stage_code` varchar(32) NOT NULL COMMENT '阶段码（S0～S6）',
  `name` varchar(128) NOT NULL COMMENT '阶段名称',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '阶段顺序',
  `entry_criteria` varchar(500) DEFAULT NULL COMMENT '准入条件说明',
  `exit_criteria` varchar(500) DEFAULT NULL COMMENT '准出条件说明',
  `creator` varchar(64) DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `deleted_time` datetime DEFAULT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '0',
  `definition_revision_id` bigint DEFAULT NULL,
  `start_node` bit(1) DEFAULT NULL,
  `terminal_node` bit(1) DEFAULT NULL,
  `work_binding_revision_id` bigint DEFAULT NULL,
  `permission_policy_revision_id` bigint DEFAULT NULL,
  `completion_rule_revision_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_revision_stage` (`template_revision_id`,`stage_code`),
  KEY `idx_revision` (`template_revision_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='项目模板阶段定义';

CREATE TABLE `proj_project_template_task_definition` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `template_revision_id` bigint NOT NULL COMMENT '项目模板发布版本逻辑引用',
  `stage_definition_key` varchar(128) NOT NULL,
  `task_definition_key` varchar(128) NOT NULL,
  `parent_task_definition_key` varchar(128) DEFAULT NULL,
  `task_code` varchar(64) NOT NULL COMMENT '任务码（版本内唯一）',
  `name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '任务定义名称',
  `parent_task_code` varchar(64) DEFAULT NULL COMMENT '父任务码（NULL=顶层）',
  `stage_code` varchar(32) NOT NULL COMMENT '所属阶段码',
  `priority` int NOT NULL DEFAULT '2' COMMENT '优先级',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '排序',
  `estimated_hours` decimal(6,1) DEFAULT NULL COMMENT '预估工时',
  `satisfaction_timing` varchar(32) DEFAULT NULL COMMENT '满意度适用时点（NULL=不适用，由ACC-02消费）',
  `description` varchar(500) DEFAULT NULL COMMENT '任务说明',
  `work_binding_type_code` varchar(32) NOT NULL,
  `target_context_code` varchar(32) DEFAULT NULL,
  `target_object_type` varchar(64) DEFAULT NULL,
  `target_object_key` varchar(128) DEFAULT NULL,
  `component_key` varchar(128) DEFAULT NULL,
  `dynamic_form_revision_id` bigint DEFAULT NULL,
  `approval_definition_key` varchar(128) DEFAULT NULL,
  `binding_config` json NOT NULL COMMENT '受控绑定参数与Schema版本',
  `permission_policy_ref` varchar(512) NOT NULL,
  `completion_rule_type_code` varchar(32) NOT NULL,
  `completion_rule_config` json NOT NULL COMMENT '完成规则配置与Schema版本',
  `gate_ref` varchar(512) DEFAULT NULL,
  `definition_version` int unsigned NOT NULL,
  `creator` varchar(64) DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `deleted_time` datetime DEFAULT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户ID',
  `definition_revision_id` bigint DEFAULT NULL,
  `work_binding_revision_id` bigint DEFAULT NULL,
  `permission_policy_revision_id` bigint DEFAULT NULL,
  `completion_rule_revision_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_revision_task` (`template_revision_id`,`task_code`),
  UNIQUE KEY `uk_project_template_task_definition_tenant_row` (`tenant_id`,`id`),
  UNIQUE KEY `uk_project_template_task_definition_v18` (`tenant_id`,`template_revision_id`,`task_definition_key`),
  KEY `idx_revision` (`template_revision_id`),
  KEY `idx_project_template_task_definition_tree_v18` (`tenant_id`,`template_revision_id`,`stage_definition_key`,`parent_task_definition_key`,`sort_order`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='项目模板任务定义';

CREATE TABLE `proj_project_tree_change` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '项目树变更编号',
  `change_batch_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `operation_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `project_id` bigint NOT NULL,
  `parent_id_before` bigint DEFAULT NULL,
  `parent_id_after` bigint DEFAULT NULL,
