  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_srv_inspection_review_reference` (`tenant_id`,`review_reference`),
  KEY `idx_srv_inspection_review_revision_digest` (`tenant_id`,`revision_id`,`content_digest`,`reviewed_at`,`id`),
  CONSTRAINT `fk_srv_inspection_review_revision` FOREIGN KEY (`tenant_id`, `revision_id`) REFERENCES `srv_inspection_rule_revision` (`tenant_id`, `id`),
  CONSTRAINT `chk_srv_inspection_review_authorization_type` CHECK ((`authorization_type` = _utf8mb4'RBAC_PERMISSION')),
  CONSTRAINT `chk_srv_inspection_review_conclusion` CHECK ((`conclusion_code` in (_utf8mb4'PASSED',_utf8mb4'REJECTED'))),
  CONSTRAINT `chk_srv_inspection_review_digest` CHECK (((char_length(`content_digest`) = 64) and regexp_like(`content_digest`,_utf8mb4'^[0-9a-f]{64}$'))),
  CONSTRAINT `chk_srv_inspection_review_permission` CHECK ((`permission_code` = _utf8mb4'pms:inspection-rule:security-review'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

